window.pastExams={"2018":[{"number":1,"question":"Según lo establecido en la Constitución Española de 1978, no es misión de las Fuerzas Armadas:","options":{"A":"Garantizar la neutralidad de España.","B":"Garantizar la soberanía e independencia de España.","C":"Defender la integridad territorial de España.","D":"Defender el ordenamiento constitucional de España."},"correct":"A","explanation":"La Constitución (art. 8.1) encomienda a las Fuerzas Armadas garantizar la soberanía e independencia de España, defender su integridad territorial y el ordenamiento constitucional. Garantizar la neutralidad no aparece entre esas misiones.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":2,"question":"Señale cuál de los siguientes enunciados es falso, de acuerdo con la Constitución Española de 1978:","options":{"A":"La detención preventiva no podrá durar más de setenta y dos horas.","B":"La detención preventiva no podrá durar más del tiempo estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos.","C":"La ley regulará un procedimiento de \"habeas corpus\" para producir la inmediata puesta en libertad de toda persona detenida ilegalmente.","D":"Toda persona tiene derecho a la libertad y a la seguridad."},"correct":"C","explanation":"El artículo 17.4 dispone que el habeas corpus debe producir la inmediata puesta a disposición judicial de la persona detenida ilegalmente, no su puesta en libertad automática. Por eso la opción C es la falsa.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":3,"question":"Según lo establecido en la Constitución Española de 1978, aprobada la reforma constitucional por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten:","options":{"A":"Dentro de los diez días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.","B":"Dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.","C":"Dentro de los diez días siguientes a su aprobación, tres quintos de los miembros de cualquiera de las Cámaras.","D":"Dentro de los quince días siguientes a su aprobación, tres quintos de los miembros de cualquiera de las Cámaras."},"correct":"B","explanation":"En la reforma ordinaria del artículo 167.3, el referéndum se celebra si lo solicita, dentro de los quince días siguientes a la aprobación, una décima parte de los miembros de cualquiera de las Cámaras.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":4,"question":"Según lo establecido en la Constitución Española de 1978, la persona del Rey:","options":{"A":"Es inviolable, estando sujeta únicamente a responsabilidad por la comisión de actos estrictamente personales.","B":"Es inviolable y no está sujeta a responsabilidad.","C":"No es inviolable, estando sujeta a responsabilidad en los actos previstos en la Constitución.","D":"Es impecable y responsable."},"correct":"B","explanation":"El artículo 56.3 declara inviolable a la persona del Rey y establece que no está sujeta a responsabilidad. La opción B reproduce esa regla.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":5,"question":"Según lo establecido en la Constitución Española de 1978, son leyes orgánicas:","options":{"A":"Las que requieren el refrendo del Rey.","B":"Las que convocan elecciones generales.","C":"Las que refunden varios textos legales en uno solo.","D":"Las relativas al desarrollo de los derechos fundamentales y de las libertades públicas."},"correct":"D","explanation":"El artículo 81.1 reserva a ley orgánica el desarrollo de los derechos fundamentales y de las libertades públicas, además de las demás materias que enumera.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":6,"question":"Según lo establecido en la Constitución Española de 1978, para la presentación de proposiciones de ley por iniciativa popular se exigirá:","options":{"A":"No menos de 100.000 firmas acreditadas.","B":"No menos de 300.000 firmas acreditadas.","C":"No menos de 500.000 firmas acreditadas.","D":"Que se trate de materias tributarias, de carácter internacional o relativas a la prerrogativa de gracia."},"correct":"C","explanation":"El artículo 87.3 exige al menos 500.000 firmas acreditadas para una proposición de ley de iniciativa popular; también excluye ciertas materias, como indica la opción D.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":7,"question":"Según la Constitución Española de 1978, el Gobierno y cada uno de sus miembros están sometidos a las interpelaciones y preguntas que se le formulen en las Cámaras. Para esta clase de debate los Reglamentos establecerán un tiempo mínimo:","options":{"A":"Diario","B":"Semanal","C":"Mensual","D":"Anual"},"correct":"B","explanation":"El artículo 111.1 exige que los reglamentos de las Cámaras establezcan un tiempo mínimo semanal para este tipo de debate.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":8,"question":"Según la Constitución Española de 1978, la moción de censura deberá ser propuesta al menos por:","options":{"A":"la décima parte de los diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.","B":"la mayoría absoluta de los diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.","C":"la mayoría simple de los diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.","D":"la décima parte de los diputados, y habrá de incluir un candidato a la Presidencia del Congreso."},"correct":"A","explanation":"El artículo 113.2 exige que la moción de censura la proponga al menos una décima parte de los Diputados e incluya un candidato a la Presidencia del Gobierno.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":9,"question":"Según la Constitución española de 1978, los demás miembros del Gobierno:","options":{"A":"Serán nombrados por el Rey, a propuesta del Presidente de Congreso","B":"Serán nombrados por el Presidente del Congreso, a propuesta del Presidente de Gobierno","C":"Serán nombrados y separados por el Presidente de Gobierno, a propuesta del Presidente de Congreso","D":"Serán nombrados y separados por el Rey, a propuesta del Presidente de Gobierno"},"correct":"D","explanation":"Según el artículo 100, los demás miembros del Gobierno son nombrados y separados por el Rey, a propuesta de su Presidente.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":10,"question":"Según la Constitución española de 1978, el Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá y:","options":{"A":"quince miembros nombrados por el Rey por un período de cinco años","B":"veinte miembros nombrados por el Rey por un período de cinco años","C":"quince miembros nombrados por el Rey por un período de cuatro años","D":"veinte miembros nombrados por el Rey por un período de cuatro años"},"correct":"B","explanation":"El artículo 122.3 establece un Consejo General del Poder Judicial integrado por el Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por un período de cinco años.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":11,"question":"Según lo establecido en la Constitución española de 1978, la alteración de los límites provinciales, requiere:","options":{"A":"Aprobación por ley de Cortes Generales.","B":"Aprobación por ley de Cortes Generales, en forma de ley orgánica.","C":"Intervención de las Diputaciones y ley orgánica.","D":"Regulación por ley en los casos que proceda."},"correct":"B","explanation":"El artículo 141.1 dispone que cualquier alteración de los límites provinciales ha de aprobarse mediante ley orgánica.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":12,"question":"Según el artículo 153 de la Constitución Española de 1978, el control de la actividad de la Administración de las Comunidades Autónomas lo ejercerá:","options":{"A":"El Parlamento.","B":"El Rey.","C":"El Tribunal Superior de Justicia.","D":"La jurisdicción contencioso-administrativa."},"correct":"D","explanation":"El artículo 153.c atribuye a la jurisdicción contencioso-administrativa el control de la administración autónoma y sus normas reglamentarias.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":13,"question":"Según el artículo 140 de la Constitución Española de 1978 ¿Por qué tipo de sufragio se elige a los Concejales?","options":{"A":"Por sufragio universal, igual, libre, directo y secreto, en la forma establecida por ley.","B":"Por sufragio universal, igual, libre y secreto, en la forma establecida por el Gobierno.","C":"Por sufragio universal, igual, libre, y secreto, en la forma establecida por la Constitución.","D":"Por sufragio universal, igual, libre, y secreto, en la forma establecida por el derecho."},"correct":"A","explanation":"El artículo 140 establece que los concejales son elegidos por los vecinos mediante sufragio universal, igual, libre, directo y secreto.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":14,"question":"De conformidad con el Estatut d'Autonomia de la Comunitat Valenciana, la elaboración de la Carta de Derechos Sociales de la Comunidad Valenciana se llevará a cabo mediante:","options":{"A":"Una Ley de Les Corts.","B":"Ley Orgánica.","C":"Ley del Consell","D":"Ley del Estado"},"correct":"A","explanation":"El artículo 10.2 del Estatut establece que la Carta de Derechos Sociales se elaborará mediante una ley de Les Corts.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-17235"},{"number":15,"question":"¿Cuál de las siguientes afirmaciones es incorrecta, de acuerdo con lo establecido en el Estatuto de Autonomía de la Comunitat Valenciana?","options":{"A":"La Bandera de la Comunitat Valenciana es la tradicional Senyera compuesta por cuatro barras amarillas sobre fondo rojo, coronadas sobre franja azul junto al asta.","B":"Una Ley de Les Corts determinará la simbología heráldica propia de la Comunitat Valenciana que integra las tres provincias de Castellón, Valencia y Alicante.","C":"El idioma valenciano es el oficial en la Comunitat Valenciana, al igual que lo es el castellano, que es el idioma oficial del Estado. Todos tienen derecho a conocerlos y a usarlos y a recibir la enseñanza del, y en, idioma valenciano.","D":"Se delimitará por ley los territorios en los que predomine el uso de una y otra lengua, así como los que puedan ser exceptuados de la enseñanza y del uso de la lengua propia de la Comunitat Valenciana."},"correct":"A","explanation":"El artículo 4 describe la Senyera con cuatro barras rojas sobre fondo amarillo y una franja azul junto al asta. La opción A invierte los colores y por eso es la incorrecta.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-17235"},{"number":16,"question":"Según el artículo 23.4 del Estatuto de Autonomía de la Comunitat Valenciana, el mandato de los diputados a determinados efectos finalizará:","options":{"A":"Cuatro años después de las elecciones o el día de la disolución de la Cámara por el President.","B":"El día antes de las elecciones.","C":"El día que establezca el decreto del President por el que se disuelven Les Corts.","D":"El día antes de que se conformen las nuevas Corts."},"correct":"B","explanation":"El artículo 23.4 fija, para los efectos que allí señala, el fin del mandato de los diputados el día anterior a las elecciones.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-17235"},{"number":17,"question":"Según el artículo 29 del Estatut d'Autonomia, el Consell es el órgano colegiado de gobierno de la Generalitat:","options":{"A":"Que ostenta únicamente la potestad ejecutiva.","B":"Que ostenta la potestad ejecutiva y reglamentaria.","C":"Que únicamente ostenta la potestad reglamentaria.","D":"Que ostenta la potestad ejecutiva, reglamentaria y judicial."},"correct":"B","explanation":"El artículo 29 define el Consell como órgano colegiado que ejerce la potestad ejecutiva y reglamentaria.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-17235"},{"number":18,"question":"Según el Estatut d'Autonomia, la iniciativa de la reforma del Estatuto corresponde:","options":{"A":"Al Consell, a una tercera parte de los miembros de Les Corts, a dos grupos parlamentarios, al Congreso de los Diputados o al Senado.","B":"Al Consell, a una tercera parte de los miembros de Les Corts, a tres grupos parlamentarios o a las Cortes Generales.","C":"Al Consell, a una tercera parte de los miembros de Les Corts, a dos grupos parlamentarios o a las Cortes Generales.","D":"Solo al Consell en pleno por mayoría absoluta."},"correct":"Anulada","explanation":"La pregunta figura anulada en la plantilla del examen, así que no se debe puntuar ninguna opción. Consulta el artículo 81 del Estatut y la plantilla original antes de usarla como pregunta válida.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-17235"},{"number":19,"question":"De conformidad con lo establecido en la Ley 5/1983, de 30 de diciembre, del Consell, para la elección del President de la Generalitat en primera votación:","options":{"A":"Se requiere del consenso de todos los grupos políticos con representación parlamentaria de les Corts.","B":"Hace falta mayoría de tres quintos de los miembros de derecho de Les Corts.","C":"Hace falta mayoría absoluta de los miembros de derecho de Les Corts.","D":"Hace falta mayoría simple de los miembros de derecho de Les Corts."},"correct":"C","explanation":"La regla de elección de la Presidencia exige mayoría absoluta de los miembros de derecho de Les Corts en primera votación; si no se alcanza, se aplica la regla de segunda votación prevista en la normativa.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":20,"question":"Entre las funciones que la Ley 5/1983, de 30 de diciembre, del Consell, atribuye al Presidente de la Generalitat, está la de:","options":{"A":"Designar representante de la Comunitat Valenciana en el Patronato del Misteri d'Elx","B":"Designar representante de la Comunitat Valenciana en el Patronato del Archivo General de Indias","C":"Designar representante de la Comunitat Valenciana en el Real Patronato del Museo Nacional de El Prado.","D":"Designar representante de la Comunitat Valenciana en el Patronato del Archivo de la Corona de Aragón."},"correct":"D","explanation":"La Ley 5/1983 incluye entre las funciones presidenciales la designación de la representación valenciana en el Patronato del Archivo de la Corona de Aragón; corresponde la opción D.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":21,"question":"De conformidad con lo establecido en la Ley 5/1983, de 30 de diciembre, del Consell, la Comisión de Secretarios Autonómicos y Subsecretarios:","options":{"A":"Será presidida por el miembro del Consell que ostente la condición de portavoz del Consell.","B":"Será presidida por el miembro del Consell que ostente la condición de secretario del Consell.","C":"Será presidida por el miembro del Consell que designado al efecto por el President de la Generalitat.","D":"Al tratarse de un órgano colegiado carece de presidencia."},"correct":"B","explanation":"La Ley 5/1983 regula esta Comisión y atribuye su presidencia al miembro del Consell que ostenta la Secretaría del Consell.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":22,"question":"De conformidad con lo establecido en la Ley 5/1983, de 30 de diciembre, del Consell, ejercer las facultades ordinarias en materia de contratación administrativa dentro de los límites legales presupuestarios, es función propia de:","options":{"A":"Los Directores Generales","B":"Los Subsecretarios","C":"Los Secretarios Autonómicos","D":"Los Consellers."},"correct":"D","explanation":"La Ley 5/1983 atribuye a los consellers, como jefes de sus departamentos, las facultades ordinarias de contratación dentro de los límites legales y presupuestarios.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":23,"question":"De conformidad con lo establecido en la Ley 5/1983 de 30 de diciembre, del Consell, el nivel directivo de las consellerias lo integran:","options":{"A":"El Conseller y los secretarios autonómicos","B":"Los secretarios autonómicos y los subsecretarios","C":"Los subsecretarios y los secretarios generales Administrativos","D":"Los subsecretarios, directores generales y demás altos cargos que ostenten el rango de director general."},"correct":"D","explanation":"La Ley 5/1983 integra el nivel directivo de las consellerias con subsecretarios, directores generales y otros altos cargos con rango de director general.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":24,"question":"De conformidad con lo establecido en la Ley 5/1983 de 30 de diciembre, del Consell, el nivel administrativo de una Conselleria se organiza en:","options":{"A":"áreas, servicios, secciones, unidades y negociados.","B":"subdirecciones generales, servicios, secciones, unidades y negociados.","C":"áreas, servicios y negociados.","D":"subdirecciones generales, secciones y unidades."},"correct":"B","explanation":"La Ley 5/1983 organiza el nivel administrativo en subdirecciones generales, servicios, secciones, unidades y negociados.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":25,"question":"De acuerdo con lo establecido en el Tratado de Funcionamiento de la Unión Europea, para ejercer las competencias de la Unión, las instituciones adoptarán:","options":{"A":"reglamentos, directivas, decisiones, recomendaciones y dictámenes.","B":"directivas y decisiones.","C":"reglamentos, decisiones y dictámenes.","D":"reglamentos, directivas, decisiones y dictámenes."},"correct":"A","explanation":"El artículo 288 del TFUE enumera cinco tipos de actos: reglamentos, directivas, decisiones, recomendaciones y dictámenes.","page":null,"topicNumber":7,"officialSource":"https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012E/TXT"},{"number":26,"question":"De acuerdo con lo establecido en el Tratado de Funcionamiento de la Unión Europea, los reglamentos de la Unión Europea:","options":{"A":"son actos normativos no aplicables a los estados miembros.","B":"son actos legislativos vinculantes, obligatorios en todos sus elementos y directamente aplicables en cada Estado miembro.","C":"son actos legislativos en los cuales se establecen objetivos que todos los países de la UE deben cumplir","D":"son actos administrativos de trámite de la Unión Europea."},"correct":"B","explanation":"El artículo 288 del TFUE establece que el reglamento tiene alcance general, es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro.","page":null,"topicNumber":7,"officialSource":"https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012E/TXT"},{"number":27,"question":"Los Tratados de la Unión Europea:","options":{"A":"Forman parte del derecho primario de la Unión Europea.","B":"Forman parte del Derecho derivado de la Unión Europea.","C":"No forman parte del derecho primario de la Unión Europea.","D":"Ninguna respuesta es correcta."},"correct":"A","explanation":"Los Tratados constitutivos y sus modificaciones forman parte del Derecho primario de la Unión; los actos derivados son los que adoptan las instituciones en virtud de los Tratados.","page":null,"topicNumber":7,"officialSource":"https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012M/TXT"},{"number":28,"question":"Según el artículo 10 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán:","options":{"A":"revisables","B":"de sentencia firme","C":"anulables","D":"nulos y sin efecto"},"correct":"D","explanation":"El artículo 10 de la LO 3/2007 declara nulos y sin efecto los actos y cláusulas de negocios jurídicos que constituyan o causen discriminación por razón de sexo.","page":null,"topicNumber":8,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115"},{"number":29,"question":"La Ley 9/2003, de 2 de Abril de la Generalitat, para la igualdad de mujeres y hombres, será de aplicación:","options":{"A":"En el ámbito de la administración de la Generalitat Valenciana.","B":"En el ámbito de la administración de la Generalitat Valenciana, en todas las actuaciones referidas a la planificación y ejecución de actuaciones en materia de igualdad de oportunidades entre mujeres y hombres.","C":"en todo el ámbito territorial de la Comunidad Valenciana, en todas las actuaciones referidas a la planificación, acciones, gestión y ejecución de actuaciones en materia de igualdad de oportunidades entre mujeres y hombres.","D":"en todo el ámbito territorial nacional."},"correct":"C","explanation":"El artículo 3 de la Ley valenciana 9/2003 extiende su aplicación a todo el territorio valenciano y a actuaciones de planificación, acción, gestión y ejecución en igualdad de oportunidades.","page":null,"topicNumber":8,"officialSource":"https://dogv.gva.es/es/eli/es-vc/l/2003/04/02/9/con"},{"number":30,"question":"Según la Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género, la violencia de género a que se refiere la presente Ley comprende:","options":{"A":"todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.","B":"todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones, pero no la privación arbitraria de libertad.","C":"solo los actos de violencia física, incluidas las agresiones a la libertad sexual.","D":"todo acto de violencia física y psicológica, sin incluir las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad."},"correct":"A","explanation":"El artículo 1.3 de la LO 1/2004 incluye violencia física y psicológica, agresiones a la libertad sexual, amenazas, coacciones y privación arbitraria de libertad.","page":null,"topicNumber":8,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760"},{"number":31,"question":"De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, la tramitación de urgencia se podrá acordar:","options":{"A":"Solo de oficio, se reducirán a la mitad los plazos establecidos para el procedimiento ordinario, cuando medien razones de interés público.","B":"Únicamente a petición del interesado, se reducirán a la mitad los plazos establecidos para el procedimiento ordinario, cuando lo dicte el órgano administrativo.","C":"De oficio o a petición del interesado, se reducirán a la mitad los plazos establecidos para el procedimiento ordinario.","D":"De oficio o a petición del interesado, se reducirán a más de la mitad los plazos establecidos para el procedimiento ordinario."},"correct":"C","explanation":"El artículo 33 de la Ley 39/2015 permite acordar la tramitación urgente de oficio o a petición de la persona interesada cuando lo aconsejen razones de interés público. Reduce a la mitad los plazos, salvo los de presentación de solicitudes y recursos.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":32,"question":"Según la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son:","options":{"A":"Hábiles excluyéndose del cómputo los domingos.","B":"Hábiles excluyéndose del cómputo los domingos y festivos.","C":"Hábiles excluyéndose del cómputo los sábados, domingos y lo declarados festivos.","D":"Naturales."},"correct":"C","explanation":"El artículo 30.2 de la Ley 39/2015 dispone que los plazos señalados por días son hábiles; se excluyen sábados, domingos y festivos, salvo que una ley o el Derecho de la UE establezcan otro cómputo.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":33,"question":"Según la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, es INCORRECTO que:","options":{"A":"Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se notifiquen, salvo que en ellos se disponga otra cosa.","B":"La eficacia quedará demorada cuando así lo exija el contenido del acto.","C":"La eficacia quedará demorada cuando esté supeditada a la publicación del acto.","D":"La eficacia quedará demorada cuando esté supeditada a aprobación superior."},"correct":"A","explanation":"El artículo 39.2 establece como regla que los actos producen efectos desde la fecha en que se dictan, salvo que se disponga otra cosa. Por eso es incorrecto afirmar que sus efectos comienzan siempre con la notificación.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":34,"question":"Según el artículo 35 de la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas serán motivados, con sucinta referencia de hechos y fundamentos de derecho:","options":{"A":"Los actos que otorguen derechos subjetivos o intereses legítimos.","B":"Los actos que acuerden el inicio del procedimiento por la imposibilidad material de continuarlo por causas sobrevenidas, así como los que acuerden el desistimiento por la Administración en procedimientos iniciados de parte.","C":"Los actos que acepten pruebas propuestas por los interesados.","D":"Los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos."},"correct":"D","explanation":"El artículo 35.1.c exige motivar los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":35,"question":"De conformidad con lo dispuesto en el artículo 37.1 de la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"Las resoluciones administrativas de carácter particular no podrán vulnerar lo establecido en una disposición de carácter general, aunque aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.","B":"Las resoluciones administrativas de carácter particular no podrán vulnerar lo establecido en una disposición de carácter general, siempre que aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.","C":"Las resoluciones administrativas de carácter particular podrán vulnerar lo establecido en una disposición de carácter general, siempre que aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.","D":"Las resoluciones administrativas de carácter particular podrán vulnerar en cualquier caso lo establecido en una disposición de carácter general."},"correct":"A","explanation":"El artículo 37.1 prohíbe que una resolución particular vulnere una disposición general, aunque aquella proceda de un órgano de igual o superior jerarquía.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":36,"question":"Señale la respuesta correcta, en relación a la práctica de las notificaciones administrativas, regulada en el artículo 41 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"En ningún caso se efectuarán por medios no electrónicos las notificaciones en las que el acto a notificar vaya acompañado de elementos que no sean susceptibles de conversión en formato electrónico.","B":"En los procedimientos iniciados a solicitud de los interesados, a los solos efectos de su iniciación, las Administraciones Públicas podrán recabar, mediante consulta a las bases de datos del Instituto Nacional de Estadística, los datos sobre el domicilio del interesado recogidos en el Padrón Municipal, remitidos por las Entidades Locales en aplicación de lo previsto en la Ley 7/1985, de 2 de abril, reguladora de las Bases del Régimen Local.","C":"Con independencia de que la notificación se realice en papel o por medios electrónicos, las Administraciones Públicas enviarán un aviso al dispositivo electrónico y/o a la dirección del correo electrónico del interesado que éste haya comunicado, informándole de la puesta a disposición de una notificación en la sede electrónica de la Administración u Organismo correspondiente o en la dirección electrónica habilitada única.","D":"La falta de la práctica del aviso al dispositivo electrónico y/o dirección de correo electrónico del interesado informándole de la puesta a disposición de una notificación en la sede electónica de la Administración, determina la invalidez de la notificación."},"correct":"C","explanation":"El artículo 41 exige cursar la notificación dentro del plazo legal e informar de su puesta a disposición. La falta de esa información complementaria no determina por sí sola la invalidez del acto notificado.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":37,"question":"De conformidad con lo dispuesto en el artículo 49.1 de la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"La nulidad o anulabilidad de un acto implicará la de los sucesivos en el procedimiento.","B":"La nulidad o anulabilidad de un acto implicará la de los sucesivos en el procedimiento, sean o no independientes del primero.","C":"La nulidad o anulabilidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero.","D":"La nulidad o anulabilidad de un acto no implicará, en ningún caso, la de los sucesivos en el procedimiento."},"correct":"C","explanation":"El artículo 49.1 limita la extensión de la nulidad: no alcanza a los actos y trámites sucesivos que sean independientes del primero declarado nulo.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":38,"question":"Según establece la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico son:","options":{"A":"Anulables, excepto los que incurran en la desviación de poder.","B":"Nulos de pleno derecho, excepto los que incurran en la desviación de poder.","C":"Anulables, incluso los que incurran en la desviación de poder.","D":"Nulos de pleno derecho, incluso los que incurran en la desviación de poder."},"correct":"C","explanation":"El artículo 48.1 califica como anulables los actos que incurran en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder, salvo que concurra una causa de nulidad de pleno derecho.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":39,"question":"Según la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, la realización de actuaciones administrativas fuera del tiempo establecido para ellas:","options":{"A":"Implicará la nulidad de pleno derecho, en todo caso.","B":"Implicará la anulabilidad del acto, en todo caso.","C":"Sólo implicará la anulabilidad del acto cuando así lo imponga la naturaleza del término o plazo.","D":"Implicará la nulidad de pleno derecho cuando dé lugar a la indefensión de los interesados."},"correct":"C","explanation":"El artículo 48.3 indica que actuar fuera de plazo solo causa anulabilidad cuando lo imponga la naturaleza del término o plazo.","page":null,"topicNumber":11,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":40,"question":"Conforme a lo establecido en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, salvo que reste menos para su tramitación ordinaria, los procedimientos administrativos tramitados de manera simplificada deberán ser resueltos en:","options":{"A":"15 días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.","B":"30 días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.","C":"45 días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.","D":"60 días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento."},"correct":"B","explanation":"El artículo 96.6 fija treinta días para resolver el procedimiento simplificado, salvo que reste menos tiempo para la tramitación ordinaria.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":41,"question":"Según lo dispuesto en el artículo 95 de la Ley 39/2015, del procedimiento administrativo común de las administraciones públicas sobre la caducidad del procedimiento, señale la opción correcta:","options":{"A":"La caducidad no producirá por sí sola la prescripción de las acciones del particular o de la Administración, pero los procedimientos caducados interrumpirán el plazo de prescripción.","B":"La caducidad no producirá por sí sola la prescripción de las acciones del particular o de la Administración, pero los procedimientos caducados no interrumpirán el plazo de prescripción.","C":"La caducidad producirá por sí sola la prescripción de las acciones del particular o de la Administración, pero los procedimientos caducados no interrumpirán el plazo de prescripción","D":"Todas las respuestas son correctas."},"correct":"B","explanation":"El artículo 95.3 señala que la caducidad no produce por sí sola la prescripción, pero el procedimiento caducado no interrumpe el plazo de prescripción.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":42,"question":"De conformidad con lo establecido en la Ley 39/2015 del Procedimiento Administrativo Común de las Administraciones Públicas, las Administraciones Públicas podrán rectificar los errores materiales, de hecho, o aritméticos existentes en sus actos:","options":{"A":"Mientras no haya transcurrido el plazo de prescripción, de oficio.","B":"En cualquier momento, y únicamente de oficio.","C":"Mientras no haya transcurrido el plazo de prescripción, de oficio o a instancia de los interesados.","D":"En cualquier momento, de oficio o a instancia de los interesados."},"correct":"D","explanation":"El artículo 109.2 permite rectificar en cualquier momento, de oficio o a solicitud de las personas interesadas, errores materiales, de hecho o aritméticos.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":43,"question":"Según la Ley 39/2015, del Procedimiento Administrativo Común de las Administraciones Públicas, el recurso de alzada podrá interponerse:","options":{"A":"Ante el órgano que dictó el acto que se impugna","B":"Ante el órgano competente para resolver el acto que se impugna.","C":"Ante el órgano que dictó el acto que se impugna o ante el competente para resolverlo.","D":"Ante el orden jurisdiccional contencioso administrativo."},"correct":"C","explanation":"El artículo 121.2 permite interponer el recurso de alzada ante el órgano que dictó el acto o ante el competente para resolverlo.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":44,"question":"De conformidad con lo establecido por la Ley 39/2015, del Procedimiento Administrativo Común de las Administraciones Públicas, la declaración de lesividad:","options":{"A":"Podrá ser objeto de los recursos que se estimen procedentes.","B":"Podrá ser recurrido en alzada.","C":"Podrá ser objeto de recurso de reposición.","D":"No será susceptible de recurso."},"correct":"D","explanation":"El artículo 107.2 establece que la declaración de lesividad no es susceptible de recurso, sin perjuicio de su examen al impugnar el acto en vía contenciosa.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":45,"question":"Conforme a lo establecido por la Ley 39/2015, del procedimiento administrativo común de las Administraciones Públicas, el procedimiento, sometido al principio de celeridad, se impulsará de oficio en todos sus trámites y:","options":{"A":"A través de medios electrónicos, respetando los principios de transparencia, publicidad y buena fe.","B":"A través de medios electrónicos respetando los principios de transparencia y publicidad.","C":"A través de medios no electrónicos, respetando los principios de transparencia, publicidad y buena fe.","D":"A través de medios no electrónicos, respetando los principios de transparencia y publicidad."},"correct":"B","explanation":"El artículo 71 dispone que el procedimiento se impulsa de oficio en todos sus trámites y se tramita por medios electrónicos, respetando los principios de transparencia y publicidad.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":46,"question":"De conformidad con lo establecido en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la creación de cualquier órgano administrativo exigirá, al menos, el cumplimiento de (señala la incorrecta):","options":{"A":"Denominación y establecimiento de sus recursos humanos necesarios.","B":"Determinación de su forma de integración en la Administración Pública de que se trate y su dependencia jerárquica.","C":"Delimitación de sus funciones y competencias.","D":"Dotación de los créditos necesarios para su puesta en marcha y funcionamiento."},"correct":"A","explanation":"El artículo 5.3 de la Ley 40/2015 exige definir la integración y dependencia jerárquica, delimitar funciones y competencias y dotar créditos. No exige como requisito mínimo establecer los recursos humanos necesarios.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":47,"question":"De acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la delegación de competencias, la encomienda de gestión, la delegación de firma y la suplencia:","options":{"A":"Suponen alteración de la titularidad de la competencia y de los elementos determinantes de su ejercicio que en cada caso se prevén.","B":"No suponen alteración de la titularidad de la competencia, aunque sí de los elementos determinantes de su ejercicio que en cada caso se prevén.","C":"No suponen alteración de la titularidad de la competencia ni de los elementos determinantes de su ejercicio que en cada caso se prevén.","D":"Suponen alteración de la titularidad de la competencia, pero no de los elementos determinantes de su ejercicio que en cada caso se prevén."},"correct":"B","explanation":"El artículo 8.1 aclara que delegación, encomienda de gestión, delegación de firma y suplencia no alteran la titularidad de la competencia, aunque pueden afectar a sus elementos de ejercicio.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":48,"question":"De conformidad con lo establecido en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, se considerará incluido entre los medios electrónicos válidos para que los órganos colegiados celebren sesiones a distancia (señala la incorrecta):","options":{"A":"El correo electrónico.","B":"El portal web del departamento competente.","C":"Las audioconferencias.","D":"Las videoconferencias."},"correct":"B","explanation":"El artículo 17.1 permite sesiones a distancia mediante medios electrónicos, como correo electrónico, audioconferencia o videoconferencia. Un portal web departamental no figura entre esos medios.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":49,"question":"De conformidad con lo establecido en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público respecto a la delegación de competencias, señala la correcta:","options":{"A":"Las resoluciones administrativas que se adopten por delegación indicarán expresamente esta circunstancia y se considerarán dictadas por el órgano delegado.","B":"Salvo autorización expresa de una Ley, podrán delegarse las competencias que se ejerzan por delegación.","C":"La delegación una vez que el órgano delegante la haya conferido no será revocable.","D":"El acuerdo de delegación de aquellas competencias atribuidas a órganos colegiados, para cuyo ejercicio se requiera un quórum o mayoría especial, deberá adoptarse observando, en todo caso, dicho quórum o mayoría."},"correct":"D","explanation":"El artículo 9.5 exige respetar el quórum o la mayoría especial al acordar la delegación de competencias atribuidas a órganos colegiados cuyo ejercicio los requiera.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":50,"question":"Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, si alguna disposición atribuye la competencia a una Administración, sin especificar el órgano que debe ejercerla, se entenderá que la facultad de instruir y resolver los expedientes corresponde a los órganos:","options":{"A":"Inferiores competentes por razón de la materia y del territorio.","B":"Superiores competentes por razón de la materia y del territorio.","C":"Que establezca el órgano superior competente por razón de la materia y del territorio.","D":"Ninguna de las respuestas es correcta."},"correct":"A","explanation":"El artículo 8.3 atribuye la instrucción y resolución a los órganos inferiores competentes por materia y territorio cuando la norma atribuye la competencia a una Administración sin identificar órgano.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":51,"question":"Según la Ley 9/2017, de Contratos del Sector Público, el contrato que contenga prestaciones correspondientes a otro u otros de distinta clase, es un:","options":{"A":"Contrato de obra.","B":"Contrato de suministro.","C":"Contrato de servicios.","D":"Contrato mixto."},"correct":"D","explanation":"El artículo 18 define como mixto el contrato que contiene prestaciones correspondientes a otro u otros contratos de distinta clase.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":52,"question":"La Ley 9/2017 de Contratos del Sector Público, respecto a fraccionar un contrato con la finalidad de disminuir la cuantía del mismo, y eludir así los requisitos de publicidad o los relativos al procedimiento de adjudicación que correspondan, establece que:","options":{"A":"Podrá fraccionarse.","B":"No podrá fraccionarse.","C":"Deberá fraccionarse.","D":"Excepcionalmente podrá fraccionarse."},"correct":"B","explanation":"El artículo 99.2 prohíbe fraccionar un contrato para reducir su cuantía y eludir los requisitos de publicidad o el procedimiento de adjudicación aplicable.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":53,"question":"Según lo dispuesto en la Ley 9/2017, de Contratos del Sector Público, en toda contratación pública se incorporarán de manera transversal y preceptiva:","options":{"A":"Criterios sociales y medioambientales siempre que guarden relación con el objeto del contrato.","B":"Criterios éticos y de transparencia aunque no guarden relación con el contrato.","C":"Criterios éticos y de transparencia siempre que guarden relación con el objeto del contrato.","D":"Criterios sociales y medioambientales aunque no guarden relación con el objeto del contrato."},"correct":"A","explanation":"El artículo 1.3 ordena incorporar criterios sociales y medioambientales de forma transversal y preceptiva siempre que guarden relación con el objeto del contrato.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":54,"question":"Según lo dispuesto en la Ley 9/2017, de Contratos del Sector Público, el valor estimado del contrato, en el caso de obras, suministros y servicios, será determinado por el órgano de contratación, que tomará:","options":{"A":"El importe total incluyendo el Impuesto sobre el Valor Añadido.","B":"El importe total sin incluir el Impuesto sobre el Valor Añadido, y sin incluir las eventuales prórrogas del contrato.","C":"El importe total sin incluir el Impuesto sobre el Valor Añadido, y teniendo en cuenta las eventuales prórrogas del contrato.","D":"El límite máximo de gasto que en virtud del contrato puede comprometer el órgano de contratación."},"correct":"C","explanation":"El artículo 101 calcula el valor estimado sin IVA e incluye, entre otros conceptos, las prórrogas y opciones previstas.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":55,"question":"Señale cuál de los siguientes principios no está garantizado por la Ley de Contratos del Sector Público:","options":{"A":"Libertad de acceso a las licitaciones.","B":"Discriminación y desigualdad de trato entre los licitadores.","C":"Publicidad y transparencia de los procedimientos.","D":"Eficiencia en la utilización de los fondos."},"correct":"B","explanation":"El artículo 1.1 garantiza acceso a las licitaciones, publicidad y transparencia, igualdad de trato y eficiencia en el uso de fondos. La discriminación y desigualdad de trato son contrarias a esos principios.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":56,"question":"Según el Decreto 220/2014, de 12 de diciembre, del Consell, por el que se aprueba el Reglamento de Administración Electrónica de la Comunitat Valenciana, en relación con la utilización de los medios electrónicos en la actividad administrativa, los ciudadanos tienen los siguientes derechos:","options":{"A":"Derecho a usar las tres lenguas oficiales en la Comunitat Valenciana.","B":"Derecho a obtener una dirección de correo postal facilitado por la Generalitat.","C":"Derecho a la representación electrónica.","D":"Todas son correctas."},"correct":"C","explanation":"El Reglamento valenciano de administración electrónica reconoce el derecho a actuar mediante representación electrónica. La opción C es el derecho que identifica la pregunta; verifica su regulación en el Tema 19 y en el decreto enlazado.","page":null,"topicNumber":19,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2014/12/12/220/con"},{"number":57,"question":"Según el Decreto 220/2014, de 12 de diciembre, del Consell, por el que se aprueba el Reglamento de Administración Electrónica de la Comunitat Valenciana, aquella dirección electrónica disponible para los ciudadanos a través de redes de telecomunicaciones cuya titularidad, gestión y administración corresponde a la Generalitat en el ejercicio de sus competencias, se denomina:","options":{"A":"Sede informática del Gobierno.","B":"Sede electrónica de la Generalitat.","C":"Sede informática de la Generalitat.","D":"Sede electrónica del Gobierno."},"correct":"B","explanation":"El Decreto 220/2014 define la sede electrónica como la dirección electrónica disponible para la ciudadanía cuya titularidad, gestión y administración corresponden a la Generalitat en el ejercicio de sus competencias.","page":null,"topicNumber":19,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2014/12/12/220/con"},{"number":58,"question":"Según lo establecido en la Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales, la Agencia Española de Protección de Datos inadmitirá las reclamaciones presentadas cuando:","options":{"A":"No carezcan manifiestamente de fundamento.","B":"No sean abusivas.","C":"No versen sobre cuestiones de protección de datos personales.","D":"Todas son correctas."},"correct":"C","explanation":"El artículo 65 de la LO 3/2018 permite inadmitir una reclamación, entre otros casos, cuando no verse sobre protección de datos personales; la opción C recoge ese supuesto.","page":null,"topicNumber":9,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673"},{"number":59,"question":"Según lo establecido en la Ley 4/2021, de 16 de abril, de la Generalitat, de la Función Pública Valenciana, no es un órgano ejecutivo competente en materia de función pública:","options":{"A":"El President de la Generalitat.","B":"El Consell.","C":"La consellera o el conseller competente en materia de función pública.","D":"El Consell Interdepartamental de Retribucions."},"correct":"A","explanation":"El artículo 6 de la Ley 4/2021 enumera los órganos ejecutivos competentes en función pública; no incluye al President de la Generalitat en esa lista.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":60,"question":"Conforme a lo establecido en el artículo 2 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, no es uno de los principios y fundamentos de actuación que ordenan la función pública valenciana:","options":{"A":"Servicio a la ciudadanía y a los intereses generales.","B":"Ética profesional en el desempeño del servicio público.","C":"Participación en la determinación de las condiciones de trabajo.","D":"Servicio a las administraciones públicas en la regulación del empleo público."},"correct":"D","explanation":"El artículo 2 incluye principios como servicio a la ciudadanía e intereses generales, ética profesional y participación en las condiciones de trabajo. La regulación del empleo público no es un principio formulado como en la opción D.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":61,"question":"De acuerdo con lo dispuesto en el artículo 11 de la Ley 4/2021, señale cuál de las siguientes competencias no corresponde a l'Escola Valenciana d'Administració Pública, en relación con el personal empleado público:","options":{"A":"Ejercer las restantes funciones que en materia de relaciones de puestos de trabajo y retribuciones del personal de la Administración de la Generalitat estén atribuidas conjuntamente a las consellerias competentes en materia de función pública y de presupuestos y gastos.","B":"Estudiar y proponer los métodos de selección más adecuados para el acceso a los distintos cuerpos y escalas del personal de la Generalitat, de modo que se garantice la selección del mejor talento y la igualdad de oportunidades.","C":"Convocar las bolsas para la provisión temporal de puestos de trabajo, mediante la selección del personal correspondiente de acuerdo con les directrices que al respecto establezca el departamento del Consell competente en materia de función pública.","D":"Promover, organizar y participar en congresos, seminarios, jornadas de estudio y otras actividades orientadas al intercambio y difusión de conocimientos y experiencias relacionadas con la administración pública, así como promover estudios e investigaciones en el ámbito de los recursos humanos y sobre la mejora e innovación del servicio público y realizar las publicaciones derivadas de todo ello."},"correct":"A","explanation":"La opción A no corresponde a las funciones de la EVAP que describe el artículo 11 citado en el examen: atribuye a otras consellerias las funciones compartidas sobre puestos y retribuciones. La pregunta se refiere a la redacción legal aplicable en su contexto; comprueba la versión consolidada vigente antes de estudiar este punto.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":62,"question":"De conformidad con lo establecido en la Ley 4/2021, de 16 de abril, de la Generalitat, de la Función Pública Valenciana, es obligación del personal empleado público en el ejercicio de sus funciones:","options":{"A":"Obedecer las instrucciones profesionales de sus superiores, aunque constituyan una infracción manifiesta del ordenamiento jurídico.","B":"Procurar la conservación de los documentos que se tramiten, salvo que el procedimiento haya caducado, en cuyo caso se destruirán inmediatamente.","C":"Observar las normas sobre seguridad y salud laboral.","D":"Velar por la conservación de los recursos y bienes públicos pudiéndolos utilizar en provecho propio o de personas allegadas."},"correct":"C","explanation":"La Ley 4/2021 obliga al personal empleado público a observar las normas de seguridad y salud laboral; desobedecer una orden manifiestamente ilegal o usar bienes públicos en provecho propio no son deberes permitidos.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":63,"question":"De acuerdo con lo establecido en el artículo 144 de la Ley 4/21, de la Función Pública Valenciana, cuando el personal funcionario de carrera de una administración pública, organismo público, consorcio o universidad pública que, en virtud de los procedimientos de transferencias, concurso o libre designación, obtenga destino en otra administración pública, será declarado en su administración pública, organismo público, consorcio o universidad pública de origen en la situación administrativa de:","options":{"A":"Excedencia voluntaria automática.","B":"Servicio en otras Administraciones Públicas.","C":"Excedencia voluntaria por interés particular.","D":"Servicios Especiales"},"correct":"B","explanation":"El artículo 144 denomina esta situación administrativa servicio en otras Administraciones Públicas cuando el personal obtiene destino en otra Administración por los procedimientos indicados.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":64,"question":"De acuerdo con lo establecido en el artículo 156 de la Ley 4/21, de la Función Pública Valenciana, las funcionarias declaradas en la situación de excedencia voluntaria por razón de violencia de género. Señalar la correcta:","options":{"A":"Durante los tres primeros meses de esta excedencia la funcionaria tendrá derecho a percibir las retribuciones íntegras y, en su caso, durante los dos primeros, las prestaciones familiares por hija o hijo a cargo.","B":"Durante los dos primeros meses de esta excedencia la funcionaria tendrá derecho a percibir las retribuciones íntegras y, en su caso, durante los tres primeros, las prestaciones familiares por hija o hijo a cargo.","C":"Durante los tres primeros meses de esta excedencia la funcionaria tendrá derecho a percibir las retribuciones íntegras y, en su caso, durante los tres primeros, las prestaciones familiares por hija o hijo a cargo.","D":"Durante los tres primeros meses de esta excedencia la funcionaria tendrá derecho a percibir las retribuciones íntegras y, en su caso, durante los seis primeros, las prestaciones familiares por hija o hijo a cargo."},"correct":"A","explanation":"El artículo 156 reconoce durante los tres primeros meses las retribuciones íntegras y, en su caso, durante los dos primeros meses las prestaciones familiares por hija o hijo a cargo.","page":null,"topicNumber":17,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":65,"question":"Según lo establecido en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, ¿cuál de las siguientes clasificaciones no aparecerá en el estado de gastos del presupuesto de la Generalitat Valenciana?","options":{"A":"La clasificación orgánica","B":"La clasificación económica","C":"La clasificación por programas","D":"La clasificación financiera"},"correct":"D","explanation":"El artículo 27 de la Ley 1/2015 prevé para los gastos las clasificaciones orgánica, por programas y económica. La clasificación financiera no es una de ellas.","page":null,"topicNumber":17,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":66,"question":"Conforme a lo establecido en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, señale quién aprueba el presupuesto de la Generalitat:","options":{"A":"El Consell","B":"La vicepresidencia o vicepresidencias del Consell","C":"Les Corts","D":"La Conselleria con competencia en materia de hacienda"},"correct":"C","explanation":"El presupuesto de la Generalitat se aprueba mediante ley por Les Corts; el Consell elabora y presenta el proyecto.","page":null,"topicNumber":17,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":67,"question":"Según lo establecido en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, señale la respuesta incorrecta. Los presupuestos de la Generalitat determinarán:","options":{"A":"Las obligaciones económicas que, como máximo, prevén liquidar, y los derechos que, como máximo, pueden reconocer, durante el correspondiente ejercicio los sujetos del sector público administrativo.","B":"Los gastos e ingresos y las operaciones de inversión y financieras a realizar por las entidades del sector público empresarial y fundacional.","C":"Los objetivos a alcanzar en el ejercicio por cada uno de los gestores responsables de los programas con los recursos que el respectivo presupuesto les asigna.","D":"La estimación de los beneficios fiscales que afecten a los tributos de la Generalitat y a aquellos cuyo rendimiento se cede por el Estado a la Generalitat, detallando para cada tipo de impuesto el importe de los beneficios fiscales correspondientes a normativa estatal y a normativa de la Comunitat Valenciana."},"correct":"A","explanation":"La opción A invierte los límites presupuestarios: el presupuesto estima los derechos que se prevé liquidar y fija las obligaciones que como máximo pueden reconocerse, no al revés.","page":null,"topicNumber":18,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":68,"question":"De conformidad con lo establecido en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, la ejecución de los créditos consignados en los presupuestos comprenderá las siguientes operaciones.","options":{"A":"Autorización del pago, compromiso o disposición del gasto, reconocimiento de la obligación, propuesta de pago, ordenación del pago y pago material.","B":"Retención del gasto, compromiso o disposición del gasto, reconocimiento de la obligación, propuesta de pago, ordenación del pago y pago material.","C":"Autorización del gasto, compromiso o disposición del gasto, reconocimiento de la obligación, propuesta de pago, ordenación del pago y pago material.","D":"Autorización del gasto, compromiso o disposición del gasto, reconocimiento del derecho, propuesta de pago, ordenación del pago y pago material."},"correct":"C","explanation":"El artículo 58 enumera la ejecución del gasto: autorización, compromiso o disposición, reconocimiento de la obligación, propuesta y ordenación del pago y pago material.","page":null,"topicNumber":18,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":69,"question":"De conformidad con lo establecido en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, en relación con la ordenación de pagos, señale la respuesta correcta:","options":{"A":"Corresponde a las personas titulares de las consellerias la ordenación general de pagos en el ámbito de la Administración de la Generalitat.","B":"Corresponde al Consell la ordenación general de pagos en el ámbito de la Administración de la Generalitat.","C":"Corresponde a la persona titular de la conselleria competente en materia de hacienda la ordenación general de pagos en el ámbito de la Administración de la Generalitat.","D":"Para el resto de sujetos que conforman el sector público administrativo la competencia corresponderá a la persona titular de la conselleria competente en materia de hacienda."},"correct":"C","explanation":"La Ley 1/2015 atribuye la ordenación general de pagos de la Administración de la Generalitat a la persona titular de la conselleria competente en hacienda.","page":null,"topicNumber":18,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":70,"question":"Indique qué documento contable de los que a continuación se relacionan no es de gastos:","options":{"A":"AD","B":"OK","C":"DR","D":"T"},"correct":"C","explanation":"El documento DR corresponde a operaciones del presupuesto de ingresos (derechos reconocidos), mientras AD, OK y T son documentos de la gestión de gastos.","page":null,"topicNumber":18,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":71,"question":"Indique cuál de las siguientes afirmaciones es incorrecta:","options":{"A":"El capítulo I del presupuesto de gastos corresponde a gastos de personal","B":"El capítulo III del presupuesto de gastos corresponde a inversiones reales","C":"El capítulo IX del presupuesto de gastos corresponde a pasivos financieros","D":"El capítulo IV del presupuesto de gastos corresponde a transferencias corrientes"},"correct":"B","explanation":"La clasificación económica del gasto identifica el capítulo III con gastos financieros. Las inversiones reales corresponden al capítulo VI, no al III.","page":null,"topicNumber":18,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":72,"question":"De conformidad con lo establecido en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, en relación con las competencias en materia de gestión del gasto, señale la respuesta correcta:","options":{"A":"Corresponde a las personas titulares de las consellerias autorizar los gastos y efectuar la disposición de crédito de los servicios propios a su cargo, salvo los casos reservados por la ley a la competencia del Consell.","B":"Corresponde a las personas titulares de las consellerias autorizar los gastos y efectuar la disposición de crédito de los servicios propios a su cargo, salvo los casos reservados reglamentariamente a la competencia del Consell.","C":"Corresponde a las personas titulares de las consellerias autorizar los gastos y efectuar la disposición de crédito de los servicios propios a su cargo, salvo los casos reservados reglamentariamente a la competencia de la persona titular de la conselleria con competencia en materia de hacienda.","D":"Corresponde a la persona titular de la conselleria con competencia en materia de hacienda autorizar los gastos y efectuar la disposición de crédito de los servicios propios a su cargo, salvo los casos reservados por la ley a la competencia del Consell."},"correct":"A","explanation":"La Ley 1/2015 atribuye a las personas titulares de las consellerias la autorización del gasto y disposición de crédito de sus servicios, salvo los casos que la ley reserva al Consell.","page":null,"topicNumber":18,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":73,"question":"¿Cuál de estos documentos contables mixtos del presupuesto de ingresos es inverso o es una anulación?","options":{"A":"DD","B":"RL/","C":"IK","D":"DRK"},"correct":"B","explanation":"RL/ es el documento inverso o de anulación empleado en la contabilidad del presupuesto de ingresos de la Generalitat. Consulta la tabla de documentos contables del Tema 18.","page":null,"topicNumber":18,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":74,"question":"Señale la respuesta correcta: al hacer triple clic en una palabra de un texto escrito con LibreOffice Writer:","options":{"A":"Se selecciona esa palabra.","B":"Se borra esa palabra.","C":"Se selecciona esa palabra y toda la frase que la contiene.","D":"La palabra cambia de mayúsculas a minúsculas, o viceversa."},"correct":"C","explanation":"La guía oficial de LibreOffice Writer indica que un triple clic selecciona la frase que contiene el punto pulsado (incluida la palabra); por eso la opción C es la correcta.","page":null,"topicNumber":23,"officialSource":"https://books.libreoffice.org/en/WG76/WG7602-TextBasics.html"},{"number":75,"question":"Indique qué combinación de teclas en LibreOffice Writer hace que se pueda cortar un texto seleccionado:","options":{"A":"Control + C","B":"Control + V","C":"Control + X","D":"Control +"},"correct":"C","explanation":"En Writer, Ctrl+X corta el texto seleccionado; Ctrl+C lo copia y Ctrl+V lo pega.","page":null,"topicNumber":23,"officialSource":"https://books.libreoffice.org/en/WG76/WG7602-TextBasics.html"}],"2021":[{"number":1,"question":"De conformidad con lo dispuesto en el artículo 13 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, donde se recogen los derechos de las personas en sus relaciones con las Administraciones Públicas, señale cuál de los siguientes derechos es incorrecto:","options":{"A":"A comunicarse con las Administraciones Públicas a través de un Punto de Acceso General electrónico de la Administración.","B":"A ser asistidos en el uso de medios electrónicos en sus relaciones con las Administraciones Públicas.","C":"A no presentar datos y documentos no exigidos por las normas aplicables al procedimiento de que se trate, que ya se encuentren en poder de las Administraciones Públicas o que hayan sido elaborados por éstas.","D":"A la protección de datos de carácter personal, y en particular a la seguridad y confidencialidad de los datos que figuren en los ficheros, sistemas y aplicaciones de las Administraciones Públicas."},"correct":"C","explanation":"El artículo 13 reconoce el derecho a no aportar documentos exigidos cuando ya están en poder de una Administración o han sido elaborados por ella. La opción C amplía el derecho a documentos que ni siquiera exige la norma, por eso es la incorrecta.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":2,"question":"De conformidad con lo dispuesto en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, señale cuál de los siguientes enunciados es correcto:","options":{"A":"Los plazos expresados por horas se contarán de hora en hora y de minuto en minuto desde la hora y minuto en que tenga lugar la notificación o publicación del acto de que se trate y no podrán tener una duración inferior a veinticuatro horas, en cuyo caso se expresarán en días.","B":"Los plazos expresados en días se contarán a partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto de que se trate, o desde aquel en que se produzca la estimación o la desestimación por silencio administrativo.","C":"El plazo concluirá el mismo día en que se produjo la notificación, publicación o silencio administrativo en el mes o el año de vencimiento. Si en el mes de vencimiento no hubiera día equivalente a aquel en que comienza el cómputo, se entenderá que el plazo expira el primer día del mes siguiente.","D":"Siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos."},"correct":"D","explanation":"El artículo 30.2 dispone que los plazos fijados por días son hábiles, salvo que una ley o el Derecho de la Unión establezca otro cómputo. Se excluyen sábados, domingos y festivos.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":3,"question":"De conformidad con lo dispuesto en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, señale cuál de los siguientes enunciados es incorrecto:","options":{"A":"La Administración, salvo precepto en contrario, podrá conceder de oficio o a petición del órgano instructor una ampliación de los plazos establecidos, que no exceda de la mitad de los mismos, si las circunstancias lo aconsejan y con ello no se perjudican derechos de tercero. El acuerdo de ampliación deberá ser notificado a los interesados.","B":"La ampliación de los plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por las misiones diplomáticas y oficinas consulares, así como a aquellos que, sustanciándose en el interior, exijan cumplimentar algún trámite en el extranjero o en los que intervengan interesados residentes fuera de España.","C":"Tanto la petición de los interesados como la decisión sobre la ampliación deberán producirse, en todo caso, antes del vencimiento del plazo de que se trate. En ningún caso podrá ser objeto de ampliación un plazo ya vencido.","D":"Los acuerdos sobre ampliación de plazos o sobre su denegación no serán susceptibles de recurso, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento."},"correct":"A","explanation":"La opción A es incorrecta: el artículo 32 permite conceder la ampliación de oficio o a petición de las personas interesadas, no a petición del órgano instructor. La ampliación no puede superar la mitad del plazo y debe notificarse.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":4,"question":"De conformidad con lo dispuesto en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos de las administraciones públicas sujetos al Derecho Administrativo serán inmediatamente ejecutivos, salvo que (señale la respuesta incorrecta):","options":{"A":"Se produzca la suspensión de la ejecución del acto.","B":"Una disposición establezca lo contrario.","C":"Se trate de una resolución de un procedimiento de responsabilidad patrimonial contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición.","D":"Se necesite aprobación o autorización superior."},"correct":"C","explanation":"El artículo 98 establece la ejecutividad inmediata como regla. La responsabilidad patrimonial no es una excepción por sí misma; la opción C es incorrecta. Sí hay excepciones cuando se suspende la ejecución, una norma dispone lo contrario o se requiere aprobación superior.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":5,"question":"De conformidad con lo dispuesto en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, señale cuál de los siguientes enunciados es correcto:","options":{"A":"Cuando la notificación por medios electrónicos sea de carácter obligatorio, o haya sido expresamente elegida por el interesado, se entenderá rechazada cuando hayan transcurrido diez días hábiles desde la puesta a disposición de la notificación sin que se acceda a su contenido.","B":"Todas las notificaciones que se practiquen en papel deberán ser puestas a disposición del interesado en la sede electrónica de la Administración u Organismo actuante para que pueda acceder al contenido de las mismas de forma voluntaria.","C":"Cuando la notificación se practique en el domicilio del interesado, de no hallarse presente éste en el momento de entregarse la notificación, podrá hacerse cargo de la misma cualquier persona mayor de dieciséis años que se encuentre en el domicilio y haga constar su identidad.","D":"Cuando los interesados en un procedimiento sean desconocidos, se ignore el lugar de la notificación o bien, intentada ésta, no se hubiese podido practicar, la notificación se hará por medio de un anuncio publicado en el boletín oficial de la comunidad autónoma o de la provincia."},"correct":"B","explanation":"El artículo 41.1 dispone que las notificaciones en papel también se pongan a disposición de la persona interesada en la sede electrónica para que pueda acceder voluntariamente a su contenido.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":6,"question":"De conformidad con lo dispuesto en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, señale el enunciado correcto:","options":{"A":"Son anulables las resoluciones administrativas que vulneren lo establecido en una disposición reglamentaria, así como aquellas que incurran en alguna de las causas recogidas en el artículo 47.","B":"Los actos de las Administraciones Públicas sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en esta Ley.","C":"Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se notifiquen, salvo que en ellos se disponga otra cosa.","D":"Excepcionalmente, podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos desfavorables al interesado, siempre que los supuestos de hecho necesarios existieran ya en la fecha a que se retrotraiga la eficacia del acto y ésta no lesione derechos o intereses legítimos de otras personas."},"correct":"B","explanation":"El artículo 38 establece que los actos sujetos al Derecho Administrativo son ejecutivos conforme a la Ley. La opción C es falsa porque, como regla general, los actos producen efectos desde que se dictan, no desde que se notifican.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":7,"question":"Según el Capítulo III del Título III de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, se produce la nulidad de pleno derecho en los actos de las Administraciones Públicas que:","options":{"A":"Incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder.","B":"Son dictados por órgano competente por razón de la materia.","C":"Lesionen los derechos y libertades susceptibles de amparo constitucional.","D":"Que no vulneren la Constitución, las leyes u otras disposiciones administrativas de rango superior, las que regulen materias reservadas a la Ley, y las que establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales."},"correct":"C","explanation":"El artículo 47.1.a declara nulos de pleno derecho los actos que lesionen derechos y libertades susceptibles de amparo constitucional.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":8,"question":"De acuerdo con el artículo 48 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, un acto que incurre en defecto de forma determinará:","options":{"A":"La nulidad de pleno derecho, en todo caso.","B":"La anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.","C":"La anulabilidad cuando el acto no carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.","D":"La nulidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados."},"correct":"B","explanation":"Según el artículo 48.2, un defecto de forma solo determina anulabilidad si el acto carece de requisitos formales indispensables para alcanzar su fin o causa indefensión.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":9,"question":"De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, la figura jurídica mediante la cual \"los actos nulos o anulables que contengan elementos constitutivos de otro distinto producirán los efectos de éste\", se denomina:","options":{"A":"Conversión de actos viciados.","B":"Conservación de actos y trámites.","C":"Convalidación.","D":"Anulación del acto."},"correct":"A","explanation":"El artículo 50 denomina conversión a la figura por la que un acto nulo o anulable que contiene elementos de otro acto produce los efectos de este último.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":10,"question":"Según el artículo 53 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, respecto a los derechos de los interesados en el procedimiento administrativo, cuál de los siguientes derechos no es correcto:","options":{"A":"A identificar a las autoridades y al personal al servicio de las Administraciones Públicas bajo cuya responsabilidad se tramiten los procedimientos.","B":"A no presentar documentos originales salvo que, de manera excepcional, la normativa reguladora aplicable establezca lo contrario. En caso de que, excepcionalmente, deban presentar un documento original, tendrán derecho a obtener una copia autenticada de éste.","C":"A presentar datos y documentos no exigidos por las normas aplicables al procedimiento de que se trate, que ya se encuentren en poder de las Administraciones Públicas o que hayan sido elaborados por éstas.","D":"A formular alegaciones, utilizar los medios de defensa admitidos por el Ordenamiento Jurídico, y a aportar documentos en cualquier fase del procedimiento anterior al trámite de audiencia, que deberán ser tenidos en cuenta por el órgano competente al redactar la propuesta de resolución."},"correct":"C","explanation":"El artículo 53 reconoce el derecho a no aportar documentos que ya obren en poder de la Administración o hayan sido elaborados por ella, no el derecho a presentar esos documentos. Por eso C no es correcto.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":11,"question":"Según el artículo 56 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, indique la respuesta correcta:","options":{"A":"Iniciado el procedimiento, el órgano administrativo competente para resolver podrá adoptar, de oficio o a instancia de parte y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la resolución que pudiera recaer, si existiesen elementos de juicio suficientes para ello, de acuerdo con los principios de proporcionalidad, efectividad y menor onerosidad.","B":"Instruido el procedimiento, el órgano administrativo competente para resolver podrá adoptar, de oficio o a instancia de parte y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la resolución que pudiera recaer, si existiesen elementos de juicio suficientes para ello, de acuerdo con los principios de proporcionalidad, efectividad y menor onerosidad.","C":"Iniciado el procedimiento, el órgano administrativo competente para instruir podrá adoptar, de oficio o a instancia de parte y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la resolución que pudiera recaer, si existiesen elementos de juicio suficientes para ello, de acuerdo con los principios de proporcionalidad, efectividad y menor onerosidad.","D":"Iniciado el procedimiento, el órgano administrativo competente para resolver podrá adoptar, de oficio o a instancia de parte y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la instrucción que pudiera recaer, si existiesen elementos de juicio suficientes para ello, de acuerdo con los principios de proporcionalidad, efectividad y menor onerosidad."},"correct":"A","explanation":"El artículo 56 permite al órgano competente para resolver adoptar, una vez iniciado el procedimiento y de forma motivada, medidas provisionales para asegurar la eficacia de la resolución.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":12,"question":"Según el artículo 59 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, respecto del inicio del procedimiento por propia iniciativa, indique la respuesta correcta:","options":{"A":"Se entiende por propia iniciativa, la actuación derivada del conocimiento directo o indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de instrucción.","B":"Se entiende por propia iniciativa, la actuación derivada del conocimiento directo o indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de resolución.","C":"Se entiende por propia iniciativa, la actuación derivada del conocimiento directo o indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de revisión.","D":"Se entiende por propia iniciativa, la actuación derivada del conocimiento directo o indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de iniciación."},"correct":"D","explanation":"El artículo 59 define la iniciación por propia iniciativa como la actuación derivada del conocimiento de hechos por el órgano que tiene atribuida la competencia de iniciación.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":13,"question":"Según el artículo 109 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, respecto a la revocación de actos, señale la respuesta correcta:","options":{"A":"Las Administraciones Públicas podrán revocar, mientras no haya transcurrido el plazo de caducidad, sus actos de gravamen o desfavorables, siempre que tal revocación no constituya dispensa o exención no permitida por las leyes, ni sea contraria al principio de igualdad, al interés público o al ordenamiento jurídico.","B":"Las Administraciones Públicas podrán revocar, mientras no haya transcurrido el plazo de prescripción, sus actos de gravamen o desfavorables, siempre que tal revocación no constituya dispensa o exención no permitida por las leyes, ni sea contraria al principio de igualdad, al interés público o al ordenamiento jurídico.","C":"Las Administraciones Públicas podrán revocar, mientras no haya transcurrido el plazo de prescripción, sus actos de gravamen o desfavorables, siempre que tal revocación constituya dispensa o exención no permitida por las leyes, y sea contraria al principio de igualdad, al interés público o al ordenamiento jurídico.","D":"Las Administraciones Públicas podrán revocar, mientras haya transcurrido el plazo de prescripción, sus actos de gravamen o desfavorables, siempre que tal revocación no constituya dispensa o exención no permitida por las leyes, ni sea contraria al principio de igualdad, al interés público o al ordenamiento jurídico."},"correct":"B","explanation":"El artículo 109.1 permite revocar actos de gravamen o desfavorables mientras no haya transcurrido el plazo de prescripción, siempre que la revocación no sea ilegal ni contraria a la igualdad o al interés público.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":14,"question":"Según el artículo 114 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, respecto al fin de la vía administrativa, señale la respuesta incorrecta:","options":{"A":"Ponen fin a la vía administrativa, las resoluciones de los recursos de alzada.","B":"Ponen fin a la vía administrativa, las resoluciones de los órganos administrativos que carezcan de superior jerárquico, salvo que un reglamento establezca lo contrario.","C":"Ponen fin a la vía administrativa, los acuerdos, pactos, convenios o contratos que tengan la consideración de finalizadores del procedimiento.","D":"Ponen fin a la vía administrativa, la resolución administrativa de los procedimientos de responsabilidad patrimonial, cualquiera que fuese el tipo de relación, pública o privada, de que derive."},"correct":"B","explanation":"El artículo 114.1 establece que los actos de órganos sin superior jerárquico ponen fin a la vía administrativa salvo que una ley disponga lo contrario; la opción B dice que puede hacerlo un reglamento, y por eso es incorrecta.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":15,"question":"Según el artículo 106 de la Ley 39/2015 de Procedimiento Administrativo común de las administraciones públicas, señale la respuesta correcta en relación con los procedimientos de revisión de oficio de disposiciones y actos nulos:","options":{"A":"Cuando el procedimiento se hubiera iniciado de oficio, el transcurso de tres meses desde el inicio sin dictarse resolución producirá la caducidad del mismo.","B":"Cuando el procedimiento se hubiera iniciado de oficio, el transcurso del plazo de seis meses desde su inicio sin dictarse resolución producirá la caducidad del mismo.","C":"Cuando el procedimiento se hubiera iniciado de oficio, el transcurso del plazo de seis meses desde su inicio sin dictarse resolución, se podrá entender la misma desestimada por silencio administrativo.","D":"Cuando el procedimiento se hubiera iniciado de oficio, el transcurso de tres meses desde su inicio sin dictarse resolución, se podrá entender la misma desestimada por silencio administrativo."},"correct":"B","explanation":"El artículo 106.5 establece que, si un procedimiento de revisión de oficio iniciado de oficio no se resuelve en seis meses, se produce su caducidad.","page":null,"topicNumber":12,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"number":16,"question":"Indique la respuesta correcta respecto a la competencia, según lo dispuesto en el artículo 8 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:","options":{"A":"La competencia es renunciable y se ejercerá por los órganos administrativos que la tengan atribuida como propia, salvo los casos de delegación o avocación.","B":"La delegación de competencias, las encomiendas de gestión, la delegación de firma y la suplencia suponen alteración de la titularidad de la competencia, aunque no de los elementos determinantes de su ejercicio que en cada caso se prevén.","C":"La titularidad y el ejercicio de las competencias atribuidas a los órganos administrativos podrán ser desconcentradas en otros jerárquicamente dependientes de aquéllos en los términos y con los requisitos que prevean las propias normas de atribución de competencias.","D":"Si alguna disposición atribuye la competencia a una Administración, sin especificar el órgano que debe ejercerla, se entenderá que la facultad de instruir y resolver los expedientes corresponde a los órganos superiores competentes por razón de la materia y del territorio."},"correct":"C","explanation":"El artículo 8.2 permite desconcentrar tanto la titularidad como el ejercicio de competencias en órganos jerárquicamente dependientes, conforme a las normas que las atribuyen.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":17,"question":"Indique la respuesta correcta respecto a la delegación de firma, según artículo 12 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:","options":{"A":"Los titulares de los órganos administrativos podrán, en materias que no sean de su competencia, que ostenten, bien por atribución, bien por delegación de competencias, delegar la firma de sus resoluciones y actos administrativos en los titulares de los órganos o unidades administrativas que no dependan de ellos, dentro de los límites señalados en el artículo 9.","B":"La delegación de firma alterará la competencia del órgano delegante y para su validez será necesaria su publicación.","C":"La delegación de firma no alterará la competencia del órgano delegante y para su validez no será necesaria su publicación.","D":"En las resoluciones y actos que se firmen por delegación no es necesario constar esta circunstancia ni la autoridad de procedencia."},"correct":"C","explanation":"El artículo 12 dispone que la delegación de firma no cambia la competencia del órgano delegante y no necesita publicarse para ser válida.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":18,"question":"Indique la respuesta correcta respecto a la encomienda de gestión, según lo dispuesto en el artículo 11 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:","options":{"A":"La realización de actividades de carácter material o técnico de la competencia de los órganos administrativos o de las Entidades de Derecho Público podrá ser encomendada a otros órganos o Entidades de Derecho Público de la misma o de distinta Administración, siempre que entre sus competencias estén esas actividades, por razones de eficacia o cuando no se posean los medios técnicos idóneos para su desempeño.","B":"Las encomiendas de gestión podrán tener por objeto prestaciones propias de los contratos regulados en la legislación de contratos del sector público. En tal caso, su naturaleza y régimen jurídico no se ajustará a lo previsto en ésta.","C":"La encomienda de gestión supone cesión de la titularidad de la competencia y de los elementos sustantivos de su ejercicio, no siendo responsabilidad del órgano o Entidad encomendante dictar cuantos actos o resoluciones de carácter jurídico den soporte o en los que se integre la concreta actividad material objeto de encomienda.","D":"En ningún caso, la Entidad u órgano encomendado tendrá la condición de encargado del tratamiento de los datos de carácter personal a los que pudiera tener acceso en ejecución de la encomienda de gestión, siéndole de aplicación lo dispuesto en la normativa de protección de datos de carácter personal."},"correct":"A","explanation":"El artículo 11 permite encomendar actividades materiales o técnicas a otros órganos o entidades de Derecho Público por eficacia o falta de medios idóneos. La competencia y los actos jurídicos siguen correspondiendo al órgano encomendante.","page":null,"topicNumber":13,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566"},{"number":19,"question":"La Ley 9/2017, de 8 de noviembre, de contratos del sector público tiene como finalidad:","options":{"A":"Garantizar que la contratación se ajusta a los principios de libertad de acceso a las licitaciones, publicidad y transparencia de los procedimientos, y no discriminación e igualdad de trato entre los licitadores.","B":"Asegurar, en conexión con el principio de estabilidad presupuestaria y control de los ingresos, una eficiente utilización de los fondos.","C":"Asegurar una eficiente utilización de los fondos, exclusivamente, mediante la salvaguarda de la libre competencia y la selección de la oferta económicamente más ventajosa.","D":"Asegurar que, en toda contratación pública, se incorporen de manera transversal y progresiva, criterios sociales y medioambientales."},"correct":"A","explanation":"El artículo 1.1 fija como finalidad asegurar libertad de acceso, publicidad y transparencia, igualdad de trato y no discriminación, además de una utilización eficiente de los fondos públicos.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":20,"question":"De conformidad con la delimitación de los tipos contractuales que establece la Ley 9/2017, de 8 de noviembre, de contratos del sector público, la adquisición de un programa de ordenador a medida se calificará como un contrato:","options":{"A":"De suministros, en todo caso.","B":"De servicios.","C":"De concesión de servicios, por su finalidad.","D":"Administrativo especial, ya que se trata de un encargo."},"correct":"B","explanation":"El artículo 17 califica como contrato de servicios la adquisición o desarrollo de programas de ordenador a medida, porque no se trata de un producto estándar adquirido como suministro.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":21,"question":"De acuerdo con la Ley 9/2017, de 8 de noviembre, de contratos del sector público, es cierto que los partidos políticos:","options":{"A":"Deberán aprobar unas instrucciones internas en materia de contratación.","B":"En los contratos sujetos a regulación armonizada deberán aplicar las normas de contratación establecidas en la ley.","C":"En todos los contratos deberán respetar, entre otros, el principio de integridad.","D":"Las instrucciones internas en materia de contratación deberán publicarse en el BOE."},"correct":"A","explanation":"La disposición adicional tercera de la Ley 9/2017 exige a los partidos políticos aprobar instrucciones internas para contratar, ajustadas a los principios de contratación pública y con la publicidad prevista legalmente.","page":null,"topicNumber":14,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"},{"number":22,"question":"De acuerdo con el tenor literal del artículo 1 del Decreto 220/2014, de 12 de diciembre, del Consell, por el que se aprueba el Reglamento de Administración Electrónica de la Comunitat Valenciana, el objeto del presente decreto es la regulación del régimen jurídico de la utilización por la Administración de la Generalitat de los medios:","options":{"A":"Electrónicos, informáticos y telemáticos en el desarrollo de su actividad administrativa.","B":"Electrónicos, informáticos, digitales y generales en el desarrollo de su actividad administrativa.","C":"Electrónicos, informáticos y tecnológicos en el desarrollo de su actividad Administrativa.","D":"Electrónicos, automatizados y tecnológicos en el desarrollo de su actividad administrativa."},"correct":"A","explanation":"El artículo 1 del Decreto 220/2014 define su objeto como la regulación del uso de medios electrónicos, informáticos y telemáticos por la Administración de la Generalitat en su actividad administrativa.","page":null,"topicNumber":19,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2014/12/12/220/con"},{"number":23,"question":"Conforme al Decreto 220/2014, de 12 de diciembre, del Consell, por el que se aprueba el Reglamento de Administración Electrónica de la Comunitat Valenciana indique la respuesta correcta respecto al tablón de anuncios y edictos electrónico de la Generalitat:","options":{"A":"La publicación en el tablón de anuncios y edictos electrónico no sustituirá a la publicación en el tablón de anuncios o edictos convencional, no obstante, se garantizará la igualdad de acceso electrónico a su contenido y no se precisará de identificación alguna.","B":"Si existe publicación convencional, esta prevalecerá sobre la publicación en el tablón de anuncios y edictos electrónico.","C":"La titularidad del tablón de anuncios y edictos electrónico de la Generalitat es única.","D":"Lo dispuesto en este Decreto, en cualquier caso, afectará a las publicaciones que se publiquen de actos y comunicaciones que deban realizarse en los tablones de anuncios o edictos de otras administraciones públicas."},"correct":"C","explanation":"El artículo 15 del Decreto 220/2014 establece la titularidad única del tablón de anuncios y edictos electrónico de la Generalitat.","page":null,"topicNumber":19,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2014/12/12/220/con"},{"number":24,"question":"Conforme al literal del artículo 7.1 de la Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales, el tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea:","options":{"A":"Mayor de 13 años.","B":"Mayor de 14 años.","C":"Mayor de 18 años.","D":"Mayor de 16 años."},"correct":"B","explanation":"El artículo 7.1 de la LO 3/2018 permite fundar el tratamiento de datos de un menor en su consentimiento cuando sea mayor de catorce años.","page":null,"topicNumber":9,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673"},{"number":25,"question":"Conforme a la Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales, indique la respuesta correcta:","options":{"A":"La Presidencia y el Adjunto de la Agencia Española de Protección de Datos serán nombrados por el Consejo de Ministros por Orden Ministerial.","B":"La Agencia Española de Protección de datos se relaciona con el Gobierno a través del Ministerio del Interior.","C":"La Agencia Española de Protección de Datos es una autoridad administrativa independiente de ámbito estatal, de las previstas en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, con personalidad jurídica y plena capacidad pública y privada, que actúa con plena independencia de los poderes públicos en el ejercicio de sus funciones.","D":"La Agencia Española de Protección de Datos es una autoridad administrativa independiente de ámbito estatal, de las previstas en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, con personalidad jurídica y plena capacidad pública, que actúa en dependencia de los poderes públicos en el ejercicio de sus funciones."},"correct":"C","explanation":"El artículo 44 de la LO 3/2018 configura la Agencia Española de Protección de Datos como autoridad administrativa independiente estatal, con personalidad jurídica y plena capacidad pública y privada, que actúa con independencia de los poderes públicos.","page":null,"topicNumber":9,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673"},{"number":26,"question":"Conforme al artículo 7 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, corresponde al Consell:","options":{"A":"Otorgar los títulos de personal funcionario de la Generalitat.","B":"Aprobar las relaciones de puestos de trabajo y otros instrumentos complementarios de gestión de la Administración de la Generalitat.","C":"Acordar la separación del servicio del personal funcionario de la Generalitat.","D":"Resolver las jubilaciones del personal de la Administración de la Generalitat."},"correct":"C","explanation":"El artículo 7 de la Ley 4/2021 atribuye al Consell acordar la separación del servicio del personal funcionario de la Generalitat.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":27,"question":"Conforme al artículo 1 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, el objeto de la presente ley es:","options":{"A":"La ordenación y regulación de la función pública valenciana, así como de sus instrumentos de gestión y la determinación del régimen jurídico del personal incluido en su ámbito de aplicación, con el alcance que en cada caso se establece, en el ejercicio de las competencias atribuidas por la Constitución Española y por el Estatut d'Autonomia de la Comunitat Valenciana, en el marco de la legislación básica estatal.","B":"La ordenación y gestión de la función pública valenciana, así como de sus instrumentos de organización y la determinación del régimen jurídico del personal incluido en su ámbito de aplicación, con el alcance que en cada caso se establece, en el ejercicio de las competencias atribuidas por la Constitución Española y por el Estatut d'Autonomia de la Comunitat Valenciana, en el marco de la legislación básica estatal.","C":"La organización y gestión de la función pública valenciana, así como de sus instrumentos de ordenación y la determinación del régimen jurídico del personal incluido en su ámbito de aplicación, con el alcance que en cada caso se establece, en el ejercicio de las competencias atribuidas por la Constitución Española y por el Estatut d'Autonomia de la Comunitat Valenciana, en el marco de la legislación básica estatal.","D":"La clasificación y gestión de la función pública valenciana, así como de sus instrumentos de organización y la determinación del régimen jurídico del personal incluido en su ámbito de aplicación, con el alcance que en cada caso se establece, en el ejercicio de las competencias atribuidas por la Constitución Española y por el Estatut d'Autonomia de la Comunitat Valenciana, en el marco de la legislación básica estatal."},"correct":"A","explanation":"El artículo 1 define el objeto de la Ley 4/2021: ordenar y regular la función pública valenciana, sus instrumentos de gestión y el régimen jurídico del personal incluido en su ámbito.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":28,"question":"Conforme al artículo 6 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, entre los órganos ejecutivos competentes en materia de función pública, no se encuentra:","options":{"A":"El Consell.","B":"El Consell Interdepartamental de Retribucions.","C":"El director o directora general competente en materia de función pública.","D":"La consellera o el conseller competente en materia de función pública."},"correct":"C","explanation":"El artículo 6 enumera como órganos ejecutivos al Consell, a la persona titular de la conselleria competente y al Consell Interdepartamental de Retribucions. No incluye a la dirección general, opción C.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":29,"question":"De acuerdo con el artículo 2.3 de la Ley 4/2015 de 16 de abril, de la Función Pública Valenciana el personal empleado público, en el desarrollo de sus funciones, para cumplir los objetivos asignados actuará de acuerdo con los principios de (indique la respuesta incorrecta):","options":{"A":"Imparcialidad.","B":"Organización.","C":"Buena fe.","D":"Profesionalidad."},"correct":"B","explanation":"El artículo 2.3 recoge principios como imparcialidad, buena fe y profesionalidad; organización no aparece en esa enumeración y es la opción incorrecta.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":30,"question":"En relación con la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, indique la respuesta correcta:","options":{"A":"La pérdida de dos grados en el sistema de carrera profesional y la privación del derecho a ser evaluado para el ascenso de grado, por un periodo de hasta un año, son algunas de las sanciones que pueden imponerse por la comisión de faltas graves.","B":"El personal empleado público que se encuentre en situación administrativa distinta a la de servicio activo podrá incurrir en responsabilidad disciplinaria por las faltas que, en su caso, pueda cometer dentro de su respectiva situación administrativa.","C":"El procedimiento disciplinario deberá ser resuelto y notificarse la resolución que proceda a la persona interesada, en el plazo máximo de seis meses desde su iniciación.","D":"En el procedimiento disciplinario, el periodo de información y actuaciones previas no podrá tener una duración superior a 15 días."},"correct":"B","explanation":"La opción B es correcta: la Ley 4/2021 permite exigir responsabilidad disciplinaria por faltas cometidas durante una situación administrativa distinta del servicio activo. Las demás opciones alteran sanciones o plazos legales.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":31,"question":"En relación con la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, indique la respuesta correcta:","options":{"A":"Las sanciones impuestas por faltas muy graves prescribirán a los 2 años.","B":"Podrán ser objeto de cancelación las anotaciones realizadas en el Registro de Personal de las sanciones de separación del servicio del personal funcionario de carrera o revocación del nombramiento del personal funcionario interino.","C":"Cuando no sea posible el cumplimiento de la sanción en el momento de dictarse la resolución por hallarse en una situación que lo impida, esta se hará efectiva cuando el cambio de situación lo permita, salvo que haya transcurrido el plazo de prescripción.","D":"Cuando de la instrucción de un procedimiento disciplinario resulte la existencia de indicios fundados de criminalidad, no se suspenderá su tramitación, pero se pondrá en conocimiento del Ministerio Fiscal."},"correct":"C","explanation":"La opción C reproduce la regla legal: si no puede ejecutarse una sanción al dictarse la resolución por la situación de la persona sancionada, se hará efectiva cuando cambie esa situación, salvo que haya prescrito.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":32,"question":"En relación con la Ley 4/2021 de 16 de abril, de la Función Pública Valenciana, indique la respuesta correcta:","options":{"A":"El personal funcionario de carrera en situación administrativa distinta a la de servicio activo podrá cambiar de situación administrativa siempre que reúna los requisitos exigidos en cada caso, sin necesidad de reingreso previo al servicio activo.","B":"La funcionaria en excedencia voluntaria por razón de violencia de género, durante los seis primeros meses, tendrá derecho a percibir las retribuciones íntegras y, en su caso, durante los tres primeros, las prestaciones familiares por hija o hijo a cargo.","C":"El personal funcionario en situación de excedencia voluntaria por cuidado de familiares no podrá participar en los cursos de formación que organice la Administración.","D":"El tiempo de permanencia en la situación de excedencia voluntaria por agrupación familiar será computable a efectos de promoción profesional, antigüedad y derechos en el Régimen de Seguridad Social que sea aplicable."},"correct":"A","explanation":"El artículo 148.2 permite al personal funcionario de carrera cambiar de situación administrativa desde otra distinta del servicio activo si reúne los requisitos, sin reingresar antes al servicio activo.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":33,"question":"En relación con la Ley 4/2021 de 16 de abril, de la Función Pública Valenciana, indique la respuesta correcta:","options":{"A":"El personal declarado en la situación administrativa de excedencia forzosa tiene derecho a percibir las retribuciones de carácter básico y las retribuciones complementarias vinculadas a la carrera administrativa y al puesto de trabajo.","B":"El personal funcionario declarado en la situación administrativa de excedencia forzosa tiene derecho a percibir las retribuciones básicas, el complemento de carrera, el nivel competencial adquirido o en proceso de reconocimiento si no se tuviera ninguno, así como el cincuenta por ciento del componente de desempeño del complemento del puesto de trabajo.","C":"El personal declarado en la situación administrativa de excedencia forzosa tiene derecho a percibir las retribuciones básicas y, en su caso, las prestaciones familiares por hija o hijo a cargo.","D":"El puesto de trabajo obtenido con destino definitivo se reservará durante los dos primeros años de duración de la excedencia voluntaria por cuidado de familiares."},"correct":"C","explanation":"El artículo 161.1 reconoce en excedencia forzosa las retribuciones básicas y, en su caso, las prestaciones familiares por hija o hijo a cargo; esa es la opción C.","page":null,"topicNumber":15,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8880"},{"number":34,"question":"De los documentos que se relacionan a continuación, según la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, cuál debe acompañar al proyecto de ley de presupuestos de la Generalitat:","options":{"A":"Informe de impacto de género.","B":"Memoria de los beneficios no fiscales que afecten a los tributos de la Generalitat.","C":"Distribución de los ingresos en programas por objetivos.","D":"Estados sin consolidar de los presupuestos."},"correct":"A","explanation":"El artículo 34.2.i incluye el informe de impacto de género entre los documentos que acompañan el proyecto de Ley de Presupuestos de la Generalitat.","page":null,"topicNumber":17,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":35,"question":"De acuerdo con la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, señale la respuesta incorrecta en relación con los documentos que se deben remitir a Les Corts acompañando el proyecto de ley de presupuestos:","options":{"A":"Detalle de las plantillas de la Administración de la Generalitat y organismos autónomos, adecuada a la estructura orgánica.","B":"La liquidación que se prevé efectuar en el presupuesto presentado y un estado de ejecución del vigente.","C":"Estados consolidados de los presupuestos.","D":"Memoria explicativa del articulado del proyecto de ley."},"correct":"B","explanation":"El artículo 34.2.f exige la liquidación del presupuesto del año anterior y el estado de ejecución del presupuesto corriente. La opción B cambia la liquidación anterior por una previsión del presupuesto presentado.","page":null,"topicNumber":17,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":36,"question":"De acuerdo con la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, ¿quién elaborará el anteproyecto del presupuesto de ingresos de la Administración de la Generalitat?:","options":{"A":"El Consell.","B":"La conselleria respectiva.","C":"Les Corts.","D":"La conselleria con competencias en materia de hacienda."},"correct":"D","explanation":"El artículo 33.3 atribuye a la conselleria competente en materia de hacienda la elaboración del anteproyecto del presupuesto de ingresos de la Administración de la Generalitat.","page":null,"topicNumber":17,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":37,"question":"De conformidad con lo establecido en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, señale a quién corresponde la ordenación general de pagos en el ámbito de la Administración de la Generalitat:","options":{"A":"A los habilitados de cada conselleria.","B":"Al titular de la conselleria competente en materia de hacienda.","C":"A las Subsecretarías de cada conselleria.","D":"A las personas titulares de cada conselleria."},"correct":"B","explanation":"La ordenación general de pagos de la Administración de la Generalitat corresponde a la persona titular de la conselleria competente en materia de hacienda, conforme al artículo 66 de la Ley 1/2015.","page":null,"topicNumber":17,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-1952"},{"number":38,"question":"Señale la respuesta correcta de acuerdo con lo dispuesto en la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones:","options":{"A":"El compromiso o disposición del gasto es el acto mediante el que se declara la existencia de un crédito exigible contra la Hacienda Pública de la Generalitat.","B":"El compromiso o disposición del gasto inicia el procedimiento de ejecución del gasto.","C":"La aprobación del gasto es el acto por el que se autoriza la realización de un gasto por cuantía cierta o aproximada, reservándose, a tal fin, la totalidad o una parte de un crédito presupuestario.","D":"La aprobación del gasto es un acto con relevancia jurídica para terceros."},"correct":"C","explanation":"El artículo 58 define la aprobación del gasto como el acto que autoriza realizar un gasto por cuantía cierta o aproximada y reserva para ello todo o parte de un crédito presupuestario.","page":null,"topicNumber":18,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2019/06/07/77/con"},{"number":39,"question":"De acuerdo con la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, las fases de gestión del presupuesto de ingresos son las siguientes:","options":{"A":"Compromiso de ingreso, reconocimiento del derecho y propuesta de ingreso.","B":"Reconocimiento del derecho e ingreso material.","C":"Compromiso de ingreso, reconocimiento del derecho e ingreso material.","D":"Reconocimiento del derecho y propuesta de ingreso."},"correct":"D","explanation":"El artículo 65 enumera dos fases de gestión de ingresos: reconocimiento del derecho y propuesta de ingreso.","page":null,"topicNumber":18,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2019/06/07/77/con"},{"number":40,"question":"El Decreto 77/2019, de 7 de junio, del Consell, de regulación del procedimiento de gestión del presupuesto de la Generalitat, establece que el crédito del Capítulo VI se gestionará a través de:","options":{"A":"Los proyectos incluidos en el anexo de inversiones reales.","B":"Las líneas incluidas en el anexo de inversiones reales.","C":"Las líneas incluidas en el anexo de subvenciones corrientes.","D":"Las líneas incluidas en el anexo de subvenciones de capital."},"correct":"A","explanation":"El artículo 3 del Decreto 77/2019 establece que los créditos del capítulo VI se gestionan mediante los proyectos incluidos en el anexo de inversiones reales.","page":null,"topicNumber":18,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2019/06/07/77/con"},{"number":41,"question":"El Decreto 77/2019, de 7 de junio, del Consell, de regulación del procedimiento de gestión del presupuesto de la Generalitat, es de aplicación:","options":{"A":"A la Administración de la Generalitat.","B":"A la Administración de la Generalitat y a sus organismos autónomos.","C":"A la Administración de la Generalitat y a los sujetos y entidades que conforman el sector público instrumental de la Generalitat.","D":"A la Presidencia de la Generalitat y a las distintas consellerias."},"correct":"B","explanation":"El Decreto 77/2019 se aplica a la Administración de la Generalitat y a sus organismos autónomos, según su artículo 1.","page":null,"topicNumber":18,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2019/06/07/77/con"},{"number":42,"question":"De acuerdo con el Decreto 77/2019, de 7 de junio, del Consell, de regulación del procedimiento de gestión del presupuesto de la Generalitat, las retribuciones del personal objeto de contratación temporal o nombramiento interino para sustituir los procesos de riesgo durante el embarazo, se imputarán al concepto:","options":{"A":"142.","B":"143.","C":"145.","D":"146."},"correct":"D","explanation":"El Decreto 77/2019 asigna al concepto 146 las retribuciones del personal temporal o interino que sustituye procesos de riesgo durante el embarazo.","page":null,"topicNumber":18,"officialSource":"https://dogv.gva.es/es/eli/es-vc/d/2019/06/07/77/con"},{"number":43,"question":"En relación a LibreOffice Writer ¿cuál de las siguientes afirmaciones es correcta?:","options":{"A":"La combinación de teclas Ctrl+W cierra la ventana.","B":"La combinación de teclas Ctrl+C corta el texto seleccionado.","C":"La combinación de teclas Ctrl+E selecciona el texto de un párrafo.","D":"La combinación de teclas Ctrl+B, muestra el diálogo de Buscar y Reemplazar."},"correct":"A","explanation":"En Writer, Ctrl+W cierra la ventana o el documento activo. Ctrl+C copia; Ctrl+B no abre el diálogo de Buscar y reemplazar.","page":null,"topicNumber":23,"officialSource":"https://help.libreoffice.org/latest/es/text/shared/02/10100000.html?DbPAR=WRITER&System=WIN"},{"number":44,"question":"¿Cuál de los siguientes resultados proporcionará la operación de LibreOffice Calc =CONTARA(A1:A6) situada en una celda?","options":{"A":"Sumará los valores de las celdas A1 hasta la A6.","B":"Sumará los valores de las celdas A1 y A6.","C":"Contará cuántas celdas entre la A1 y la A6 contienen valores.","D":"Contará cuántas celdas hay entre A1 y A6."},"correct":"C","explanation":"La función CONTARA cuenta cuántas celdas no están vacías en el rango A1:A6; no suma sus contenidos ni cuenta solo los extremos.","page":null,"topicNumber":23,"officialSource":"https://help.libreoffice.org/latest/es/text/scalc/01/04060181.html?DbPAR=SHARED&System=WIN"},{"number":45,"question":"Trabajando en LibreOffice Calc ¿cuál de las siguientes fórmulas escribiremos para obtener el producto del valor de la celda B2 por el valor de la celda B3?","options":{"A":"PRODUCTO(B2:B3)","B":"=B2*B3","C":"B2*B3","D":"=B2*B3"},"correct":"D","explanation":"La fórmula debe comenzar por el signo igual y usar el operador de multiplicación: =B2*B3. El JSON muestra esa misma fórmula tanto en B como en D; la plantilla marca D, pero B parece duplicada y también sería válida tal como está escrita.","page":null,"topicNumber":23,"officialSource":"https://books.libreoffice.org/en/CG262/CG26202-EnteringandEditingData.html"},{"number":46,"question":"La Constitución Española de 1978 garantiza:","options":{"A":"El principio de legalidad, la jerarquía normativa, la publicidad de las normas, la retroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales, la seguridad jurídica, la responsabilidad y la interdicción de la arbitrariedad de los poderes públicos.","B":"El principio de legalidad, la jerarquía normativa, la publicidad de las normas, la irretroactividad de las disposiciones sancionadoras favorables o restrictivas de derechos individuales, la seguridad jurídica, la responsabilidad y la interdicción de la arbitrariedad de los poderes públicos.","C":"El principio de legalidad, la jerarquía normativa, la publicidad de las normas, la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales, la seguridad jurídica, la responsabilidad y la interdicción de la arbitrariedad de los poderes públicos.","D":"El principio de legalidad, la jerarquía normativa, la publicidad de las normas, la retroactividad de las disposiciones sancionadoras favorables o restrictivas de derechos individuales, la seguridad jurídica, la responsabilidad y la interdicción de la arbitrariedad de los poderes públicos."},"correct":"C","explanation":"El artículo 9.3 garantiza, entre otros, la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales, además de seguridad jurídica y responsabilidad.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":47,"question":"Según la Constitución Española de 1978, todos tienen derecho a sindicarse libremente, si bien:","options":{"A":"La Ley podrá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar y regulará las peculiaridades de su ejercicio para los funcionarios públicos. La libertad sindical comprende el derecho a fundar sindicatos y a afiliarse al de su elección, así como el derecho de los sindicatos a formar confederaciones y a fundar organizaciones sindicales internacionales o a afiliarse a las mismas. Nadie podrá ser obligado a afiliarse a un sindicato.","B":"La Ley podrá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar y regulará las peculiaridades de su ejercicio para los funcionarios públicos. La libertad sindical comprende el derecho a fundar sindicatos y a afiliarse al de su elección, así como el derecho de los sindicatos a formar confederaciones y a fundar organizaciones sindicales nacionales o a afiliarse a las mismas. Nadie podrá ser obligado a afiliarse a un sindicato.","C":"La Ley deberá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar y regulará las peculiaridades de su ejercicio para los funcionarios públicos. La libertad sindical comprende el derecho a fundar sindicatos y a afiliarse al de su elección, así como el derecho de los sindicatos a formar confederaciones y a fundar organizaciones sindicales internacionales o a afiliarse a las mismas. Nadie podrá ser obligado a afiliarse a un sindicato.","D":"La Ley no podrá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar y regulará las peculiaridades de su ejercicio para los funcionarios públicos. La libertad sindical comprende el derecho a fundar sindicatos y a afiliarse al de su elección, así como el derecho de los sindicatos a formar confederaciones y a fundar organizaciones sindicales internacionales o a afiliarse a las mismas. Nadie podrá ser obligado a afiliarse a un sindicato."},"correct":"A","explanation":"El artículo 28.1 permite a la ley limitar o exceptuar la libertad sindical para las Fuerzas o Institutos armados y cuerpos sometidos a disciplina militar; no impone que deba hacerlo.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":48,"question":"De acuerdo con la Constitución Española de 1978, indique la respuesta correcta:","options":{"A":"Todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de igualdad y capacidad que, en ningún caso, tendrá alcance confiscatorio.","B":"Todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de igualdad y progresividad que, en todo caso, tendrá alcance confiscatorio.","C":"Todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de igualdad y capacidad que, en todo caso, tendrá alcance confiscatorio.","D":"Todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de igualdad y progresividad que, en ningún caso, tendrá alcance confiscatorio."},"correct":"D","explanation":"El artículo 31.1 establece un sistema tributario justo inspirado en igualdad y progresividad, que en ningún caso tendrá alcance confiscatorio.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":49,"question":"Según la Constitución Española de 1978, indique la respuesta correcta:","options":{"A":"Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey.","B":"Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos. En su defecto, lo nombrará el Congreso de los Diputados, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey.","C":"Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey.","D":"Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey."},"correct":"C","explanation":"El artículo 60.1 señala que, si el Rey difunto no nombró tutor en testamento, lo serán el padre o la madre mientras permanezcan viudos; en su defecto lo nombran las Cortes Generales. La opción C recoge además los requisitos del tutor testamentario.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":50,"question":"Según la Constitución Española de 1978, indique la respuesta correcta:","options":{"A":"Las elecciones tendrán lugar entre los treinta días y sesenta días desde la terminación del mandato. El Congreso electo deberá ser convocado dentro de los veinticinco días siguientes a la celebración de las elecciones.","B":"Las elecciones tendrán lugar entre los treinta días y setenta días desde la terminación del mandato. El Congreso electo deberá ser convocado dentro de los veinticinco días siguientes a la celebración de las elecciones.","C":"Las elecciones tendrán lugar entre los treinta días y sesenta días desde la terminación del mandato. El Congreso electo deberá ser convocado dentro de los treinta días siguientes a la celebración de las elecciones.","D":"Las elecciones tendrán lugar entre los treinta días y setenta días desde la terminación del mandato. El Congreso electo deberá ser convocado dentro de los treinta días siguientes a la celebración de las elecciones."},"correct":"A","explanation":"El artículo 68.6 fija las elecciones entre treinta y sesenta días desde la terminación del mandato y ordena convocar el Congreso electo dentro de los veinticinco días siguientes a las elecciones.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":51,"question":"Según la Constitución Española de 1978, aprobado un proyecto de ley ordinaria u orgánica por el Congreso de los Diputados, su Presidente dará inmediata cuenta del mismo al Presidente del Senado, el cual lo someterá a la deliberación de éste. Indique la respuesta correcta:","options":{"A":"El Senado en el plazo de dos meses, a partir del día siguiente de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo. El veto deberá ser aprobado por mayoría absoluta. El proyecto no podrá ser sometido al Rey para sanción sin que el Congreso ratifique por mayoría absoluta, en caso de veto, el texto inicial, o por mayoría simple, una vez transcurridos dos meses desde la interposición del mismo, o se pronuncie sobre las enmiendas, aceptándolas o no por mayoría simple.","B":"El Senado en el plazo de dos meses, a partir del día de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo. El veto deberá ser aprobado por mayoría absoluta. El proyecto no podrá ser sometido al Rey para sanción sin que el Congreso ratifique por mayoría absoluta, en caso de veto, el texto inicial, o por mayoría simple, una vez transcurridos tres meses desde la interposición del mismo, o se pronuncie sobre las enmiendas, aceptándolas o no por mayoría simple.","C":"El Senado en el plazo de dos meses, a partir del día de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo. El veto deberá ser aprobado por mayoría simple. El proyecto no podrá ser sometido al Rey para sanción sin que el Congreso ratifique por mayoría absoluta, en caso de veto, el texto inicial, o por mayoría simple, una vez transcurridos tres meses desde la interposición del mismo, o se pronuncie sobre las enmiendas, aceptándolas o no por mayoría simple.","D":"El Senado en el plazo de dos meses, a partir del día de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo. El veto deberá ser aprobado por mayoría absoluta. El proyecto no podrá ser sometido al Rey para sanción sin que el Congreso ratifique por mayoría absoluta, en caso de veto, el texto inicial, o por mayoría simple, una vez transcurridos dos meses desde la interposición del mismo, o se pronuncie sobre las enmiendas, aceptándolas o no por mayoría simple."},"correct":"D","explanation":"El artículo 90.2 da al Senado dos meses desde la recepción del texto para vetar o enmendarlo; el veto requiere mayoría absoluta y el Congreso puede levantarlo con las mayorías indicadas. La opción D coincide con el cómputo constitucional del plazo.","page":null,"topicNumber":2,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":52,"question":"Según la Constitución Española de 1978, el Gobierno se compone:","options":{"A":"Exclusivamente del Presidente y los Vicepresidentes.","B":"Exclusivamente del Presidente y los Ministros.","C":"Del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley.","D":"Del Presidente, de los Vicepresidentes, en todo caso, de los Ministros y de los demás miembros que establezca la ley."},"correct":"C","explanation":"El artículo 98.1 establece que el Gobierno se compone del Presidente, los Vicepresidentes en su caso, los Ministros y los demás miembros que establezca la ley.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":53,"question":"De acuerdo con la Constitución Española de 1978, el Gobierno responde en su gestión política:","options":{"A":"Mancomunadamente ante las Cortes Generales.","B":"Subsidiariamente ante el Senado.","C":"Solidariamente ante el Congreso de los Diputados.","D":"No responde en ningún caso solidariamente."},"correct":"C","explanation":"El artículo 108 establece que el Gobierno responde solidariamente de su gestión política ante el Congreso de los Diputados.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":54,"question":"Según la Constitución Española de 1978, el Gobierno cesante continuará en funciones:","options":{"A":"Sin límite de tiempo.","B":"Hasta la toma de posesión del nuevo Gobierno.","C":"Hasta la celebración de nuevas elecciones.","D":"No puede continuar en funciones en ningún caso."},"correct":"B","explanation":"El artículo 101.2 mantiene al Gobierno cesante en funciones hasta la toma de posesión del nuevo Gobierno.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":55,"question":"Según establece la Constitución Española de 1978, el Ministerio Fiscal:","options":{"A":"Tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los españoles y del interés general tutelado por la ley, de oficio o a petición de los interesados.","B":"Ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación e independencia jerárquica y con sujeción, en todo caso, a los de coordinación e imparcialidad.","C":"Tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de la Justicia y procurar la satisfacción del interés nacional.","D":"Ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad."},"correct":"D","explanation":"El artículo 124.2 dispone que el Ministerio Fiscal actúa mediante órganos propios, conforme a unidad de actuación y dependencia jerárquica, y sujeto a legalidad e imparcialidad.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":56,"question":"La Constitución Española de 1978, en su título VI, \"Del Poder Judicial\", establece:","options":{"A":"Los ciudadanos podrán ejercer la acción jurídica y participar en la Administración popular mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la ley determina, así como en los Tribunales consuetudinarios y tradicionales.","B":"Los ciudadanos podrán ejercer la acción popular y participar en la Administración de Justicia mediante la institución del Jurado, en la forma y con respecto a todo tipo de procesos que la ley determina, así como en los Tribunales consuetudinarios y tradicionales.","C":"La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente, en los términos que la ley establezca.","D":"La policía judicial depende de los Jueces, de los Tribunales y del Ministerio del Interior en sus funciones de averiguación del delito y descubrimiento y aseguramiento del detenido, en los términos que la ley establezca."},"correct":"C","explanation":"El artículo 126 establece que la policía judicial depende de Jueces, Tribunales y Ministerio Fiscal en sus funciones de investigación del delito y aseguramiento del delincuente.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":57,"question":"Según el Título IX de la Constitución Española de 1978, señale la respuesta correcta:","options":{"A":"Los miembros del Tribunal Constitucional deberán ser nombrados entre Magistrados y Fiscales, Profesores de Universidad, funcionarios públicos y Abogados, todos ellos juristas de reconocida competencia con más de quince años de ejercicio profesional.","B":"El Congreso podrá impugnar ante el Tribunal Constitucional las disposiciones y resoluciones adoptadas por los órganos de las Comunidades Autónomas. La impugnación producirá la suspensión de la disposición o resolución recurrida, pero el Tribunal, en su caso, deberá ratificarla o levantarla en un plazo no superior a cinco meses.","C":"Los miembros del Tribunal Constitucional serán designados por un período de doce años y se renovarán por terceras partes cada tres.","D":"Las sentencias del Tribunal Constitucional se publicarán en el boletín oficial del Estado con los votos particulares, si los hubiere. Tienen el valor de cosa juzgada a partir del día de su publicación y no cabe recurso alguno contra ellas."},"correct":"A","explanation":"El artículo 159.2 exige que los miembros del Tribunal Constitucional sean juristas de reconocida competencia con más de quince años de ejercicio profesional.","page":null,"topicNumber":3,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":58,"question":"Según lo establecido en el Título VIII de la Constitución Española de 1978, las Cortes Generales, mediante ley orgánica, podrán, por motivos de interés nacional:","options":{"A":"Autorizar la constitución de una comunidad autónoma cuando su ámbito territorial supere el de una provincia y reúna las condiciones del apartado 1 del artículo 143.","B":"Autorizar la constitución de una comunidad autónoma cuando su ámbito territorial no supere el de una provincia y no reúna las condiciones del apartado 1 del artículo 143.","C":"Autorizar o acordar, en su caso, un Estatuto de autonomía para territorios que estén integrados en la organización provincial.","D":"Redactar y aprobar, en su caso, un Estatuto de autonomía para territorios que no estén integrados en la organización provincial."},"correct":"B","explanation":"El artículo 144 permite a las Cortes Generales, mediante ley orgánica y por motivos de interés nacional, autorizar la constitución de una comunidad autónoma en los supuestos de la opción B.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":59,"question":"De acuerdo con la Constitución Española de 1978, las Comunidades Autónomas podrán asumir competencias en las siguientes materias:","options":{"A":"Los puertos y aeropuertos que desarrollen actividades comerciales.","B":"Fomento y coordinación general de la investigación científica y técnica.","C":"Legislación sobre propiedad intelectual e industrial.","D":"Los montes y aprovechamientos forestales."},"correct":"D","explanation":"El artículo 148.1.8 permite a las comunidades autónomas asumir competencias en montes y aprovechamientos forestales. Las otras opciones se refieren a competencias estatales o compartidas distintas.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":60,"question":"Señale la respuesta correcta, según lo establecido en el Título VIII de la Constitución Española de 1978:","options":{"A":"El Estado se organiza territorialmente en municipios y comarcas, en provincias y en Comunidades Autónomas.","B":"El Estado podrá dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las Comunidades Autónomas, aún en el caso de materias atribuidas a la competencia de éstas, cuando así lo exija el interés general. Corresponde a las Cortes Generales, por mayoría de dos tercios de cada Cámara, la apreciación de esta necesidad.","C":"Transcurridos cinco años, y mediante la reforma de sus Estatutos, las Comunidades Autónomas podrán ampliar sucesivamente sus competencias dentro del marco establecido en el artículo 149.","D":"Aprobado un proyecto de Estatuto por la Asamblea de Parlamentarios, se remitirá a la Comisión Constitucional de las Cortes Generales, la cual, dentro del plazo de dos meses, lo examinará con el concurso y asistencia de una delegación de la Asamblea proponente para determinar de común acuerdo su formulación definitiva."},"correct":"C","explanation":"El artículo 148.2 permite ampliar competencias, tras cinco años y mediante reforma del Estatuto, dentro del marco del artículo 149 de la Constitución.","page":null,"topicNumber":1,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"},{"number":61,"question":"De acuerdo con Ley Orgánica 5/1982, de 1 de julio, de Estatuto de Autonomía de la Comunidad Valenciana, la Ley Electoral Valenciana garantizará un número mínimo de Diputados por cada circunscripción provincial, indique la respuesta correcta:","options":{"A":"10 diputados.","B":"15 diputados.","C":"20 diputados.","D":"5 diputados."},"correct":"C","explanation":"El artículo 23.1 del Estatut fija en veinte el mínimo de diputados por circunscripción provincial.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-6472"},{"number":62,"question":"De acuerdo con Ley Orgánica 5/1982, de 1 de julio, de Estatuto de Autonomía de la Comunidad Valenciana, Les Corts adoptan acuerdos con la presencia, al menos, de:","options":{"A":"Un tercio de los Diputados y Diputadas.","B":"La mitad más uno de los Diputados y Diputadas.","C":"Un tercio más uno de los Diputados y Diputadas.","D":"La mayoría de los grupos parlamentarios."},"correct":"B","explanation":"El artículo 26.1 del Estatut exige la presencia de la mitad más uno de los diputados y diputadas para que Les Corts adopten acuerdos.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-6472"},{"number":63,"question":"De acuerdo con Ley Orgánica 5/1982, de 1 de julio, de Estatuto de Autonomía de la Comunidad Valenciana, el presidente del Tribunal Superior de Justicia de la Comunitat Valenciana será nombrado por el Rey a propuesta de:","options":{"A":"El Consell.","B":"El Consejo General del Poder Judicial.","C":"El presidente de la Generalitat.","D":"La Conselleria de Justicia."},"correct":"B","explanation":"El artículo 33 del Estatut dispone que el Rey nombra al presidente del Tribunal Superior de Justicia de la Comunitat Valenciana a propuesta del Consejo General del Poder Judicial.","page":null,"topicNumber":4,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-6472"},{"number":64,"question":"Según la Ley 5/1983, de 30 de diciembre, del Consell, al President de la Generalitat, como más alto representante de la Comunitat Valenciana, le corresponden las siguientes funciones. Señale la respuesta incorrecta:","options":{"A":"Designar representante de la Comunitat Valenciana en el Patronato del Archivo de la Corona de Aragón.","B":"Solicitar de la Administración del Estado, previo acuerdo de les Corts, la transferencia o delegación de competencias previstas en los apartados 2 y 3 del artículo 60 del Estatut d'Autonomia de la Comunitat Valenciana.","C":"Nombrar los altos cargos de la Comunitat Valenciana que las Leyes determinen.","D":"Representar a la Comunitat Valenciana en el Comité de las Regiones de la Unión Europea, de conformidad con lo previsto en el artículo 61.3.c) del Estatut d'Autonomia."},"correct":"B","explanation":"La opción B es incorrecta: la función presidencial prevista en la Ley 5/1983 requiere acuerdo del Consell, no acuerdo de Les Corts, para solicitar determinadas transferencias o delegaciones al Estado.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":65,"question":"Según la Ley 5/1983, de 30 de diciembre, del Consell, en uso de sus funciones ejecutivas y administrativas, compete al Consell. Señale la respuesta correcta:","options":{"A":"El ejercicio de las facultades que el Estatuto de Autonomía o Ley de Les Corts le atribuya en lo que se refiere a la actividad de las Diputaciones Provinciales y demás entes locales..","B":"Ejercer la potestad reglamentaria, de acuerdo con la Constitución Española, el Estatut d'Autonomia de la Comunitat Valenciana y las Leyes.","C":"Proponer a Les Corts la creación de personas jurídicas públicas y privadas o, en su caso, crearlas, para el ejercicio de competencias de la Generalitat.","D":"Acordar la comparecencia y personación en los recursos y en las cuestiones de inconstitucionalidad que afecten a la Comunitat Valenciana."},"correct":"C","explanation":"El artículo 17 de la Ley 5/1983 atribuye al Consell proponer a Les Corts la creación de personas jurídicas públicas y privadas o crearlas, en su caso, para ejercer competencias de la Generalitat.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":66,"question":"Según la Ley 5/1983, de 30 de diciembre, del Consell, el President electo comenzará a ejercer sus funciones:","options":{"A":"A partir del día de la publicación en el «Boletin Oficial del Estado y en el <<Diario Oficial de la Comunitat Valenciana de su nombramiento por el Rey.","B":"A partir del día siguiente de la publicación en el «Boletin Oficial del Estado>>> de su nombramiento por el Rey.","C":"A partir del día de la publicación en el «Boletin Oficial del Estado>> de su nombramiento por el Rey.","D":"A partir del día siguiente de la publicación en el «Boletin Oficial del Estado y en el <<<Diario Oficial de la Comunitat Valenciana>> de su nombramiento por el Rey."},"correct":"C","explanation":"El artículo 16 de la Ley 5/1983 establece que el President electo comienza sus funciones el día de la publicación de su nombramiento por el Rey en el BOE.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":67,"question":"Según la Ley 5/1983, de 30 de diciembre, del Consell, los consellers como miembros del Consell y Jefes de Departamento tienen las siguientes funciones. Señale la respuesta incorrecta:","options":{"A":"Disponer los gastos propios de los servicios de su conselleria dentro de los límites legales y presupuestarios y la ordenación de pagos correspondientes.","B":"Ejercer la potestad reglamentaria en las materias propias de su conselleria, en forma de Órdenes de la Conselleria.","C":"Proponer al Consell, para su aprobación, la estructura y organización de sus respectivas Consellerias.","D":"Formular motivadamente el proyecto de Presupuesto de la Conselleria."},"correct":"D","explanation":"El artículo 28 atribuye a los consellers formular motivadamente el anteproyecto de presupuesto de su conselleria. La opción D dice proyecto, no anteproyecto, por eso es incorrecta.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":68,"question":"Según la Ley 5/1983, de 30 de diciembre, del Consell, son funciones de los Directores Generales. Señale la respuesta correcta:","options":{"A":"Vigilar, fiscalizar y supervisar el funcionamiento de todas las dependencias a su cargo.","B":"Elaborar proyectos o planes de actuación y programas de necesidades de la Consellería.","C":"Resolver los recursos que se interpongan contra las Resoluciones de los Centros Directivos que estén bajo su dependencia y cuyos actos no agoten la vía administrativa.","D":"Proponer normas generales sobre adquisición de material y cuantas disposiciones afecten al funcionamiento de los servicios."},"correct":"A","explanation":"La Ley 5/1983 atribuye a los directores generales vigilar, fiscalizar y supervisar las dependencias a su cargo; corresponde a la opción A.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":69,"question":"Según la Ley 5/1983, de 30 de diciembre, del Consell, ¿ante quien se exigirá la responsabilidad penal y civil del president de la Generalitat y de los miembros del Consell?. Señale la respuesta correcta","options":{"A":"Ante el Tribunal Supremo.","B":"Ante la Audiencia Nacional.","C":"Ante el Tribunal Superior de Justicia de la Comunitat Valenciana o, en su caso, ante el Tribunal Supremo.","D":"Ante el Tribunal Superior de Justicia de la Comunitat Valenciana."},"correct":"C","explanation":"La responsabilidad penal y civil del President y de los miembros del Consell se exige ante el Tribunal Superior de Justicia de la Comunitat Valenciana o, en su caso, ante el Tribunal Supremo, conforme al Estatut y a la Ley 5/1983.","page":null,"topicNumber":5,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-1984-3460"},{"number":70,"question":"De conformidad con el Tratado de la Unión europea (TUE), indique la respuesta correcta:","options":{"A":"El ejercicio de las competencias de la Unión se rige por los principios de solidaridad y proporcionalidad.","B":"En virtud del principio de atribución toda competencia no atribuida a los Estados miembros corresponde a la Unión en los Tratados.","C":"La Unión reconoce los derechos, libertades y principios enunciados en la Carta de los Derechos Fundamentales de la Unión Europea de 7 de diciembre de 2000, la cual tendrá el mismo valor jurídico que los Tratados.","D":"En virtud del principio de proporcionalidad, el contenido y la forma de la acción de la Unión podrá exceder de lo necesario para alcanzar los objetivos de los Tratados."},"correct":"C","explanation":"El artículo 6.1 del TUE reconoce a la Carta de los Derechos Fundamentales de la Unión el mismo valor jurídico que a los Tratados.","page":null,"topicNumber":7,"officialSource":"https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012M/TXT"},{"number":71,"question":"En relación con la legislación de la Unión Europea, son instrumentos jurídicos vinculantes:","options":{"A":"Reglamento, Directiva y Decisión.","B":"Reglamento, Recomendación y Dictamen.","C":"Directiva, Dictamen y Decisión.","D":"Directiva, Reglamento y Recomendación."},"correct":"A","explanation":"El artículo 288 del TFUE considera vinculantes los reglamentos, las directivas y las decisiones; las recomendaciones y los dictámenes no son vinculantes.","page":null,"topicNumber":7,"officialSource":"https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012E/TXT"},{"number":72,"question":"De acuerdo con el Tratado de Funcionamiento de la Unión Europea, indique cuándo entran en vigor las Directivas publicadas en el DOUE:","options":{"A":"En la fecha que fijen o en su defecto a los 10 días desde su publicación.","B":"A los 15 días de su publicación.","C":"A los 30 días de su publicación.","D":"En la fecha que fijen o en su defecto a los 20 días desde su publicación."},"correct":"D","explanation":"El artículo 297.2 del TFUE dispone que, si una directiva no fija fecha de entrada en vigor, entra en vigor a los veinte días de su publicación en el Diario Oficial de la Unión Europea.","page":null,"topicNumber":7,"officialSource":"https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012E/TXT"},{"number":73,"question":"En el Título Preliminar de la Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género, se articula un principio rector que establece:","options":{"A":"Fortalecer las medidas de sensibilización ciudadana de prevención, dotando a los poderes públicos de instrumentos eficaces en el ámbito educativo, servicios sociales, sanitario, publicitario y mediático.","B":"Consagrar derechos de las mujeres, exigibles ante las Administraciones Públicas, y así asegurar una atención jurídica integral.","C":"Garantizar derechos relativos a la asistencia sanitaria para las mujeres víctimas de violencia de género, con el fin de facilitar su integración social.","D":"Promover la participación de las entidades y asociaciones para fortalecer el marco penal y procesal vigente para asegurar una protección integral."},"correct":"A","explanation":"El artículo 2.a de la LO 1/2004 establece como principio rector reforzar la sensibilización y prevención mediante instrumentos en educación, servicios sociales, sanidad, publicidad y medios de comunicación.","page":null,"topicNumber":8,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760"},{"number":74,"question":"Según la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, en su Título Preliminar, ¿qué artículos de la Constitución Española están citados, y en base a cuáles se desarrolla esta ley?","options":{"A":"Artículos 11.1 y 23 de la Constitución Española.","B":"Artículos 8.2 y 13 de la Constitución Española.","C":"Artículos 10.2 y 23 de la Constitución Española.","D":"Artículos 9.2 y 14 de la Constitución Española."},"correct":"D","explanation":"El artículo 1 de la LO 3/2007 desarrolla la igualdad efectiva sobre la base de los artículos 9.2 y 14 de la Constitución Española.","page":null,"topicNumber":8,"officialSource":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115"},{"number":75,"question":"De acuerdo con el literal del artículo 42 de la Ley 9/2003, de 2 de abril, para la igualdad entre mujeres y hombres, la Generalitat velará, de manera específica, por:","options":{"A":"El cumplimiento del deber de guardar silencio en casos de acoso sexual.","B":"El cumplimiento de todos los compromisos acordados en las juntas de personal en materia de igualdad.","C":"El cumplimiento del principio de igualdad y no discriminación en la publicidad en los medios de comunicación social o cualquier otro medio de difusión.","D":"El cumplimiento del principio de igualdad en los centros de trabajo."},"correct":"C","explanation":"El artículo 42 de la Ley valenciana 9/2003 encomienda a la Generalitat velar específicamente por el cumplimiento del principio de igualdad y no discriminación en la publicidad difundida en medios de comunicación y otros medios.","page":null,"topicNumber":8,"officialSource":"https://dogv.gva.es/es/eli/es-vc/l/2003/04/02/9/con"}],"2022":[{"number":1,"question":"De acuerdo con lo establecido en la Constitución Española, el principio de irretroactividad garantizado en el artículo 9 abarca:","options":{"A":"A todas las normas de carácter general.","B":"A todas las disposiciones legales de cualquier orden.","C":"A las disposiciones sancionadoras no favorables o restrictivas de derechos individuales.","D":"A las disposiciones indicadas en la opción anterior, más aquellas que impongan penas privativas de libertad no superior a los seis años, o de multa cualquiera que fuese su cuantía."},"correct":"C","explanation":null,"page":null},{"number":2,"question":"De acuerdo con la Constitución Española, señale cual de los siguientes derechos podrá ser objeto de suspensión cuando se declaren los estados de excepción o de sitio:","options":{"A":"Derecho a la inviolabilidad del domicilio.","B":"Derecho a la producción y creación literaria.","C":"Derecho de asociación.","D":"Derecho a la educación."},"correct":"A","explanation":null,"page":null},{"number":3,"question":"De acuerdo con el artículo 54 de la Constitución Española, el Defensor del Pueblo:","options":{"A":"Es designado por el Gobierno de la Nación, al que dará cuenta.","B":"Es designado por las Cortes Generales, a las que dará cuenta.","C":"Es designado por el Congreso de los Diputados, al que dará cuenta.","D":"Es designado por el Rey, al que dará cuenta."},"correct":"B","explanation":null,"page":null},{"number":4,"question":"De acuerdo con la Constitución Española, los extranjeros:","options":{"A":"Gozarán en España de las libertades públicas que garantiza el Título I en los términos que establece la Constitución Española.","B":"Gozarán en España de las libertades públicas que garantiza el Título I en los términos que establezcan los reglamentos y la ley.","C":"Gozarán en España de las libertades públicas que garantiza el Título I en los términos que establezcan los tratados y la ley.","D":"Gozarán en España de las libertades públicas que garantiza el Título II."},"correct":"C","explanation":null,"page":null},{"number":5,"question":"Uno de los siguientes derechos, no está recogido en la sección 1ª «De los derechos fundamentales y de las libertades públicas» del Titulo I, Capítulo II de la Constitución Española:","options":{"A":"El derecho a la libertad religiosa.","B":"El derecho de reunión pacífica y sin armas.","C":"El derecho a la libertad de cátedra.","D":"El derecho a la protección de la salud."},"correct":"D","explanation":null,"page":null},{"number":6,"question":"De acuerdo con lo estipulado en el Título II de la Constitución Española, relativo a la Corona:","options":{"A":"La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.","B":"Las abdicaciones y renuncias en el orden sucesorio se resolverán por ley ordinaria.","C":"El Príncipe heredero podrá asumir la Regencia durante su minoría de edad.","D":"La Regencia podrá ejercerse por nacionales de cualquier Estado."},"correct":"A","explanation":null,"page":null},{"number":7,"question":"De acuerdo con el artículo 90 de la Constitución Española, el plazo de que dispone el Senado para oponer su veto o introducir enmiendas a un proyecto de ley aprobado por el Congreso de los Diputados es:","options":{"A":"Dos meses, a partir del día de la recepción del texto. Dicho plazo se reducirá a veinte días hábiles en los proyectos declarados urgentes por el Gobierno o por el Congreso de los Diputados.","B":"Dos meses, a partir del día de la aprobación por el Congreso. Dicho plazo se reducirá a veinte días hábiles en los proyectos declarados urgentes por el Gobierno o por el Congreso de los Diputados.","C":"Dos meses, a partir del día de la recepción del texto. Dicho plazo se reducirá a veinte días naturales en los proyectos declarados urgentes por el Gobierno o por el Congreso de los Diputados.","D":"Dos meses, a partir del día de la aprobación por el Congreso. El veto deberá ser aprobado por mayoría absoluta."},"correct":"C","explanation":null,"page":null},{"number":8,"question":"De conformidad con el artículo 113 de la Constitución Española y en relación con la moción de censura:","options":{"A":"Debe votarse en el plazo máximo de cinco días desde su presentación.","B":"Deberá votarse una vez transcurridos diez días desde su presentación.","C":"Deberá ser propuesta al menos por la cuarta parte de los Diputados.","D":"Podrán presentarse mociones alternativas durante los dos días siguientes a su presentación."},"correct":"D","explanation":null,"page":null},{"number":9,"question":"De acuerdo con el artículo 68 de la Constitución Española, el mandato de los Diputados termina:","options":{"A":"4 años después de su elección o el día de la celebración de las elecciones.","B":"4 años después de su nombramiento o el día de la disolución de la Cámara.","C":"4 años después de su elección o el día de la disolución de la Cámara.","D":"4 años después de su nombramiento o el día de la celebración de las elecciones."},"correct":"C","explanation":null,"page":null},{"number":10,"question":"De acuerdo con el Título V de la Constitución Española la propuesta de disolución de las Cámaras no podrá presentarse:","options":{"A":"Cuando esté en trámite una moción de censura.","B":"Cuando esté reunida la Diputación Permanente.","C":"En el primer período de sesiones.","D":"Sin el visto bueno del Rey."},"correct":"A","explanation":null,"page":null},{"number":11,"question":"Cuando los particulares sufran lesión en sus bienes y derechos a consecuencia del funcionamiento de los servicios públicos:","options":{"A":"Solo tendrán derecho a indemnización cuando sea la Administración Civil del Estado causante del perjuicio, en los términos establecidos por la ley.","B":"Tendrán derecho, en los términos establecidos por la ley, a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos.","C":"Tendrán derecho, en los términos establecidos por la ley, a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos.","D":"Tendrán derecho, en los términos establecidos por la ley, a indemnización en los casos de fuerza mayor."},"correct":"B","explanation":null,"page":null},{"number":12,"question":"De acuerdo con la Constitución Española, el Presidente del Gobierno:","options":{"A":"Previa deliberación del Consejo de Ministros, puede plantear ante las Cortes Generales la cuestión de confianza sobre su programa o sobre una declaración de política general.","B":"Previa comunicación al Consejo de Ministros, puede plantear ante el Congreso de los Diputados la cuestión de confianza sobre su programa o sobre una declaración de política general.","C":"Previa deliberación del Consejo de Ministros, puede plantear ante el Congreso de los Diputados la cuestión de confianza sobre su programa o sobre una declaración de política general.","D":"Previa comunicación al Consejo de Ministros, puede plantear ante el Senado la cuestión de confianza sobre su programa o sobre una declaración de política general."},"correct":"C","explanation":null,"page":null},{"number":13,"question":"Conforme a la Constitución Española, se puede interponer un recurso de amparo ante el Tribunal Constitucional para recabar la tutela de:","options":{"A":"La objeción de conciencia reconocida en el artículo 30 de la Constitución Española.","B":"Los derechos reconocidos en la sección II del Capítulo II del Título II de la Constitución Española.","C":"Derecho de protección de la salud.","D":"Derecho a una vivienda digna y adecuada."},"correct":"A","explanation":null,"page":null},{"number":14,"question":"De acuerdo con el artículo 159 de la Constitución Española, los miembros del Tribunal Constitucional serán designados por un período de:","options":{"A":"9 años y se renovarán por terceras partes cada 3.","B":"6 años y se renovarán por terceras partes cada 3.","C":"5 años y se renovarán por terceras partes cada 2.","D":"4 años y se renovarán por terceras partes cada 2."},"correct":"A","explanation":null,"page":null},{"number":15,"question":"De acuerdo con la Constitución Española, el Estado podrá transferir o delegar en las Comunidades Autónomas, mediante:","options":{"A":"Real Decreto, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza no sean susceptibles de transferencia o delegación.","B":"Ley orgánica, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.","C":"Ley orgánica, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza no sean susceptibles de transferencia o delegación.","D":"Real Decreto, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación."},"correct":"B","explanation":null,"page":null},{"number":16,"question":"De acuerdo con el artículo 141 de la Constitución Española, respecto de la provincia es cierto que:","options":{"A":"La provincia es una entidad local sin personalidad jurídica propia.","B":"Cualquier alteración de los límites provinciales ha de ser aprobada por el Gobierno.","C":"Cualquier alteración de los límites provinciales ha de ser aprobada exclusivamente por el Senado que es la cámara de representación territorial.","D":"Cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante Ley Orgánica."},"correct":"D","explanation":null,"page":null},{"number":17,"question":"De acuerdo con lo que establece la Constitución Española, el control de la actividad de los órganos de las Comunidades Autónomas, en lo relativo a lo económico y presupuestario se ejercerá por:","options":{"A":"El Tribunal Constitucional.","B":"El Gobierno.","C":"El Tribunal de Cuentas.","D":"La jurisdicción Contencioso Administrativa."},"correct":"C","explanation":null,"page":null},{"number":18,"question":"De acuerdo con la Ley Orgánica 5/1982, de 1 de julio, de Estatuto de Autonomía de la Comunidad Valenciana, la Generalitat tiene competencia exclusiva sobre las siguientes materias:","options":{"A":"Legislación sobre propiedad intelectual e industrial.","B":"Nacionalidad, inmigración, emigración, extranjería y derecho de asilo.","C":"Iluminación de costas y señales marítimas.","D":"Higiene."},"correct":"D","explanation":null,"page":null},{"number":19,"question":"Según el artículo 10 de la Ley Orgánica 5/1982, de 1 de julio, de Estatuto de Autonomía de la Comunitat Valenciana, la Carta de Derechos Sociales de la Comunitat Valenciana contendrá:","options":{"A":"El conjunto de principios, derechos y directrices que informen la actuación pública de la Generalitat en el ámbito de la política social.","B":"El conjunto de derechos y deberes que informen la actuación pública de la Generalitat en el ámbito de la política social.","C":"El conjunto de principios y derechos que informen la actuación pública de la Generalitat en el ámbito de la igualdad.","D":"El conjunto de valores y derechos universales de las personas que informen la actuación pública de la Generalitat en el ámbito de la política social."},"correct":"A","explanation":null,"page":null},{"number":20,"question":"De acuerdo con lo establecido en la Ley Orgánica 5/1982, de 1 de julio, de Estatuto de Autonomía de la Comunitat Valenciana, Les Corts aprobarán:","options":{"A":"Por mayoría simple, su Reglamento que tendrá rango de Ley. Igualmente, en la forma que determine el Reglamento, aprobarán los Estatutos de Gobierno y Régimen Interno de la Cámara.","B":"Por mayoría absoluta, su Reglamento que no tendrá rango de Ley. Igualmente, en la forma que determine el Reglamento, aprobarán los Estatutos de Gobierno y Régimen Interno de la Cámara.","C":"Por mayoría absoluta, su Reglamento que tendrá rango de Ley. Igualmente, en la forma que determine el Reglamento, aprobarán los Estatutos de Gobierno y Régimen Interno de la Cámara.","D":"Por mayoría simple, su Reglamento que no tendrá rango de Ley. Igualmente, en la forma que determine el Reglamento, aprobarán los Estatutos de Gobierno y Régimen Interno de la Cámara."},"correct":"C","explanation":null,"page":null},{"number":21,"question":"De acuerdo con el artículo 60 de la ley 5/1983, de 30 de diciembre, del Consell, la Administración Pública de la Generalitat:","options":{"A":"Se organiza y actúa con personalidad jurídica propia conforme a los criterios de eficacia, publicidad, jerarquía, descentralización, desconcentración y coordinación.","B":"Se organiza y actúa con personalidad jurídica propia conforme a los criterios de eficiencia, publicidad, jerarquía, descentralización, cooperación y coordinación.","C":"Se organiza y actúa con personalidad jurídica única conforme a los criterios de eficacia, publicidad, jerarquía, descentralización, desconcentración y coordinación.","D":"Se organiza y actúa con personalidad jurídica única conforme a los criterios de eficiencia, publicidad, jerarquía, descentralización, desconcentración y coordinación."},"correct":"C","explanation":null,"page":null},{"number":22,"question":"De acuerdo con la Ley 5/1983, de 30 de diciembre, del Consell, la responsabilidad penal y civil del President de la Generalitat y de los miembros del Consell se exigirá ante:","options":{"A":"El Tribunal Superior de Justicia de la Comunitat Valenciana o, en su caso, ante el Tribunal Constitucional.","B":"La Audiencia Provincial o, en su caso, ante el Tribunal Constitucional.","C":"El Tribunal Superior de Justicia de la Comunitat Valenciana o, en su caso, ante el Tribunal Supremo.","D":"El Tribunal Constitucional o, en su caso, ante el Tribunal Supremo."},"correct":"C","explanation":null,"page":null},{"number":23,"question":"De acuerdo con lo establecido en el artículo 63 de la Ley 5/1983, del Consell, son delegables las siguientes competencias del Consell:","options":{"A":"Las que procedan de una atribución expresa del Estatuto de Autonomía.","B":"Las que correspondan a los Consellers en su condición de miembros del Consell.","C":"Las que correspondan a relaciones con órganos del Estado, de otras Comunidades Autónomas o Les Corts.","D":"Son delegables en cualquier caso en las Comisiones Delegadas del Consell."},"correct":"D","explanation":null,"page":null},{"number":24,"question":"Según lo establecido en el artículo 68 de la Ley 5/1983, de 30 de diciembre, del Consell, los Secretarios autonómicos llevan a cabo las siguientes funciones ejecutivas:","options":{"A":"Elaborar proyectos o planes de actuación y programas de necesidades de la Conselleria.","B":"Resolver los recursos que se interpongan contra las Resoluciones de los Centros Directivos que estén bajo su dependencia y cuyos actos no agoten la vía administrativa.","C":"Informar los asuntos que cada Conseller deba someter al Pleno del Consell o al President.","D":"Dirigir y facilitar la formación de estadísticas acerca de las materias de competencia del Consell, en lo que afecte a cada Conselleria, en colaboración con el Instituto Valenciano de Estadística y el Instituto Nacional de Estadística u otros Organismos que se consideren convenientes."},"correct":"B","explanation":null,"page":null},{"number":25,"question":"De acuerdo con el artículo 28 de la Ley 5/1983, de 30 de diciembre, del Consell, no es función de los Consellers:","options":{"A":"Ejercer la potestad reglamentaria en las materias propias de su Conselleria, en forma de Órdenes de la Conselleria.","B":"Nombrar los altos cargos de su Conselleria.","C":"Ejecutar los acuerdos del Consell en el marco de sus competencias.","D":"Formular motivadamente el anteproyecto de Presupuesto de la Conselleria."},"correct":"B","explanation":null,"page":null},{"number":26,"question":"De acuerdo con el Tratado de funcionamiento de la Unión Europea ¿que acto jurídico de la Unión tiene un alcance general y será obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro?","options":{"A":"Los Reglamentos.","B":"La Directiva.","C":"La recomendación.","D":"La decisión."},"correct":"A","explanation":null,"page":null},{"number":27,"question":"De acuerdo con la normativa europea, cuál de los siguientes enunciados es incorrecto:","options":{"A":"La directiva obligará al Estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando, sin embargo, a las autoridades nacionales la elección de la forma y de los medios.","B":"La decisión será obligatoria en todos sus elementos. Cuando designe destinatarios, sólo será obligatoria para éstos.","C":"Las recomendaciones no son vinculantes.","D":"Los dictámenes son instrumentos que permiten a las instituciones hacer declaraciones de manera vinculante, es decir, imponer obligaciones legales a quienes se dirigen."},"correct":"D","explanation":null,"page":null},{"number":28,"question":"Según el Artículo 4 de la Ley 9/2003 de 2 de abril, de la Generalitat para la igualdad de mujeres y hombres:","options":{"A":"El Conseller competente en la materia, informará al Consell de las actuaciones llevadas a cabo para el cumplimiento de la presente Ley.","B":"El President de la Generalitat informará a las Corts Valencianes de las actuaciones llevadas a cabo para el cumplimiento de la presente Ley.","C":"El Consell de la Generalitat informará a las Corts Valencianes de las actuaciones llevadas a cabo para el cumplimiento de la presente Ley.","D":"El President de la Generalitat, informará al Consell de las actuaciones llevadas a cabo para el cumplimiento de la presente Ley."},"correct":"C","explanation":null,"page":null},{"number":29,"question":"De acuerdo con la Ley 9/2003, de 2 de abril, de la Generalitat, para la igualdad de mujeres y hombres, los informes de impacto de género:","options":{"A":"Serán elaborados por Les Corts previamente a la aprobación parlamentaria.","B":"Serán elaborados por el departamento o centro directivo que propone el anteproyecto de ley o proyecto de norma, plan o programa.","C":"Serán necesarios solo en el caso de aprobación de leyes de Les Corts.","D":"Su elaboración será libre sin estar sujeto a instrucciones y directrices previas."},"correct":"B","explanation":null,"page":null},{"number":30,"question":"La Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, respecto a la igualdad de trato y de oportunidades en el acceso al empleo, en la formación y en la promoción profesionales, y en las condiciones de trabajo, establece:","options":{"A":"El principio de igualdad de trato y de oportunidades entre mujeres y hombres no será aplicable en el ámbito del empleo en el sector privado.","B":"Se garantizará, en el acceso al empleo, incluso al trabajo por cuenta propia.","C":"No incluirá las condiciones retributivas ni las de despido.","D":"Constituirá discriminación en el acceso al empleo, una diferencia de trato basada en una característica relacionada con el sexo cuando, debido a la naturaleza de las actividades profesionales concretas o al contexto en el que se lleven a cabo, dicha característica constituya un requisito profesional esencial y determinante, siempre y cuando el objetivo sea legítimo y el requisito proporcionado."},"correct":"B","explanation":null,"page":null},{"number":31,"question":"De acuerdo con lo dispuesto en la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"Cuando la Administración no tenga por ciertos los hechos alegados por los interesados o la naturaleza del procedimiento lo exija, el instructor del mismo acordará la apertura de un período de prueba por un plazo no superior a treinta días ni inferior a diez, a fin de que puedan practicarse cuantas juzgue pertinentes.","B":"Los interesados, en un plazo no inferior a diez días ni superior a quince, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes.","C":"Cuando la notificación por medios electrónicos sea de carácter obligatorio, o haya sido expresamente elegida por el interesado, se entenderá rechazada cuando hayan transcurrido diez días desde la puesta a disposición de la notificación sin que se acceda a su contenido.","D":"El órgano al que corresponda la resolución del procedimiento, cuando la naturaleza de éste lo requiera, podrá acordar un período de información pública. A tal efecto, se publicará un anuncio en el Diario oficial correspondiente, donde se determinará el plazo para formular alegaciones, que en ningún caso podrá ser inferior a veinte días."},"correct":"C","explanation":null,"page":null},{"number":32,"question":"De acuerdo con lo dispuesto en la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, señale cuál de las siguientes afirmaciones es la correcta:","options":{"A":"La Administración no podrá convalidar en ningún caso los actos anulables.","B":"Los actos de la Administración son nulos de pleno derecho cuando así se establezca expresamente en una disposición con rango de Ley.","C":"Los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto no producirán los efectos de éste.","D":"Son nulos de pleno derecho los actos de las Administraciones Públicas que lesionen los derechos y libertades de los interesados."},"correct":"B","explanation":null,"page":null},{"number":33,"question":"De acuerdo con lo dispuesto en la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"Salvo que por una norma de rango legal se disponga otro cómputo, cuando los plazos se señalen por horas, se entiende que éstas son hábiles.","B":"Cuando razones de interés público lo aconsejen, se podrá acordar, de oficio o a petición del interesado, la aplicación al procedimiento de la tramitación de urgencia, por la cual se reducirán a la mitad todos los plazos establecidos para el procedimiento ordinario, salvo la presentación de recursos.","C":"Serán motivados, con sucinta referencia de hechos y fundamentos de derecho los actos que limiten derechos objetivos o intereses legítimos.","D":"Excepcionalmente, podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos favorables al interesado, siempre que los supuestos de hecho necesarios existieran ya en la fecha a que se retrotraiga la eficacia del acto y ésta no lesione derechos o intereses legítimos de otras personas."},"correct":"D","explanation":null,"page":null},{"number":34,"question":"De acuerdo con lo establecido en el artículo 6 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, sin perjuicio de las posibles prórrogas, los poderes inscritos en el registro electrónico general de apoderamientos, tendrán una validez determinada:","options":{"A":"Máxima de cuatro años a contar desde la fecha de inscripción.","B":"Máxima de seis años a contar desde el día siguiente a la fecha de inscripción.","C":"Máxima de tres años a contar desde el día siguiente a la fecha de inscripción.","D":"Máxima de cinco años a contar desde la fecha de inscripción."},"correct":"D","explanation":null,"page":null},{"number":35,"question":"De acuerdo con lo establecido en el artículo 21 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, el plazo para notificar la resolución expresa en los procedimientos iniciados de oficio se contará:","options":{"A":"Desde la fecha del acuerdo de iniciación.","B":"Desde la fecha en que la solicitud haya tenido entrada en el registro electrónico de la Administración u Organismo competente para su tramitación.","C":"Desde el día siguiente a la fecha en que la solicitud haya tenido entrada en el registro electrónico de la Administración u Organismo competente para su tramitación.","D":"Desde el día siguiente a la fecha del acuerdo de iniciación."},"correct":"A","explanation":null,"page":null},{"number":36,"question":"Según lo que establece el artículo 24 de la Ley 39/2015, de 1 de octubre, de Procedimiento Administrativo Común de las Administraciones Públicas, con relación al silencio administrativo en los procedimientos iniciados a solicitud del interesado:","options":{"A":"La desestimación por silencio administrativo tiene a todos los efectos la consideración de acto administrativo que pone fin al procedimiento.","B":"Cuando el procedimiento tenga por objeto el acceso a actividades o su ejercicio, la ley que disponga el carácter estimatorio del silencio deberá fundarse en la concurrencia de razones imperiosas de interés general.","C":"El sentido del silencio será estimatorio en los procedimientos de impugnación de actos y disposiciones y en los de revisión de oficio iniciados a solicitud de los interesados.","D":"Los actos administrativos producidos por silencio administrativo se podrán hacer valer tanto ante la Administración como ante cualquier persona física o jurídica, pública o privada."},"correct":"D","explanation":null,"page":null},{"number":37,"question":"De acuerdo con el artículo 52 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"La Administración no podrá convalidar, en ningún caso, los actos anulables.","B":"Si el vicio consistiera en incompetencia determinante de nulidad, la convalidación podrá realizarse por el órgano competente cuando sea superior jerárquico del que dictó el acto viciado.","C":"Si el vicio consistiese en la falta de alguna resolución, podrá ser convalidado el acto mediante el otorgamiento de la misma por el órgano competente.","D":"Si el vicio consistiese en la falta de alguna autorización, podrá ser convalidado el acto mediante el otorgamiento de la misma por el órgano competente."},"correct":"D","explanation":null,"page":null},{"number":38,"question":"Según lo que establece el artículo 57 la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, contra el acuerdo de acumulación podrá interponerse:","options":{"A":"Recurso de alzada.","B":"Recurso potestativo de reposición.","C":"No procederá recurso alguno.","D":"Recurso extraordinario de revisión."},"correct":"C","explanation":null,"page":null},{"number":39,"question":"De acuerdo con lo establecido en el artículo 77 de la Ley 39/2015 de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, cuando la prueba en un procedimiento consista en la emisión de un informe de un órgano administrativo, organismo público o Entidad de derecho público, se entenderá que éste tiene:","options":{"A":"Carácter vinculante.","B":"Carácter preceptivo.","C":"Carácter facultativo.","D":"Carácter no vinculante."},"correct":"B","explanation":null,"page":null},{"number":40,"question":"De acuerdo con lo establecido en la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, salvo que reste menos para su tramitación ordinaria, los procedimientos administrativos tramitados de manera simplificada deberán ser resueltos en:","options":{"A":"1 mes, a contar desde el día en que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.","B":"2 meses, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.","C":"Treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.","D":"Quince días, a contar desde el día en que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento."},"correct":"C","explanation":null,"page":null},{"number":41,"question":"De acuerdo con el artículo 102 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, qué medio de ejecución forzosa se aplicaría cuando se trate de actos que, por no ser personalísimos, puedan ser realizados por sujeto distinto del obligado:","options":{"A":"La multa coercitiva.","B":"La ejecución coercitiva.","C":"La ejecución subsidiaria.","D":"La compulsión sobre las personas."},"correct":"C","explanation":null,"page":null},{"number":42,"question":"De acuerdo con el artículo 107 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, la declaración de lesividad no podrá adoptarse una vez transcurridos:","options":{"A":"6 meses desde que se dictó el acto administrativo.","B":"1 año desde que se dictó el acto administrativo.","C":"2 años desde que se dictó el acto administrativo.","D":"4 años desde que se dictó el acto administrativo."},"correct":"D","explanation":null,"page":null},{"number":43,"question":"De acuerdo con la Ley 39/2015 de 1 de octubre del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"El plazo para la interposición del recurso de alzada será de un mes en todo caso.","B":"El recurso de alzada podrá interponerse contra resoluciones y actos que pongan fin a la vía administrativa.","C":"El recurso de alzada podrá interponerse ante el órgano que dictó el acto que se impugna o ante el competente para resolverlo.","D":"Las resoluciones y actos, cuando no pongan fin a la vía administrativa, podrán ser recurridos en alzada ante el órgano que dictó el acto que se recurre o ante el superior jerárquico."},"correct":"C","explanation":null,"page":null},{"number":44,"question":"De acuerdo con el artículo 125 de la Ley 39/2015 de 1 de octubre del Procedimiento Administrativo Común de las Administraciones Públicas, el recurso extraordinario de revisión podrá interponerse contra los actos firmes en vía administrativa:","options":{"A":"Ante el órgano administrativo que los dictó, que también será el competente para su resolución, cuando concurra alguna de las circunstancias descritas en la ley.","B":"Cuando al dictarlos se hubiera incurrido en error de hecho, que resulte de los propios documentos incorporados al expediente, en el plazo de tres meses desde la notificación de la resolución impugnada.","C":"Cuando aparezcan documentos de valor esencial para la resolución del asunto que, aunque sean posteriores, evidencien el error de la resolución recurrida, en el plazo de cuatro años siguientes a la fecha de notificación de la resolución impugnada.","D":"Ante el órgano administrativo que los dictó, pese a no ser el competente para su resolución."},"correct":"A","explanation":null,"page":null},{"number":45,"question":"Según lo establecido en la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"Los actos de las Administraciones Públicas son anulables cuando lesionen los derechos y libertades susceptibles de amparo constitucional.","B":"Serán anulables los actos que tengan un contenido imposible.","C":"El defecto de forma sólo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.","D":"Serán anulables los actos de las Administraciones Públicas dictados prescindiendo total y absolutamente del procedimiento legalmente establecido o de las normas que contienen las reglas esenciales para la formación de la voluntad de los órganos colegiados."},"correct":"C","explanation":null,"page":null},{"number":46,"question":"En relación con el ámbito de aplicación de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, están sujetas a esta ley:","options":{"A":"Los organismos públicos y entidades de derecho público vinculados o dependientes de las Administraciones Públicas.","B":"Las entidades de derecho privado vinculadas o dependientes de las Administraciones Públicas quedarán sujetas a lo dispuesto en las normas de esta Ley solo cuando ejerzan potestades administrativas.","C":"Las Universidades públicas se regirán por su normativa específica y supletoriamente por las previsiones de la presente Ley.","D":"Las Universidades públicas forman parte, a efectos de esta Ley, del sector público institucional."},"correct":"B","explanation":null,"page":null},{"number":47,"question":"De acuerdo con lo dispuesto en la Ley 40/2015 de 1 de octubre, de Régimen Jurídico del Sector Público:","options":{"A":"Si alguna disposición atribuye la competencia a una Administración, sin especificar el órgano que deba ejercerla, se entenderá que la facultad de instruir y resolver los expedientes corresponde a los órganos inferiores competentes por razón de la materia y del territorio.","B":"En ningún caso podrán ser objeto de delegación las competencias relativas a los asuntos que se refieran a relaciones con la Jefatura del Estado, el Gobierno de la Nación, la Presidencia de las Cortes Generales y los Consejos de Gobierno de las Comunidades Autónomas.","C":"En los supuestos de delegación de competencias en órganos dependientes jerárquicamente, el conocimiento de un asunto podrá ser avocado únicamente por el órgano delegante.","D":"Las delegaciones de competencias, la avocación y las encomiendas de gestión deberán publicarse en el Boletín Oficial del Estado, en el de la Comunidad Autónoma o en el de la Provincia, según la Administración a que pertenezca el órgano delegante."},"correct":"A","explanation":null,"page":null},{"number":48,"question":"Según Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público ¿dónde se entenderán adoptados los acuerdos de un órgano colegiado, cuando se asista a distancia?","options":{"A":"En el lugar donde tenga la sede la presidencia y, en su defecto, donde esté ubicada la sede del órgano colegiado.","B":"En el lugar donde tenga la sede el órgano colegiado y, en su defecto, donde esté ubicada la presidencia.","C":"En el lugar donde se encuentren la mayoría de los miembros que asisten a distancia.","D":"En el lugar donde se encuentren la mayoría de los miembros que asisten presencialmente y, en su defecto, donde esté ubicada la sede de la presidencia del órgano colegiado."},"correct":"B","explanation":null,"page":null},{"number":49,"question":"Según el artículo 9 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, los contratos de compraventa, donación, permuta, arrendamiento y demás negocios jurídicos análogos sobre bienes inmuebles, valores negociables y propiedades incorporales, a no ser que recaigan sobre programas de ordenador y deban ser calificados como contratos de suministro o servicio, tendrán siempre el carácter de contratos:","options":{"A":"Administrativos Especiales.","B":"Privados pero se regirán por la Ley de Contratos.","C":"Privados y se regirán por la legislación patrimonial.","D":"Administrativos pero se regirán por la legislación patrimonial."},"correct":"C","explanation":null,"page":null},{"number":50,"question":"Según el artículo 14 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, la concesión de obras es un contrato que tiene por objeto la realización por el concesionario de algunas de las prestaciones a que se refiere el contrato de obras:","options":{"A":"Incluidas las de restauración y reparación de construcciones existentes, así como la conservación y mantenimiento de los elementos construidos.","B":"Incluidas las de restauración y reparación de construcciones existentes, pero no la conservación y mantenimiento de los elementos construidos.","C":"Salvo las de restauración y reparación de construcciones existentes, así como la conservación y mantenimiento de los elementos construidos.","D":"Incluida la conservación y mantenimiento de los elementos construidos, pero no las de restauración y reparación de construcciones existentes."},"correct":"A","explanation":null,"page":null},{"number":51,"question":"Según lo establecido en el artículo 62 dela Ley 9/2017 de 8 de noviembre, de Contratos del Sector Público, los órganos de contratación deberán designar un responsable del contrato al que corresponderá supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias con el fin de asegurar la correcta realización de la prestación pactada. El responsable del contrato:","options":{"A":"Debe ser una persona física o jurídica, vinculada al órgano de contratación del contrato.","B":"Debe ser una persona física o jurídica, vinculada al órgano gestor del contrato.","C":"Debe ser una persona física, vinculada a la entidad contratante.","D":"Podrá ser una persona física o jurídica, vinculada a la entidad contratante o ajena a él."},"correct":"D","explanation":null,"page":null},{"number":52,"question":"De acuerdo con el artículo 101 de la ley 9/2017, de 8 de noviembre, de contratos del sector público que regula el valor estimado de los contratos:","options":{"A":"El método de cálculo del valor estimado de los contratos viene descrito en la ley general presupuestaria.","B":"En el cálculo del valor estimado de los contratos, nunca se toman en cuenta las prórrogas.","C":"El método de cálculo aplicado por el órgano de contratación para calcular el valor estimado del contrato, en todo caso deberá figurar en los pliegos de cláusulas administrativas particulares.","D":"El valor estimado de los contratos siempre se obtiene con el IVA incluido."},"correct":"C","explanation":null,"page":null},{"number":53,"question":"De acuerdo con lo dispuesto en la Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales, señale la respuesta correcta:","options":{"A":"El tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea mayor de catorce años.","B":"Las infracciones leves en materia de protección de datos prescribirán a los 6 meses.","C":"Tendrá la consideración de encargado del tratamiento de datos personales quien figurando como responsable utilizase los datos para sus propias finalidades.","D":"Los miembros del Consejo Consultivo de la Agencia Española de Protección de Datos serán nombrados mediante Real Decreto del Consejo de Ministros."},"correct":"A","explanation":null,"page":null},{"number":54,"question":"De acuerdo con lo dispuesto en el art 4 de la Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales y conforme al artículo 5.1 d del Reglamento (UE) 2016/679, en lo que respecta al tratamiento de datos personales, éstos serán:","options":{"A":"Exactos y, se mantendrán siempre actualizados.","B":"Exactos y, se actualizarán mensualmente.","C":"Exactos y, si fuere necesario, actualizados.","D":"Aproximados y, si fuere necesario, actualizados."},"correct":"C","explanation":null,"page":null},{"number":55,"question":"De acuerdo con el artículo 22 del Decreto 220/2014, de 12 de diciembre, del Consell, por el que se aprueba el Reglamento de Administración Electrónica de la Comunitat Valenciana, para la creación de sedes electrónicas derivadas, se necesitará un informe previo del órgano directivo con competencias horizontales en materia de tecnologías de la información y las comunicaciones, que será:","options":{"A":"Informe facultativo y vinculante.","B":"Informe preceptivo y vinculante.","C":"Informe facultativo y no vinculante.","D":"Informe preceptivo y no vinculante."},"correct":"B","explanation":null,"page":null},{"number":56,"question":"De acuerdo con lo establecido en la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, ¿A quien le corresponde efectuar o autorizar, en su caso, los nombramientos del personal funcionario y la contratación del personal laboral, de acuerdo a lo establecido reglamentariamente?","options":{"A":"Al President de la Generalitat.","B":"Al Consell.","C":"Al conseller o consellera competente en materia de función pública.","D":"Al Director General competente en materia de función pública."},"correct":"C","explanation":null,"page":null},{"number":57,"question":"Según el artículo 80 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana además de los días por asuntos particulares que se establezcan, el personal funcionario tendrá derecho al disfrute de:","options":{"A":"Tres días adicionales al cumplir el sexto trienio, incrementándose en un día adicional por cada trienio cumplido a partir del octavo.","B":"Dos días adicionales al cumplir el sexto trienio, incrementándose en un día adicional por cada trienio cumplido a partir del octavo.","C":"Dos días adicionales al cumplir el sexto trienio, incrementándose en dos días adicionales por cada trienio cumplido a partir de octavo.","D":"Dos días adicionales al cumplir el quinto trienio, incrementándose en un día adicional por cada trienio cumplido a partir del octavo."},"correct":"B","explanation":null,"page":null},{"number":58,"question":"De acuerdo con lo establecido en el artículo 138 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, ¿cuál de las siguientes respuestas no se corresponde con una situación administrativa del personal funcionario de carrera?","options":{"A":"Excedencia voluntaria.","B":"Jubilación voluntaria.","C":"Expectativa de destino.","D":"Servicios Especiales."},"correct":"B","explanation":null,"page":null},{"number":59,"question":"Según el artículo 147 de la Ley 4/2021 de 16 de abril, de la Función Pública Valenciana, el personal funcionario de carrera podrá obtener la excedencia voluntaria por interés particular cuando haya prestado servicios efectivos en cualquiera de las administraciones públicas, organismos públicos, consorcios o universidades públicas, durante un período:","options":{"A":"Mínimo de 2 años inmediatamente anteriores.","B":"Mínimo de 3 años, que podrán ser inmediatamente anteriores o discontinuos.","C":"Mínimo de 3 años inmediatamente anteriores.","D":"Mínimo de 5 años, que podrán ser inmediatamente anteriores o discontinuos."},"correct":"C","explanation":null,"page":null},{"number":60,"question":"De acuerdo con lo dispuesto en el Decreto 42/2019, de 22 de marzo, del Consell, de regulación de las condiciones de trabajo del personal funcionario de la Administración de la Generalitat indique cuál de las siguientes afirmaciones es correcta:","options":{"A":"A los efectos de lo dispuesto en este decreto y de las normas que lo desarrollen, se entenderá por 'Tener a su cargo' mantener una relación de dependencia que implica convivencia.","B":"El personal funcionario, que por nacimiento de hijas e hijos prematuros o que por cualquier otra causa deban permanecer hospitalizado a continuación del parto, tendrá derecho a ausentarse durante un máximo de dos horas diarias percibiendo las retribuciones íntegras y a reducir su jornada de trabajo hasta un máximo de otras dos horas, con la disminución proporcional de sus retribuciones.","C":"El horario de permanencia obligatoria del personal de servicios burocráticos podrá flexibilizarse en una hora diaria, entre otros supuestos, para quienes tengan a su cuidado directo hijos o hijas, o niños o niñas en acogimiento preadoptivo o permanente, de 12 años o menores de esa edad.","D":"El personal de la Generalitat tendrán derecho a una reducción de jornada de una hora diaria sin disminución de retribuciones cuando, tratándose de una familia monoparental, tenga a su cargo, por razones de guarda legal, niñas o niños de 14 años o menores."},"correct":"B","explanation":null,"page":null},{"number":61,"question":"De acuerdo con lo dispuesto en el Decreto 42/2019, de 22 de marzo, del Consell, de regulación de las condiciones de trabajo del personal funcionario de la Administración de la Generalitat, indique cuál de las siguientes afirmaciones es correcta:","options":{"A":"Las reducciones de jornada que no comporten disminución de retribuciones serán concedidas por la dirección general competente en materia de función pública. En el caso de que sí comporten disminución de retribuciones, será el órgano competente en materia de personal de cada conselleria u organismo quien las conceda.","B":"El órgano competente en materia de personal de la conselleria o entidad en que presta servicios la persona solicitante, cuando no lo impidan las necesidades del servicio, podrá conceder licencia de hasta doce meses de duración para la realización de acciones formativas en materias directamente relacionadas con las funciones del puesto o la carrera profesional administrativa de la persona solicitante.","C":"Con una duración máxima de seis meses cada cinco años, la dirección general competente en materia de función pública, previo informe del órgano competente en materia de personal podrá conceder licencia por interés particular.","D":"Las licencias sin retribución, en cualquier caso, deberán comprender períodos continuados e ininterrumpidos. Para poder solicitar una nueva licencia será necesario que transcurran, como mínimo, tres días laborables entre el período que se solicita y el anteriormente disfrutado."},"correct":"D","explanation":null,"page":null},{"number":62,"question":"De acuerdo con lo establecido en el artículo 171 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, el incumplimiento de las normas en materia de incompatibilidades cuando no suponga el mantenimiento de una situación de incompatibilidad se considerará una falta:","options":{"A":"No está tipificada en la Ley.","B":"Leve.","C":"Muy Grave.","D":"Grave."},"correct":"D","explanation":null,"page":null},{"number":63,"question":"De acuerdo con la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones:","options":{"A":"La clasificación territorial agrupará por provincias, comarcas o municipios, los créditos asignados a los distintos centros gestores del gasto.","B":"Los capítulos se desglosarán en artículos y éstos, a su vez, en conceptos que se dividirán en subconceptos.","C":"El fondo de contingencia recogerá una dotación diferenciada que se destinará a hacer frente durante el correspondiente ejercicio a necesidades inaplazables de carácter no discrecional y no previstas, en todo o en parte, en el presupuesto inicial.","D":"Al objeto de disponer de una clasificación funcional del gasto, los créditos se identificarán funcionalmente de acuerdo a su finalidad."},"correct":"B","explanation":null,"page":null},{"number":64,"question":"De acuerdo con el artículo 38 de la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, y según la clasificación económica de los estados de ingresos de los Presupuestos de la Generalitat, en los ingresos de capital se distinguirán:","options":{"A":"Activos y pasivos financieros.","B":"Enajenación de inversiones reales y transferencias de capital.","C":"Transferencias corrientes y de capital.","D":"Inversiones reales y transferencias de capital."},"correct":"B","explanation":null,"page":null},{"number":65,"question":"Según el artículo 33 de la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones. ¿Quién acordará el límite máximo de gasto no financiero de los Presupuestos de la Generalitat para el siguiente ejercicio?.","options":{"A":"La persona titular de la conselleria con competencias en materia de hacienda, a propuesta del Consell.","B":"El Consell, a propuesta de la persona titular de la conselleria con competencia en materia de hacienda.","C":"El Consell, a propuesta del President de la Generalitat.","D":"El president de la Generalitat a propuesta de la persona titular de la conselleria con competencia en materia de hacienda."},"correct":"B","explanation":null,"page":null},{"number":66,"question":"Según en lo dispuesto en la Orden de 12 de diciembre de 1994, de la Conselleria de Economía y Hacienda, sobre gestión y registro contable de las operaciones de administración y ejecución del presupuesto de la Generalitat Valenciana, señale el documento contable que tiene por objeto reflejar el acto en virtud del cual se registran las entradas reales o virtuales de fondos en la Tesorería de la Generalitat.","options":{"A":"DRK","B":"RL","C":"IK","D":"MI"},"correct":"D","explanation":null,"page":null},{"number":67,"question":"Según el art 58 de la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, la ejecución de los créditos consignados en los presupuestos comprenderá las siguientes operaciones:","options":{"A":"Aprobación del gasto, Compromiso o disposición del gasto, Reconocimiento de la obligación y Ordenación del pago y pago material.","B":"Autorización del gasto, Compromiso o disposición del gasto, Reconocimiento de la obligación, Propuesta de pago y pago material.","C":"Autorización del gasto, Compromiso o disposición del gasto, Propuesta de pago, Ordenación del pago y pago material.","D":"Aprobación del gasto, Compromiso o disposición del gasto, Reconocimiento de la obligación, Propuesta de pago y Ordenación del pago y pago material."},"correct":"A","explanation":null,"page":null},{"number":68,"question":"Tal como indica el art 65 de la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, la gestión del presupuesto de ingresos se realizará en:","options":{"A":"Las siguientes fases sucesivas o simultáneas: Reconocimiento del derecho y Propuesta de ingreso.","B":"Las siguientes fases siempre sucesivas: Reconocimiento del derecho y Propuesta de ingreso.","C":"Las siguientes fases siempre simultáneas: Reconocimiento del derecho y Propuesta de ingreso.","D":"Las siguientes fases sucesivas o simultáneas: Reconocimiento del derecho, Liquidación del derecho y Propuesta de ingreso."},"correct":"A","explanation":null,"page":null},{"number":69,"question":"De acuerdo con la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones, el Proyecto de Ley de Presupuestos de la Generalitat, integrado por el articulado con sus anexos y los estados de gastos y de ingresos, se remitirá a Les Corts:","options":{"A":"Antes del 1 de octubre de cada año, para su examen y aprobación o, en su caso, enmienda o devolución al Consell.","B":"Antes del 1 de noviembre de cada año, para su examen y aprobación o, en su caso, enmienda o devolución al Consell.","C":"Antes del 1 de noviembre de cada año, para su examen y aprobación o, en su caso, enmienda o devolución a la Conselleria competente en materia de hacienda.","D":"Antes del 30 de noviembre de cada año, para su examen y aprobación o, en su caso, enmienda o devolución al Consell."},"correct":"B","explanation":null,"page":null},{"number":70,"question":"De acuerdo con el artículo 60 de la Ley 1/2015, de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones:","options":{"A":"Corresponde a la persona titular de cada conselleria la ordenación general de pagos en el ámbito de la Administración de la Generalitat. Para el resto de sujetos que conforman el sector público administrativo la competencia corresponderá a las personas que ostenten la presidencia o dirección.","B":"Corresponde a la persona titular de la conselleria competente en materia de hacienda la ordenación general de pagos en el ámbito de la Administración de la Generalitat y para el resto de sujetos que conforman el sector público administrativo.","C":"Corresponde a la persona titular de la conselleria competente en materia de hacienda la ordenación general de pagos en el ámbito de la Administración de la Generalitat. Para el resto de sujetos que conforman el sector público administrativo la competencia corresponderá a las personas que ostenten la presidencia o dirección.","D":"Corresponde a la persona titular de cada conselleria la ordenación general de pagos en el ámbito de la Administración de la Generalitat y para el resto de sujetos que conforman el sector público administrativo."},"correct":"C","explanation":null,"page":null},{"number":71,"question":"Según la Ley 1/2015 de 6 de febrero, de Hacienda Pública, del Sector Público Instrumental y de Subvenciones ¿quien aprueba el presupuesto de la Generalitat?","options":{"A":"El President del Consell.","B":"El Consell.","C":"La Conselleria con competencias en materia de hacienda.","D":"Les Corts."},"correct":"D","explanation":null,"page":null},{"number":72,"question":"La extensión de un archivo creado con Writer es:","options":{"A":".ODS","B":".ODT","C":".DOT","D":".DOC"},"correct":"B","explanation":null,"page":null},{"number":73,"question":"En relación a LibreOffice Writer, diga cual de las siguientes afirmaciones es correcta.","options":{"A":"LibreOffice Writer tiene diez categorías de estilos.","B":"Los estilos de párrafo afectan a párrafos completos y también se utilizan para fines como compilar una tabla de contenido.","C":"Los estilos de caracteres afectan a un sólo carácter dentro de un párrafo. Proporcionan excepciones a los estilos de párrafo.","D":"Los párrafos son los componentes básicos de cada documento aunque los encabezados, los pies de página y los elementos en listas numeradas no se consideran párrafos a estos efectos."},"correct":"B","explanation":null,"page":null},{"number":74,"question":"Indique que combinación de teclas en LibreOffice Writer muestra el cuadro de dialogo 'Buscar y Reemplazar'.","options":{"A":"Ctrl + B.","B":"Mayús + R.","C":"Ctrl + H.","D":"Ctrl + R"},"correct":"C","explanation":null,"page":null},{"number":75,"question":"Indique que combinación de teclas en LibreOffice Calc utilizaría para insertar un salto de página manual mientras escribe en una celda.","options":{"A":"Ctrl + Enter.","B":"Mayús + Enter.","C":"Alt + insert.","D":"AltGr + Enter."},"correct":"A","explanation":null,"page":null}],"2023":[{"number":1,"question":"Según el artículo 6 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, los asientos que se realicen en los registros electrónicos generales y particulares de apoderamientos deberán contener, al menos, la siguiente documentación:","options":{"A":"Nombre y apellidos o la denominación o razón social, documento nacional de identidad, número de identificación fiscal o documento equivalente del interesado.","B":"Fecha de aprobación.","C":"Período de tiempo por el cual se otorga el poder.","D":"Tipo de registro según las facultades que otorgue."},"correct":"C","explanation":null,"page":null},{"number":2,"question":"De acuerdo con el artículo 21 de la Ley 39/2015, de 1 de octubre, el plazo máximo en el que debe notificarse la resolución expresa:","options":{"A":"El fijado por la Administración reguladora del correspondiente procedimiento.","B":"No podrá exceder de seis meses, salvo que una norma con rango de Ley establezca uno menor o así venga previsto en el Derecho de la Unión Europea.","C":"Será de tres meses, cuando las normas reguladoras de los procedimientos no fijen el plazo mínimo.","D":"Será de tres meses, cuando las normas reguladoras de los procedimientos no fijen el plazo máximo."},"correct":"D","explanation":null,"page":null},{"number":3,"question":"De acuerdo con el artículo 24 de la Ley 39/2015, de 1 de octubre, el silencio administrativo en procedimientos iniciados a solicitud del interesado tendrá efecto desestimatorio en los procedimientos:","options":{"A":"Cuya desestimación tuviera como consecuencia que se transfieran al solicitante o a terceros facultades relativas al dominio privado o al servicio público.","B":"Que impliquen el ejercicio de actividades que puedan dañar el medio ambiente.","C":"De Responsabilidad Civil de las Administraciones Públicas.","D":"Relativos al Derecho de petición, a que se refiere el artículo 30 de la Constitución."},"correct":"B","explanation":null,"page":null},{"number":4,"question":"Según la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, toda notificación deberá ser cursada a partir de la fecha en que el acto haya sido dictado, dentro del plazo de:","options":{"A":"10 días.","B":"15 días.","C":"20 días.","D":"1 mes."},"correct":"A","explanation":null,"page":null},{"number":5,"question":"La motivación de los actos que pongan fin a los procedimientos selectivos y de concurrencia competitiva:","options":{"A":"Se realizará de conformidad con lo que disponga la Ley 39/2015","B":"Se realizará de conformidad con lo que dispongan las normas que regulen sus convocatorias, debiendo, en todo caso, quedar acreditados en el procedimiento los fundamentos de la resolución que se adopte.","C":"Se realizará de conformidad con lo que dispongan las normas que regulen sus convocatorias, sin necesidad de que queden acreditados en el procedimiento los fundamentos de la resolución que se adopte.","D":"No precisarán de motivación."},"correct":"B","explanation":null,"page":null},{"number":6,"question":"Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde:","options":{"A":"La fecha en que se dicten, salvo que en ellos se disponga otra cosa.","B":"El día siguiente a la fecha en que se dicten, en cualquier caso.","C":"El día siguiente a la fecha en que se dicten, salvo que en ellos se disponga otra cosa.","D":"La fecha en que se dicten, en cualquier caso."},"correct":"A","explanation":null,"page":null},{"number":7,"question":"Habrá lugar a la ejecución subsidiaria cuando se trate de actos que:","options":{"A":"Por ser personalísimos puedan ser realizados por sujeto distinto del obligado.","B":"Por no ser personalísimos no puedan ser realizados por sujeto distinto del obligado.","C":"Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado.","D":"Por ser personalísimos no puedan ser realizados por sujeto distinto del obligado."},"correct":"C","explanation":null,"page":null},{"number":8,"question":"Según el artículo 47 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, los actos de las Administraciones Públicas son nulos de pleno derecho en el caso siguiente:","options":{"A":"Los que lesionen los derechos y libertades susceptibles de amparo constitucional.","B":"Los dictados por órgano competente por razón de la jurisdicción o del territorio.","C":"Los que tengan un contenido posible de tramitar.","D":"Los que no sean constitutivos de cualquier infracción administrativa."},"correct":"A","explanation":null,"page":null},{"number":9,"question":"Según el artículo 50 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"Todos los actos anulables que, sin embargo, contengan los elementos constitutivos de otro distinto no producirán los efectos de este.","B":"Los actos anulables que, sin embargo, contengan los elementos constitutivos de otro distinto siempre producirán los efectos de este.","C":"Los actos nulos que, sin embargo, contengan los elementos constitutivos de otro distinto nunca producirán los efectos de este.","D":"Los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto producirán los efectos de este."},"correct":"D","explanation":null,"page":null},{"number":10,"question":"Según el artículo 52 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas:","options":{"A":"La Administración podrá convalidar los actos anulables, subsanando los vicios de que adolezcan.","B":"Nunca podrá convalidar un acto nulo o anulable.","C":"La Administración podrá convalidar los actos nulos o anulables, sin necesidad de subsanar los vicios de que adolezcan.","D":"La Administración podrá convalidar, a solicitud del interesado, los actos nulos subsanando los vicios de que adolezcan."},"correct":"A","explanation":null,"page":null},{"number":11,"question":"Según establece el artículo 96 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, salvo que reste menos para su tramitación ordinaria, los procedimientos administrativos tramitados de manera simplificada deberán ser resueltos en:","options":{"A":"Un mes.","B":"Sesenta días.","C":"Dos meses.","D":"Treinta días."},"correct":"D","explanation":null,"page":null},{"number":12,"question":"Si la solicitud de iniciación no reúne los requisitos que señala el artículo 66 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y, en su caso, los que señala el artículo 67 u otros exigidos por la legislación específica aplicable:","options":{"A":"Se requerirá al interesado para que, en un plazo de quince días, subsane la falta o acompañe los documentos preceptivos.","B":"Se requerirá al interesado para que, en un plazo de cinco días, subsane la falta o acompañe los documentos preceptivos.","C":"Se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos.","D":"Se le declarará directamente como desistido."},"correct":"C","explanation":null,"page":null},{"number":13,"question":"Respecto al plazo para la interposición del recurso de alzada, señale la respuesta correcta:","options":{"A":"El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos.","B":"El plazo para la interposición del recurso de alzada será de tres meses, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos.","C":"El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera presunto. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos.","D":"El plazo para la interposición del recurso de alzada será de tres meses, si el acto fuera presunto. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos."},"correct":"A","explanation":null,"page":null},{"number":14,"question":"Respecto al recurso de alzada, el plazo máximo para dictar y notificar la resolución será de:","options":{"A":"Un mes.","B":"Dos meses.","C":"Tres meses.","D":"Cuatro meses."},"correct":"C","explanation":null,"page":null},{"number":15,"question":"Respecto al trámite de audiencia recogido en el artículo 118 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, señale la respuesta correcta:","options":{"A":"Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente originario, se pondrán de manifiesto a los interesados para que, en un plazo inferior a diez días, formulen las alegaciones y presenten los documentos y justificantes que estimen procedentes.","B":"Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente originario, se pondrán de manifiesto a los interesados para que, en un plazo inferior a siete días, formulen las alegaciones y presenten los documentos y justificantes que estimen procedentes.","C":"Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente originario, se pondrán de manifiesto a los interesados para que, en un plazo no inferior a diez días ni superior a quince, formulen las alegaciones y presenten los documentos y justificantes que estimen procedentes.","D":"Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente originario, se pondrán de manifiesto a los interesados para que, en un plazo no inferior a cinco días ni superior a diez, formulen las alegaciones y presenten los documentos y justificantes que estimen procedentes."},"correct":"C","explanation":null,"page":null},{"number":16,"question":"Según el artículo 8 de la Ley 40/2015:","options":{"A":"La competencia es renunciable y se ejercerá por los órganos administrativos que la tengan atribuida como propia, salvo los casos de delegación o avocación, cuando se efectúen en los términos previstos en ésta u otras leyes.","B":"La delegación de competencias, las encomiendas de gestión, la delegación de firma y la suplencia no suponen alteración de la titularidad de la competencia ni de los elementos determinantes de su ejercicio.","C":"La titularidad y el ejercicio de las competencias atribuidas a los órganos administrativos podrán ser concentradas en otros jerárquicamente dependientes de aquellos en los términos y con los requisitos que prevean las propias normas de atribución de competencias.","D":"Si alguna disposición atribuye la competencia a una Administración, sin especificar el órgano que debe ejercerla, se entenderá que la facultad de instruir y resolver los expedientes corresponde a los órganos inferiores competentes por razón de la materia y del territorio."},"correct":"D","explanation":null,"page":null},{"number":17,"question":"La delegación de firma:","options":{"A":"Alterará la competencia del órgano delegante y para su validez no será necesaria su publicación.","B":"No alterará la competencia del órgano delegante y para su validez no será necesaria su publicación.","C":"Alterará la competencia del órgano delegante y para su validez será necesaria su publicación.","D":"No alterará la competencia del órgano delegante y para su validez será necesaria su publicación."},"correct":"B","explanation":null,"page":null},{"number":18,"question":"Según el artículo 19 de la Ley 40/2015, en caso de vacante, ausencia, enfermedad, u otra causa legal:","options":{"A":"El Presidente del órgano colegiado será sustituido por el Vicepresidente que corresponda, y en su defecto, por el miembro del órgano colegiado de mayor jerarquía, antigüedad y edad, por este orden.","B":"El Presidente del órgano colegiado será sustituido por el Vicepresidente que corresponda, y en su defecto, por el miembro del órgano colegiado de mayor antigüedad, jerarquía y edad, por este orden.","C":"El Presidente del órgano colegiado será sustituido por el Vicepresidente que corresponda, y en su defecto, por el miembro del órgano colegiado de mayor edad, jerarquía y antigüedad, por este orden.","D":"El Presidente del órgano colegiado será sustituido por el Vicepresidente que corresponda, y en su defecto, por el miembro del órgano colegiado de mayor jerarquía, edad y antigüedad, por este orden."},"correct":"A","explanation":null,"page":null},{"number":19,"question":"Según la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, son contratos de obras:","options":{"A":"Aquellos contratos que tienen por objeto la ejecución de una obra, aislada o conjuntamente con la redacción del proyecto.","B":"Aquellos contratos que tienen por objeto la adquisición de bienes consumibles.","C":"Aquellos contratos que tienen por objeto la adquisición de material informático.","D":"Aquellos contratos que tienen por objeto sustituir a la Administración en el ejercicio de sus competencias."},"correct":"A","explanation":null,"page":null},{"number":20,"question":"El contrato de concesión de servicios es aquel en cuya virtud uno o varios poderes adjudicadores encomiendan:","options":{"A":"A título oneroso a una o varias personas jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia.","B":"A título oneroso o gratuito a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia.","C":"A título oneroso a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia.","D":"A título oneroso o gratuito a una o varias personas jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia."},"correct":"C","explanation":null,"page":null},{"number":21,"question":"Respecto al perfil del contratante, la publicación de la información relativa a los contratos menores deberá realizarse, al menos:","options":{"A":"Semanalmente.","B":"Mensualmente.","C":"Trimestralmente.","D":"Anualmente."},"correct":"C","explanation":null,"page":null},{"number":22,"question":"Los precios de los contratos del sector público:","options":{"A":"Solo podrán ser objeto de revisión periódica y predeterminada en los términos establecidos en el Capítulo II, del Título III, de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público.","B":"No podrán ser objeto de revisión periódica.","C":"Serán objeto de revisión periódica y predeterminada en los términos establecidos en la legislación de la Unión Europea.","D":"Serán objeto de revisión periódica y predeterminada en los términos establecidos en la Ley de Bases de Régimen Local."},"correct":"A","explanation":null,"page":null},{"number":23,"question":"De acuerdo con lo establecido en el artículo 21 del Decreto 220/2014, de 12 de diciembre, del Consell, por el que se aprueba el Reglamento de Administración Electrónica de la Comunitat Valenciana, la sede de la Generalitat Valenciana es:","options":{"A":"Aquella dirección electrónica disponible para los ciudadanos a través de redes de telecomunicaciones cuya titularidad, gestión y administración corresponde a la Generalitat en el ejercicio de sus competencias y que la identifica cuando se relaciona por medios electrónicos con los ciudadanos y con otras administraciones públicas.","B":"Una plataforma disponible para la ciudadanía cuya gestión corresponde a la Generalitat en el ejercicio de sus competencias y que la identifica cuando se relaciona por medios electrónicos con la ciudadanía y con otras administraciones públicas.","C":"Aquella dirección electrónica disponible para los ciudadanos a través de redes de telecomunicaciones cuya titularidad, y gestión expresamente corresponde a la Generalitat en el ejercicio de sus competencias y que la identifica cuando se relaciona por medios electrónicos con los ciudadanos y con otras administraciones públicas.","D":"Aquella dirección habilitada para los ciudadanos a través de redes de telecomunicaciones cuya titularidad, gestión y administración corresponde a la Generalitat en el ejercicio de sus competencias y que la identifica cuando se relaciona por medios electrónicos con los ciudadanos y con otras administraciones públicas."},"correct":"A","explanation":null,"page":null},{"number":24,"question":"De acuerdo con lo establecido en la Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales:","options":{"A":"El tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea mayor de catorce años.","B":"El tratamiento de los datos personales de un menor de edad podrá fundarse en su consentimiento cuando sea mayor de catorce años.","C":"De conformidad con lo dispuesto en el artículo 4.11 del Reglamento (UE) 2016/679 se entiende por consentimiento del afectado toda manifestación de voluntad libre, informada e inequívoca por la que este acepta, ya sea mediante una declaración o una clara acción afirmativa, el tratamiento de datos personales que le conciernen.","D":"El tratamiento de los datos de los mayores de catorce años y menores de dieciséis años, fundado en el consentimiento, solo será lícito si consta el del titular de la patria potestad o tutela, con el alcance que determinen los titulares de la patria potestad o tutela."},"correct":"A","explanation":null,"page":null},{"number":25,"question":"Atendiendo a lo establecido en el artículo 33 de la Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales, ¿cuál de las siguientes aseveraciones es la correcta?","options":{"A":"Tendrá la consideración de encargado del tratamiento y no la de responsable quien en su propio nombre y sin que conste que actúa por cuenta de otro, establezca relaciones con los afectados, aun cuando exista un contrato o acto jurídico con el contenido fijado en el artículo 28.3 del Reglamento (UE) 2016/679. Esta previsión no será aplicable a los encargos de tratamiento efectuados en el marco de la legislación de contratación del sector público.","B":"El encargado del tratamiento determinará si, cuando finalice la prestación de los servicios del responsable, los datos personales deben ser destruidos, devueltos al encargado o entregados, en su caso, a un nuevo responsable.","C":"No procederá la destrucción de los datos cuando exista una previsión legal que obligue a su conservación, en cuyo caso deberán ser devueltos al responsable, que garantizará su conservación mientras tal obligación persista.","D":"El encargado del tratamiento deberá conservar, debidamente bloqueados, los datos en tanto pudieran derivarse responsabilidades de su relación con el responsable del tratamiento."},"correct":"C","explanation":null,"page":null},{"number":26,"question":"El personal empleado público, en el desarrollo de sus funciones, para cumplir los objetivos asignados actuará de acuerdo con:","options":{"A":"Los principios de imparcialidad, profesionalidad, seriedad, buena fe, confidencialidad, responsabilidad, ejemplaridad y honradez.","B":"Los principios de parcialidad, profesionalidad, diligencia, buena fe, confidencialidad, responsabilidad, ejemplaridad y honestidad.","C":"Los principios de imparcialidad, profesionalidad, seriedad, buena fe, confidencialidad, responsabilidad, ejemplaridad y honestidad.","D":"Los principios de imparcialidad, profesionalidad, diligencia, buena fe, confidencialidad, responsabilidad, ejemplaridad y honradez."},"correct":"D","explanation":null,"page":null},{"number":27,"question":"Respecto al Consell Assessor de la Funció Pública Valenciana, regulado en el artículo 12 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, señale la respuesta correcta:","options":{"A":"El Consell Assessor de la Funció Pública Valenciana es el órgano de consulta que tiene encomendada la selección del personal empleado público de la administración de la Generalitat.","B":"El Consell Assessor de la Funció Pública Valenciana es el órgano técnico de coordinación e información a través del cual se instrumenta la interlocución entre la conselleria competente en materia de función pública, los órganos gestores en materia de personal de los ámbitos sectoriales correspondientes a sanidad, educación y justicia, y el sector público instrumental de la Generalitat.","C":"Los informes y propuestas del Consell Assessor de la Funció Pública Valenciana tendrán carácter vinculante. De manera que quienes se aparten del criterio contenido en los mismos, deberán motivar esta decisión.","D":"Los informes y propuestas del Consell Assessor de la Funció Pública Valenciana no tendrán carácter vinculante. No obstante, quienes se aparten del criterio contenido en los mismos, deberán motivar esta decisión."},"correct":"D","explanation":null,"page":null},{"number":28,"question":"Respecto a la composición del Consell Assessor de la Funció Pública Valenciana, señale la respuesta correcta:","options":{"A":"Integran el Consell Assessor de la Funció Pública Valenciana el o la presidenta, los vocales natos y 6 vocales electivos.","B":"Integran el Consell Assessor de la Funció Pública Valenciana el o la presidenta, los vocales natos y 7 vocales electivos.","C":"Integran el Consell Assessor de la Funció Pública Valenciana el o la presidenta, los vocales natos y 8 vocales electivos.","D":"Integran el Consell Assessor de la Funció Pública Valenciana el o la presidenta, los vocales natos y 9 vocales electivos."},"correct":"D","explanation":null,"page":null},{"number":29,"question":"Serán vocales natos del Consell Assessor de la Funció Pública Valenciana, las siguientes personas:","options":{"A":"Una, en representación de la Federación Valenciana de Municipios y Provincias. Dos, en representación de las universidades públicas valencianas. Una por cada organización sindical con representación en la Mesa General de Negociación I.","B":"Una, en representación de la Federación Valenciana de Municipios y Provincias. Una, en representación de las universidades públicas valencianas. Una por cada organización sindical con representación en la Mesa General de Negociación I.","C":"Dos, en representación de la Federación Valenciana de Municipios y Provincias. Dos, en representación de las universidades públicas valencianas. Una por cada organización sindical con representación en la Mesa General de Negociación I.","D":"Dos, en representación de la Federación Valenciana de Municipios y Provincias. Una, en representación de las universidades públicas valencianas. Dos por cada organización sindical con representación en la Mesa General de Negociación I."},"correct":"A","explanation":null,"page":null},{"number":30,"question":"Las retribuciones que retribuyen la carrera administrativa, las características de los puestos de trabajo, el resultado de la actividad profesional, así como los servicios extraordinarios prestados fuera de la jornada normal de trabajo son:","options":{"A":"Retribuciones básicas.","B":"Retribuciones accesorias.","C":"Retribuciones complementarias.","D":"Retribuciones extraordinarias."},"correct":"C","explanation":null,"page":null},{"number":31,"question":"Según establece el artículo 82 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, al haber completado los veinte años de servicio, se tendrá derecho al disfrute de los siguientes días de vacaciones anuales:","options":{"A":"Veinticuatro días.","B":"Veinticinco días.","C":"Veintiséis días.","D":"Veintisiete días."},"correct":"A","explanation":null,"page":null},{"number":32,"question":"Según establece el artículo 162 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, el personal funcionario cuyo puesto de trabajo haya sido suprimido como consecuencia de la aplicación de una medida de redistribución de efectivos o de racionalización de la organización administrativa y de personal reguladas por esta ley y no hayan obtenido otro puesto de trabajo, podrá ser declarado:","options":{"A":"En situación de excedencia forzosa.","B":"En situación asimilada al servicio activo.","C":"En situación de expectativa de destino.","D":"Ninguna respuesta es correcta."},"correct":"C","explanation":null,"page":null},{"number":33,"question":"Según establece el artículo 170 de la Ley 4/2021, de 16 de abril, de la Función Pública Valenciana, se considera falta disciplinaria muy grave del personal funcionario público:","options":{"A":"El abuso de autoridad en el ejercicio del cargo.","B":"La emisión de informes manifiestamente ilegales que causen perjuicio grave a la Administración o a la ciudadanía.","C":"Intervenir en un procedimiento administrativo cuando se dé alguna de las causas de abstención legalmente señaladas.","D":"La falta de obediencia debida a las personas que sean sus superiores jerárquicos y a las que sean autoridades."},"correct":"B","explanation":null,"page":null},{"number":34,"question":"En el ámbito de la Administración de la Generalitat y de los organismos autónomos de la Generalitat, el crédito presupuestario se determina, atendiendo a la clasificación orgánica, de acuerdo a su naturaleza económica y funcional, de la forma siguiente:","options":{"A":"Para los gastos de inversiones reales: consignación por proyecto de inversión, capítulo económico y programa presupuestario.","B":"Para los gastos de activos y pasivos financieros: consignación por capítulo económico y programa presupuestario.","C":"Para los gastos de transferencias, corrientes y de capital: consignación por línea, ya sea de subvención o transferencia, capítulo económico y programa presupuestario.","D":"Para los gastos de personal: consignación por artículo económico y programa presupuestario."},"correct":"C","explanation":null,"page":null},{"number":35,"question":"Señale la respuesta correcta:","options":{"A":"Los Presupuestos de la Generalitat determinarán las obligaciones económicas y los derechos que, como máximo, pueden reconocer durante el correspondiente ejercicio la Generalitat y los sujetos que forman parte del sector público de la Generalitat.","B":"Los Presupuestos de la Generalitat constituyen la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio por cada uno de los sujetos que forman parte del sector público de la Generalitat.","C":"Los Presupuestos de la Generalitat constituyen la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio por la administración de la Generalitat.","D":"Los Presupuestos de la Generalitat no recogen los presupuestos de explotación y capital de las entidades del sector público empresarial y fundacional."},"correct":"B","explanation":null,"page":null},{"number":36,"question":"Si Les Corts no aprobaran el presupuesto de la Generalitat antes del primer día del ejercicio económico correspondiente:","options":{"A":"Se entenderá prorrogado el del ejercicio anterior hasta el ejercicio siguiente y la prórroga no afectará a los créditos para gastos correspondientes a programas o actuaciones que terminen en el ejercicio cuyos presupuestos se prorrogan.","B":"Se entenderá prorrogado el del ejercicio anterior hasta la aprobación y publicación del nuevo en el Diari Oficial de la Comunitat Valenciana y la prórroga afectará a todos los créditos incluidos en el presupuesto que se prorroga.","C":"Se entenderá prorrogado el del ejercicio anterior hasta el ejercicio siguiente y la prórroga afectará a todos los créditos incluidos en el presupuesto que se prorroga.","D":"Se entenderá prorrogado el del ejercicio anterior hasta la aprobación y publicación del nuevo en el Diari Oficial de la Comunitat Valenciana y la prórroga no afectará a los créditos para gastos correspondientes a programas o actuaciones que terminen en el ejercicio cuyos presupuestos se prorrogan."},"correct":"D","explanation":null,"page":null},{"number":37,"question":"Señale la respuesta correcta:","options":{"A":"El compromiso o disposición del gasto inicia el procedimiento de ejecución del gasto.","B":"La aprobación del gasto es el acto por el que se autoriza la realización de un gasto por cuantía cierta o aproximada, reservándose, a tal fin, la totalidad o una parte de un crédito presupuestario.","C":"La aprobación del gasto es un acto con relevancia jurídica para con terceros.","D":"El compromiso o disposición del gasto es el acto mediante el que se declara la existencia de un crédito exigible contra la Hacienda Pública de la Generalitat."},"correct":"B","explanation":null,"page":null},{"number":38,"question":"Las fases de gestión del presupuesto de ingresos son las siguientes:","options":{"A":"Compromiso de ingreso, reconocimiento del derecho y propuesta de ingreso.","B":"Reconocimiento del derecho e ingreso material.","C":"Compromiso de ingreso, reconocimiento del derecho e ingreso material.","D":"Reconocimiento del derecho y propuesta de ingreso."},"correct":"D","explanation":null,"page":null},{"number":39,"question":"El documento contable mixto que se expide para contabilizar la autorización y el compromiso de gastos sobre créditos disponibles es el siguiente:","options":{"A":"RA.","B":"ADO.","C":"T/.","D":"A."},"correct":"B","explanation":null,"page":null},{"number":40,"question":"A la apertura del ejercicio presupuestario se formalizará la proyección anual de la nómina:","options":{"A":"Mediante la contabilización de los documentos de retención de crédito correspondientes a las retribuciones del personal en los puestos ocupados.","B":"Mediante la contabilización de los documentos de autorización y disposición del gasto correspondientes a las retribuciones del personal en los puestos ocupados.","C":"Mediante la contabilización de los documentos de autorización y disposición del gasto correspondientes a las retribuciones del personal en los puestos ocupados y vacantes.","D":"Mediante la contabilización de los documentos de reconocimiento de la obligación correspondientes a las retribuciones del personal en los puestos ocupados."},"correct":"B","explanation":null,"page":null},{"number":41,"question":"En las convocatorias en régimen de concurrencia competitiva:","options":{"A":"Cuando la cuantía total máxima de las subvenciones convocadas se distribuya entre distintos créditos presupuestarios y se otorgue expresamente a dicha distribución carácter estimativo, la alteración de dicha distribución precisará de las modificaciones que procedan en el expediente de gasto antes de la resolución de la concesión.","B":"Cuando la cuantía total máxima de las subvenciones convocadas se distribuya entre distintos créditos presupuestarios y se otorgue expresamente a dicha distribución carácter estimativo, la alteración de dicha distribución precisará de nueva convocatoria.","C":"En ningún caso podrán concederse subvenciones por importe superior a la cuantía total máxima fijada en las mismas sin que previamente se realice una nueva convocatoria.","D":"La convocatoria no podrá prever que eventuales aumentos sobrevenidos en el crédito disponible posibiliten una resolución complementaria de la concesión de la subvención que incluya solicitudes que, aun cumpliendo todos los requisitos, no hayan sido beneficiarias por agotamiento del mismo."},"correct":"A","explanation":null,"page":null},{"number":42,"question":"Efectuada la apertura del presupuesto de gastos del correspondiente ejercicio, se registrarán, en la fase contable que corresponda y con carácter previo al registro de cualquier otro expediente:","options":{"A":"Los créditos derivados de sentencias judiciales.","B":"Las anualidades que, correspondiendo al ejercicio corriente, deriven de compromisos de carácter plurianual contraídos en ejercicios anteriores.","C":"Los compromisos de gasto de ejercicios anteriores que hubieran quedado pendientes de alcanzar la fase contable de reconocimiento de la obligación.","D":"Las obligaciones reconocidas pendientes de pago del ejercicio anterior."},"correct":"B","explanation":null,"page":null},{"number":43,"question":"¿Qué es lo que no incluye LibreOffice?","options":{"A":"Un procesador de texto.","B":"Un cliente de correo electrónico.","C":"Un editor de presentaciones.","D":"Entre otras clases de aplicaciones LibreOffice incorpora todas las que anteriormente se indica."},"correct":"B","explanation":null,"page":null},{"number":44,"question":"La extensión de un archivo creado con Writer:","options":{"A":".ocr","B":".odt","C":".dot","D":".doc"},"correct":"B","explanation":null,"page":null},{"number":45,"question":"¿Qué combinación de teclas hemos de pulsar si queremos realizar un atajo para cerrar una ventana en una hoja de cálculo Calc?","options":{"A":"Crtl+W","B":"Crtl+C","C":"Crtl+E","D":"Crtl+T"},"correct":"A","explanation":null,"page":null},{"number":46,"question":"Según lo establecido en la Constitución Española:","options":{"A":"El castellano es la lengua española oficial del Estado. Todos los españoles tienen el deber de conocerla y de usarla.","B":"Las demás lenguas españolas serán también cooficiales en las respectivas Comunidades Autónomas.","C":"La riqueza de las distintas modalidades lingüísticas de España es un patrimonio cultural que será objeto de especial protección.","D":"El castellano es la lengua española oficial del Estado. Todos los españoles tienen el deber de conocerla y el derecho a usarla."},"correct":"D","explanation":null,"page":null},{"number":47,"question":"Según lo establecido en el artículo 20 de la Constitución Española referente a la libertad de expresión, indique cuál de los siguientes es un derecho reconocido como derecho fundamental:","options":{"A":"Expresar y difundir libremente los pensamientos, ideas y opiniones de otras personas mediante la palabra, el escrito o cualquier otro medio de difusión.","B":"La reproducción, creación y adaptación literaria, artística, científica y técnica.","C":"La libertad de cátedra.","D":"Comunicar o recibir libremente información por cualquier medio. La ley regulará el derecho a la cláusula de conciencia y al secreto profesional en el ejercicio de estas libertades."},"correct":"C","explanation":null,"page":null},{"number":48,"question":"Según lo establecido en la Constitución Española, son fundamento del orden político y de la paz social:","options":{"A":"La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás.","B":"La dignidad de la persona, los derechos que le son inherentes, el desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás.","C":"La integridad de la persona, los derechos inviolables que le son inherentes, el desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás.","D":"La dignidad de la persona, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás."},"correct":"A","explanation":null,"page":null},{"number":49,"question":"Según el Título III de la Constitución Española, las sesiones conjuntas de las Cámaras:","options":{"A":"Serán presididas alternativamente por el Presidente del Congreso y por el Presidente del Senado.","B":"Serán presididas conjuntamente por el Presidente del Congreso y por el Presidente del Senado.","C":"Serán presididas por el Presidente del Congreso.","D":"Serán presididas por el Presidente del Senado."},"correct":"C","explanation":null,"page":null},{"number":50,"question":"Según la Constitución Española, la Ley distribuirá el número total de Diputados:","options":{"A":"Asignando un número fijo de Diputados por cada circunscripción electoral.","B":"Asignando una representación máxima inicial a cada circunscripción y distribuyendo los demás en proporción a la población.","C":"Asignando una representación mínima inicial a cada circunscripción y distribuyendo los demás en proporción a la población.","D":"Distribuyendo dicho número total en proporción a la población."},"correct":"C","explanation":null,"page":null},{"number":51,"question":"Según la Constitución Española, ¿quién proveerá a la sucesión en la Corona si se extinguen todas las líneas llamadas en derecho?","options":{"A":"El Congreso de los Diputados.","B":"El Consejo de Estado.","C":"El Senado.","D":"Las Cortes Generales."},"correct":"D","explanation":null,"page":null},{"number":52,"question":"Según el artículo 98 de la Constitución Española de 1978:","options":{"A":"El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley.","B":"El Gobierno se compone del Presidente, de los Ministros y de los demás miembros que establezca la ley.","C":"El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, y de los demás miembros que establezca la ley.","D":"El Gobierno se compone únicamente del Presidente y de los Vicepresidentes."},"correct":"A","explanation":null,"page":null},{"number":53,"question":"Según el artículo 103 de la Constitución Española de 1978, la Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de:","options":{"A":"Justicia, igualdad, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.","B":"Eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.","C":"Transparencia, eficiencia, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.","D":"Igualdad, transparencia, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho."},"correct":"B","explanation":null,"page":null},{"number":54,"question":"Según el artículo 116 de la Constitución Española de 1978, la declaración de los estados de alarma, de excepción y de sitio:","options":{"A":"No modificarán el principio de responsabilidad del Gobierno y de sus agentes reconocidos en la Constitución y en las leyes.","B":"Modificarán el principio de responsabilidad del Gobierno.","C":"Según su duración, podrán modificar el principio de responsabilidad del Gobierno.","D":"Podrán modificar el principio de responsabilidad del Gobierno y de sus agentes reconocidos en la Constitución y en las leyes."},"correct":"A","explanation":null,"page":null},{"number":55,"question":"Según establece la Constitución Española, el procedimiento judicial será:","options":{"A":"Predominantemente oral, sobre todo en materia criminal.","B":"Predominantemente escrito, sobre todo en materia civil.","C":"Predominantemente escrito, sobre todo en materia criminal.","D":"Predominantemente oral, sobre todo en materia civil."},"correct":"A","explanation":null,"page":null},{"number":56,"question":"El Presidente del Tribunal Supremo será nombrado:","options":{"A":"Por el Presidente del Gobierno, a propuesta del Congreso.","B":"Por el Rey, a propuesta del Presidente del Gobierno.","C":"Por el Congreso, a propuesta del Consejo General del Poder Judicial.","D":"Por el Rey, a propuesta del Consejo General del Poder Judicial."},"correct":"D","explanation":null,"page":null},{"number":57,"question":"Los miembros del Tribunal Constitucional serán designados por un período de:","options":{"A":"Cinco años.","B":"Cuatro años.","C":"Seis años.","D":"Nueve años."},"correct":"D","explanation":null,"page":null},{"number":58,"question":"Señale la respuesta correcta de acuerdo con el artículo 139 de la Constitución Española:","options":{"A":"Todos los españoles tienen los mismos derechos y deberes en cualquier parte del territorio del Estado.","B":"Todos los ciudadanos tienen los mismos derechos y deberes en cualquier parte del territorio del Estado.","C":"Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado.","D":"Todos los ciudadanos tienen los mismos deberes y obligaciones en cualquier parte del territorio del Estado."},"correct":"C","explanation":null,"page":null},{"number":59,"question":"De las siguientes competencias, señale ¿cuál es una competencia exclusiva del Estado, recogida en el artículo 149 de la Constitución Española?","options":{"A":"Los puertos de refugio, los puertos y aeropuertos deportivos y, en general, los que no desarrollen actividades comerciales.","B":"Legislación sobre propiedad intelectual e industrial.","C":"Asistencia social.","D":"La pesca en aguas interiores, el marisqueo y la acuicultura, la caza y la pesca fluvial."},"correct":"B","explanation":null,"page":null},{"number":60,"question":"Según el artículo 153 de la Constitución Española, el control de la actividad de los órganos de las Comunidades Autónomas se ejercerá:","options":{"A":"Por el Consejo Jurídico Consultivo, el relativo a la constitucionalidad de sus disposiciones normativas con fuerza de ley.","B":"Por el Consejo de Estado, el del ejercicio de funciones delegadas a que se refiere el apartado 2 del artículo 150.","C":"Por la jurisdicción civil, el de la administración autónoma y sus normas reglamentarias.","D":"Por el Tribunal de Cuentas, el económico y presupuestario."},"correct":"D","explanation":null,"page":null},{"number":61,"question":"Son funciones de Les Corts:","options":{"A":"Ejercer el control parlamentario sobre la acción de la Administración situada bajo la autoridad de la Generalitat.","B":"Presentar ante la Mesa del Congreso proyectos de ley y nombrar a los Diputados encargados de defenderlas.","C":"Solicitar al Gobierno del Estado la adopción de proposiciones de ley.","D":"Elaborar los convenios y los acuerdos de cooperación con el Estado y con las demás Comunidades Autónomas."},"correct":"A","explanation":null,"page":null},{"number":62,"question":"Según el artículo 9 del Estatuto de Autonomía de la Comunitat Valenciana:","options":{"A":"Sin perjuicio de lo que dispone la legislación básica del Estado, una Ley de Les Corts regulará el acceso a una buena administración y el acceso a los documentos de las instituciones y administraciones públicas y privadas valencianas.","B":"Todos los ciudadanos tienen derecho a que las administraciones públicas de la Generalitat traten sus asuntos de modo equitativo y parcial y en un plazo razonable, y a gozar de servicios públicos de calidad.","C":"Los ciudadanos valencianos tendrán derecho a dirigirse a la Administración de la Comunitat Valenciana en cualquiera de sus dos lenguas oficiales y a recibir respuesta en la misma lengua utilizada.","D":"Todos los ciudadanos tienen derecho a participar únicamente de forma individual en la vida política, económica, cultural y social de la Comunitat Valenciana."},"correct":"C","explanation":null,"page":null},{"number":63,"question":"Según el artículo 29 del Estatuto de Autonomía de la Comunitat Valenciana:","options":{"A":"El Consell es el órgano colegiado de gobierno de la Generalitat, que ostenta la potestad legislativa y reglamentaria.","B":"Los miembros del Consell que reciben el nombre de Consellers son designados por el President de Les Corts.","C":"Los organismos, servicios y dependencias del Consell se podrán establecer en diferentes lugares del territorio de la Comunitat Valenciana, de acuerdo con criterios de centralización y coordinación de funciones.","D":"Todas las normas, disposiciones y actos emanados del Consell, que por su naturaleza lo exijan, serán publicados en el 'Diario Oficial de la Generalitat' en las dos lenguas oficiales."},"correct":"D","explanation":null,"page":null},{"number":64,"question":"La Generalitat tiene competencia exclusiva sobre:","options":{"A":"Pesca en aguas exteriores, marisqueo, acuicultura, caza y pesca fluvial y lacustre.","B":"Archivos, bibliotecas, museos, hemerotecas y demás centros de depósito de titularidad estatal.","C":"Promoción de la mujer.","D":"Casinos, juego y apuestas deportivas y benéficas."},"correct":"C","explanation":null,"page":null},{"number":65,"question":"Según la Ley 5/1983, de 30 de diciembre, del Consell, al President de la Generalitat, como más alto representante de la Comunitat Valenciana, le corresponden las siguientes funciones:","options":{"A":"Solicitar de las Cortes Generales, previo acuerdo del Consell, la facultad de dictar normas legislativas en materias de competencia estatal, de conformidad con el artículo 150.1 de la Constitución y el artículo 60.1 del Estatut d'Autonomia de la Comunitat Valenciana.","B":"Mantener las relaciones con las otras Instituciones de la Generalitat, sin perjuicio de las facultades atribuidas al respecto a los consellers.","C":"Firmar los Convenios y Acuerdos de colaboración con la Administración del Estado y las demás Comunidades Autónomas.","D":"Fomentar las peculiaridades del pueblo valenciano y solicitar la participación de los valencianos en la vida política, económica, cultural y social."},"correct":"D","explanation":null,"page":null},{"number":66,"question":"Según el artículo 16 de la Ley 5/1983, de 30 de diciembre, del Consell, en materia de política general de la Generalitat, corresponden al Consell las siguientes competencias:","options":{"A":"Nombrar y separar a los altos cargos de la Administración de la Generalitat, a propuesta del conseller correspondiente.","B":"Ejercer las competencias en materia de acción interior atribuidas por el artículo 62 del Estatut d'Autonomia.","C":"La planificación y desarrollo de la política valenciana.","D":"Determinar las directrices de la acción de gobierno, de acuerdo con lo que establezca al respecto el President de Les Corts."},"correct":"C","explanation":null,"page":null},{"number":67,"question":"De acuerdo con lo establecido en el artículo 51 de la Ley 5/1983, de 30 de diciembre, del Consell, el President de la Generalitat:","options":{"A":"Previa deliberación de Les Corts puede plantear al Consell, la cuestión de confianza sobre su programa, una decisión política o un proyecto de Ley, conforme se establece en el artículo 30 del Estatut d'Autonomia.","B":"Previa deliberación del Consell puede plantear ante Les Corts, la cuestión de confianza sobre su programa, una decisión política o una proposición de Ley, conforme se establece en el artículo 30 del Estatut d'Autonomia.","C":"Previa deliberación de Les Corts puede plantear al Consell, una moción de censura sobre su programa, una decisión política o un proyecto de Ley, conforme se establece en el artículo 30 del Estatut d'Autonomia.","D":"Previa deliberación del Consell puede plantear ante Les Corts, la cuestión de confianza sobre su programa, una decisión política o un proyecto de Ley, conforme se establece en el artículo 30 del Estatut d'Autonomia."},"correct":"D","explanation":null,"page":null},{"number":68,"question":"Los consellers, como miembros del Consell y jefes de Departamento, tienen entre otras la siguiente función:","options":{"A":"Determinar las directrices de la acción de gobierno.","B":"Suscribir convenios y acuerdos de cooperación con el estado.","C":"Formular motivadamente el anteproyecto de Presupuesto de la Conselleria.","D":"Participar en la fijación de demarcaciones correspondientes a los Registros de la Propiedad y Mercantiles."},"correct":"C","explanation":null,"page":null},{"number":69,"question":"Constituye una función del President de la Generalitat:","options":{"A":"Nombrar y separar a los altos cargos de la Generalitat, a propuesta del conseller correspondiente.","B":"Proponer a Les Corts la reforma del Estatut d'Autonomia de la Comunitat Valenciana.","C":"Emitir deuda pública para gastos de inversión, previo acuerdo de Les Corts.","D":"Nombrar, entre los vicepresidentes o los consellers, un secretario del Consell, para que ejerza las funciones establecidas en la Ley del Consell."},"correct":"D","explanation":null,"page":null},{"number":70,"question":"No es una función del Consell en materia normativa, concretada en la siguiente competencia:","options":{"A":"Dictar decretos legislativos en los términos y con las formalidades previstas en la Ley del Consell.","B":"Nombrar y separar a los consellers.","C":"Ejercer la potestad reglamentaria de acuerdo con la Constitución Española, el Estatut d'Autonomia de la Comunitat Valenciana y las leyes.","D":"Emitir deuda pública para gastos de inversión, previo acuerdo de Les Corts."},"correct":"B","explanation":null,"page":null},{"number":71,"question":"El Consejo Europeo se reunirá:","options":{"A":"Una vez al año.","B":"Dos veces al año.","C":"Una vez por trimestre.","D":"Dos veces por semestre."},"correct":"D","explanation":null,"page":null},{"number":72,"question":"En la Unión Europea, ¿quién velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones en virtud de éstos?","options":{"A":"El Parlamento.","B":"El Consejo.","C":"La Comisión.","D":"El Tribunal de Justicia."},"correct":"C","explanation":null,"page":null},{"number":73,"question":"El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de:","options":{"A":"750, con el Presidente.","B":"750, más el Presidente.","C":"736, con el Presidente.","D":"736, más el Presidente."},"correct":"B","explanation":null,"page":null},{"number":74,"question":"Según el artículo 13 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:","options":{"A":"De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad en cualquier tipo de procedimiento judicial.","B":"De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad, en todo caso.","C":"De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a la persona demandante probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad.","D":"De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad, salvo en los procesos penales."},"correct":"D","explanation":null,"page":null},{"number":75,"question":"Según el artículo 3 de la Ley 9/2003, de 2 de abril, de la Generalitat, para la igualdad entre mujeres y hombres:","options":{"A":"Las actuaciones reguladas están referidas solamente a las nuevas medidas que se implementen, ya sean promovidas o realizadas por personas físicas o jurídicas, de naturaleza pública o privada.","B":"Las actuaciones reguladas están referidas tanto a las nuevas medidas que se implementen como a las que actualmente se están realizando, así como las que ya existen en materia de igualdad de oportunidades entre mujeres y hombres, ya sean promovidas o realizadas por personas físicas o jurídicas, de naturaleza pública o privada.","C":"Las actuaciones reguladas están referidas tanto a las nuevas medidas que se implementen como a las que actualmente se están realizando, así como las que ya existen en materia de igualdad de oportunidades entre mujeres y hombres, ya sean promovidas o realizadas por personas jurídicas, de naturaleza pública o privada.","D":"Las actuaciones reguladas están referidas tanto a las nuevas medidas que se implementen como a las que actualmente se están realizando, así como las que ya existen en materia de igualdad de oportunidades entre mujeres y hombres, ya sean promovidas o realizadas por personas físicas o jurídicas, de naturaleza pública."},"correct":"B","explanation":null,"page":null}]};
